window.HARDTRP.receive("130271",[[130272,"2026-07-26T07:53:01",9,"Начало темы.\n\nHard Master — Дм этой темы.",130271,null],[130342,"2026-07-26T17:07:02",9,"// @dunchev @Jak_Zak @Meokala @Toix21 представьте ваших персонажей и киньте их арт. После я отпишу первый пост и погнали",130271,null],[130345,"2026-07-26T17:08:10",49,"Кши Тек, арбалетчик воин, держится немного отдаленно изучая вас. Судя по всему, не агрессивен.",130271,null],[130349,"2026-07-26T17:09:34",21,"Матерый Наемник Варг, тщательно осматривает территорию и немного бурчит под нос:\n\"И снова?\"",130347,null],[130350,"2026-07-26T17:09:43",17,"Фауст. Зимний эладрин. Рядом ходит ледяной клон. Общается жестами и телепатией.",130271,null],[130354,"2026-07-26T17:13:15",42,"Люциус, Химера что была ранее аасимаром. Теперь его знакомые видят что гитара его старала целой и излучает магию",130271,null],[130355,"2026-07-26T17:13:56",9,"//Пиздец его покорёжило, не настолько я расчитывал, но ладно)",130354,null],[130356,"2026-07-26T17:14:41",9,"//По задумке изначально он сохранил околочеловеческий, но похоже оно сверху еще и мутиповало)",130271,null],[130357,"2026-07-26T17:15:10",42,"// да пох уже. Нейронка не умеет химер генерить",130271,null],[130358,"2026-07-26T17:15:48",9,"//Короче, доя всех, он не настолько монстряка и больше напоминает человека)",130354,null],[130359,"2026-07-26T17:16:08",17,"/ Да какая разница с нами уже три крин",130271,null],[130360,"2026-07-26T17:16:17",17,"/ Одним жуком больше одним меньше",130271,null],[130362,"2026-07-26T17:16:28",17,"/ Обожаю жуков",130271,null],[130363,"2026-07-26T17:16:31",9,"//Тогда пусть как хочет, ладно. Буду писать первон сообщение ^^",130359,null],[130364,"2026-07-26T17:16:41",9,"//Давить?)",130362,null],[130365,"2026-07-26T17:16:46",17,"/ Ты что",130271,null],[130376,"2026-07-26T17:31:09",9,"//Примерное нахождение хутора/деревушки \"Малые вершки\"",130271,null],[130377,"2026-07-26T17:32:38",9,"*Кто вы? Откуда? Вас привела нажива. Знакомые через старые связи предложили вам работёнку, не пыльную, притащить воды из одного горного источника. Платили много (400 золотых каждому), это было опасно, но вы согласились так или иначе.*\n\n*По условиям надо ожидать связного в глухом хуторе, у самого Изголовья драконьих гор.*\n\n*Земли Вальдхейма полно Орков разного рода, среди них зверолюды, полурослики и прочие жили мирно рядом с обычными людьми, на разумных представителей разных рас реагировали нормально.*",130271,null],[130380,"2026-07-26T17:34:33",9,"*Хутор \"Малые вершки\", селяне, обычные люди, животные топтали широкие сельские тропы. Свежий воздух, пахнет свежевырванной травой, на обочине коровья лепёшка, растёт подорожник. Редкие домики, семей 30? 40? Около того, и в этом месте вам надо ждать человека.*\n\n*Утро, крестьяне перестают заниматься своими делами рассматривая таких редких гостей — путников гадая мимоходом ли они или привнесут новые слухи.  В этом месте немного развлечений.*",130271,null],[130381,"2026-07-26T17:35:04",49,"—Клик...\n*Три крин сказал что то на три кринском, осматривая союзников*",130377,null],[130387,"2026-07-26T17:40:52",9,"*Герои собрались возле того что казалось центром хутора, деревянного колодца-журавля. Местные пока осторожничали и не говорили с незнакомцами, все здесь скорей всего по одному, вас предупреждали о том что задание опасное и будете не одни.\"",130271,null],[130388,"2026-07-26T17:41:06",17,"Фауст смотрит на три крина и не понимая что он говорит телепатически на общем ему передает \n\n\"Приветствую. Вижу у тебя такая же листовка. Вода с горы за четыре сотни. Ты меня понимаешь?\"",130271,null],[130390,"2026-07-26T17:42:44",49,"—\"О, ты тоже телепат? Удивительно. Да, я вас понимаю\"\n*Он кивает мужчине, продолжая осмотр*",130388,null],[130391,"2026-07-26T17:45:12",9,"// Три крин и Фауст, 😏👌\nА остальная группа смотрит как 2 чела общаются у себя в голове ^^",130271,null],[130392,"2026-07-26T17:46:03",49,"// выглядит как битва стенд юзеров",130391,null],[130394,"2026-07-26T17:49:35",17,"\"Да у нас в клане это передается по крови. Как тебя зовут. Меня Фауст. Я сражаюсь на передовой и в тылах, если что прикрою\"",130390,null],[130395,"2026-07-26T17:50:04",49,"—\"А у нас это с рождения. Я Кши Тек, буду стоять сзади.\"",130394,null],[130396,"2026-07-26T17:50:52",49,"—\"Не думаешь, что стоит поговорить с остальными?\"\n—Клик.",130271,null],[130398,"2026-07-26T17:51:39",17,"\"Да они что то молчат. Может немые.\"\n\nФауст каждому в голову передает\n\n\"Привет. Готовы подзаработать?\"",130271,null],[130401,"2026-07-26T17:53:44",49,"—Клик.\n*Кши Тек проверяет колчаны с болтами и свой арбалет*",130271,null],[130403,"2026-07-26T17:56:39",21,"Варг, видя довольно неловкое молчание меж отрядом, ищет примечательных личностей что бы найти работы.",130271,null],[130404,"2026-07-26T17:57:21",42,"°люц лишь осматривал окрестности и что-то интересное искал своими глазами°",130271,null],[130406,"2026-07-26T17:58:28",49,"// Шота тухленько игра идёт",130271,null],[130407,"2026-07-26T17:58:41",49,"// за час полтос сообщений",130271,null],[130408,"2026-07-26T17:59:37",9,"*Дома, дома, на вас смотрят крестьяне. И кажется кто-то идет прямо к вам, старик в расшитой рубахе был слишком примечательный, кажется староста.*",130404,null],[130409,"2026-07-26T18:00:17",21,"—?..Чего хотел, старче?\nВарг осматривает его с головы до пят, оценивая состояние.",130408,null],[130410,"2026-07-26T18:01:00",9,"*За лесополосой у огородов под домами выглядывает мельница. Она стоит на небрльшом поле. А так место выглядит свежо и тихо.*",130271,null],[130411,"2026-07-26T18:02:11",42,"// я сегодня не смогу. Извиняйте. Переместили меня в экзаменаторы, теперь надо принимать курсантов",130271,null],[130412,"2026-07-26T18:02:34",21,"Ну, значит все сегодня?",130271,null],[130413,"2026-07-26T18:04:10",9,"Староста (Григорий) — Здравствуйте путники дорогие. — *Он явно при параде, кланяется низко, его длинная борода почти достала до земли когда он нагнулся.* — Вы к нам по делу аль мимоходом? Коли надо где заночевать найду избу пустую.",130409,null],[130414,"2026-07-26T18:04:50",9,"//Ну, мне в начале все нужны и на второй половине игры. Прийдется отложить тогда.",130412,null],[130415,"2026-07-26T18:05:13",21,"Очень жаль.",130414,null],[130421,"2026-07-26T18:18:04",17,"Фауст показывает старосте листовку с заказом. Добыть воды за четыре сотни.\n\n\"Мы по этому делу.\"",130271,null],[130669,"2026-07-26T22:07:36",42,"// если что я тут и свободен сейчас и всë завтра",130271,null],[130670,"2026-07-26T22:07:45",17,"/ Круто",130271,null],[130671,"2026-07-26T22:08:34",17,"В голове у Луца возникает голос знакомого эладрина\n\n\"Луц, рад видеть. Тоже подорвался на прибыльную и непыльную работу?\"",130271,null],[130672,"2026-07-26T22:10:23",42,"— Да, иногда приятно зарабатывать беззз крови и жжжжертв",130671,null],[130673,"2026-07-26T22:11:00",17,"\"Согласен. Необходимость убивать только все усложняет. И растягивает во времени.\"",130672,null],[130674,"2026-07-26T22:12:24",42,"— Зззарабатываем мы жжжже на беззззаботную жжжизнь и пускай зззадания будут такими жжжже",130271,null],[130675,"2026-07-26T22:14:00",49,"—\"Ты плохо притворяешься Три Крином\"",130674,null],[130676,"2026-07-26T22:15:32",42,"°глаза люца закатились°\n— я хочу изззбавиться от жжжучиной оболочки",130675,null],[130679,"2026-07-26T22:16:02",49,"—\"Тогда притворялся бы лучше.\"",130676,null],[130680,"2026-07-26T22:16:58",42,"— понятно. С тобою вряд ли подружжжимся\n°скептично глянул на три-крина°",130679,null],[130681,"2026-07-26T22:18:27",49,"— \"Раскусил как дешевку, жук переросток\"",130680,null],[130683,"2026-07-26T22:24:11",42,"°покрутил когтем у виска подойдя к Фаусту и шëпотом говорит°\n— он какой-то странный и психованный, этот мерзкий таракан",130271,null],[130684,"2026-07-26T22:25:01",49,"—\"А я знал, что ты можешь говорить нормально\"",130683,null],[130685,"2026-07-26T22:26:25",42,"— поебать, пойду пожжжжую\n°хавает сырое мяско из обëртки°",130684,null],[130686,"2026-07-26T22:26:53",49,"—\"Поделись!\"",130685,null],[130687,"2026-07-26T22:29:15",42,"°смотрит на него глазами словно у якута и думает. Делиться добром или нет°\n— ну и с чего бы? Ты ко мне был очень ззззол и подозззрителен",130271,null],[130688,"2026-07-26T22:32:02",49,"—\"Я не потерплю попыток мимикрии под свою расу, что и так почти истреблена, ты оскорбляешь наше суще...существование!\"\nОн явно тупой'",130687,null],[130689,"2026-07-26T22:33:24",42,"— Ага, и специально умер от жжжука паразззита. И чтобы востать мой покровитель объединил тело с тварью чтобы я жжжил. Я наоборот хочу изззбавиться от этой оболочки",130688,null],[130690,"2026-07-26T22:36:08",49,"—\"Так ты же...поделишься?\"",130689,null],[130691,"2026-07-26T22:36:51",42,"— настырный какой.. \n°отдал половину таракану°",130271,null],[130692,"2026-07-26T22:37:12",9,"//Отлично, подружитесь, а я пока ирл допилю, дел мне притащили на ночь глядя",130271,null],[130693,"2026-07-26T22:37:19",49,"Кши Тек моментально начал быстро есть поданное, осматривая городок",130271,null],[130698,"2026-07-26T22:58:05",17,"\"Да? А мне показался нормальным жуком. Не вижу проблем.\"",130683,null],[130699,"2026-07-26T22:58:59",17,"Фауст обращается в наемнику с щитом\n\n\"Тебя эти жуки не напрягают? Меня кстате Фауст зовут. А тебя как боец?\"",130271,null],[130700,"2026-07-26T23:02:05",21,"—Ты ко мне? Я Варг, ваша защита. Постараюсь стоять впереди и принимать как можно больше ударов, просто держитесь поближе.\nОн кивает на немаленький щит, предназначенный явно не для защиты 1 существа, и сам мужчины в целом выглядит очень крепким.",130699,null],[130701,"2026-07-26T23:09:12",41,"( Фауст в мужской компании аж разговорился",130271,null],[130702,"2026-07-26T23:10:35",42,"// завидно)",130701,null],[130703,"2026-07-26T23:17:09",9,"//Поставьте реакцию, если все ещё тут? Только освободился.",130271,null],[130706,"2026-07-26T23:50:46",17,"/ я уж засыпаю",130271,null],[130887,"2026-07-27T11:37:22",42,"// я если чё готов",130271,null],[130924,"2026-07-27T14:41:37",9,"//Тоже жду вас, давно",130271,null],[130927,"2026-07-27T14:48:52",42,"// я сам жду",130271,null],[131690,"2026-07-28T15:46:14",9,"// @dunchev @Meokala @Toix21 @Jak_Zak когда мы там собираемся?",130271,null],[131693,"2026-07-28T15:48:07",42,"// ну я свободен только вечером",130271,null],[131694,"2026-07-28T15:48:43",17,"Я до 17 00 тут потом по ситуации",131690,null],[131718,"2026-07-28T16:06:30",49,"Не знаю, готовлю игру",131690,null],[132468,"2026-07-30T13:34:05",17,"// Такс ну чего, давайте реакты кто будет играть и пошлите играть, сидеть уже надоело",130271,null],[132469,"2026-07-30T13:35:33",42,"// согласен",130271,null],[132470,"2026-07-30T13:37:36",42,"— какой-то он слишком. Жжжучинный\n°доедает свой кусок мяска°",130698,null],[132471,"2026-07-30T13:38:29",17,"\"Не то, что ты, хех. Откуда такой красавец? На трикрина вон того не похож. Или у вас, у жуков разные виды есть?\"",132470,null],[132472,"2026-07-30T13:40:50",42,"— Я Химера, не по своей воли. Но благодаря этому сливанию я и жжживой. Мой покровитель\n°достал гитару°\n— соеденив органы мои и жжжжука паразззита дал мне второй шанс на жжжизнь",132471,null],[132473,"2026-07-30T13:41:59",17,"\"Интересно, ты умирал чтле и тебя скрестили с жуком чтоб выжить? А кто твой покровитель? Дьявол какой то?\"",132472,null],[132474,"2026-07-30T13:42:43",42,"— да вот он мой покровитель, у меня с ним контракт\n°тыкаю когтями на гитару°",132473,null],[132475,"2026-07-30T13:43:19",17,"\"О как, покровитель сидит в этой гитаре? Он маленький чтоле как жук? Можно на него посмотреть?\"",130271,null],[132476,"2026-07-30T13:44:26",42,"— азаззазаззз.. Смешно, нет. Это дух одинокого воина в гитаре, который жжжажжждет чего-то, а вот что именно мне не изззвестно. Но видно он был могущественный воином если смог поместить душу в предмет",130271,null],[132477,"2026-07-30T13:52:33",17,"Фауст почесал затылок и задумался\n\n\"Да, душу в предмет перенёс это сильно. Значит у него незаконченое дело или вроде того. Ну, разберёшься по ходу пьессы. Сейчас нам стоит заработать деньжат, судя по объявлению дельце плёсове, а награда выше среднего, я бы сказал жирная. Стоит расспросить старика в чем тут подвох. Давай я начну\"",130271,null],[132478,"2026-07-30T13:53:09",17,"Фауст подходит к старосте и мысленно задаёт вопрос, который звучит у него в голове\n\n\"В чем подвох по задаче, что вам нужно конкретно. Вода с горного источника или что?\"",130271,null],[132491,"2026-07-30T14:40:53",9,"//Такс, кто тут?",130271,null],[132492,"2026-07-30T14:44:11",17,"/ Я и Жака",130271,null],[132493,"2026-07-30T14:47:19",9,"// ммммм",130271,null],[132507,"2026-07-30T15:43:55",42,"// ммммммммммм",130271,null],[132615,"2026-07-30T19:16:00",21,"Я свободна, тоикс ушел, в теории можем сыграть?",130271,null],[132616,"2026-07-30T19:16:24",17,"/ я тож + - свободен",130271,null],[132617,"2026-07-30T19:16:31",17,"/ @Jak_Zak Hard",130271,null],[132618,"2026-07-30T19:16:36",21,"Остался Жак",130271,null],[132619,"2026-07-30T19:22:03",42,"// да я тут тута",130271,null],[132620,"2026-07-30T19:25:34",17,"\"Варг, знакомая у тебя физиономия. Мы раньше не встречались?\"",130700,null],[132621,"2026-07-30T19:26:34",21,"—Не думаю. Я тут не так давно, что бы мы были знакомы.",132620,null],[132622,"2026-07-30T19:27:24",17,"\"Я много где путешествовал. В этом краю я тоже впервые. Ну ладно. Обознался видать\"",132621,null],[132623,"2026-07-30T19:29:53",9,"*Дед чешет голову, пытаясь понять действительно ли он слышит Фауста или ему показалось. Он слышал его или нет? Или слышал но нет.*\n\nСтароста (Григорий) — Фейской колдунство. — *Бормочет он под нос, а после отвечает.* — Давеча не знаю как к источнику пойти. Бывает тут иногда человек, приводит наёмников и посылает в горы. Сам не знаю где искать.\n\n*Дед лишь развёл руками.*\n\nСтароста (Григорий) — О, вспомнил. — *Дед хлопнул себя по лбу.* — Горн знает где источник, наверное. Он мамке своей воды приносил с самих гор, две осьмицы его небыло, весь ободранный пришёл. Старуха до сих пор бегает как молодая. Толька пропал Горн, ушёл и не вернулся. Куда не знаю, как почти осьмицу нет его, жонка плачет, думает хоронить.",132478,null],[132624,"2026-07-30T19:32:26",21,"—Так значит, вы хотите что бы мы нашли Горна?",132623,null],[132625,"2026-07-30T19:32:54",21,"—Что думаете?\nОн кивает на Люца и Фауста",130271,null],[132626,"2026-07-30T19:33:36",17,"\"Надо бы с его женой поговорить. Может укажет направление куда ушел. И с его матушкой, которая молодая из за водицы волшебной стала. Посмотрим насколько.\"",132623,null],[132627,"2026-07-30T19:33:53",9,"Староста (Григорий) — Да не найдёте поди. — *Он лишь манхнул рукой.* — Давненько мужик пропал, могу ток показать где жонка его живёт, но болтать о муже не хтчет, горюет.",130271,null],[132628,"2026-07-30T19:33:53",17,"\"Подскажи мил человек. Где дом Горна?\"",130271,null],[132630,"2026-07-30T19:34:14",21,"—А где примерно пропал? В какую сторону ушел он.",132627,null],[132634,"2026-07-30T19:34:59",9,"*Дед показывает на дом у окраины и второй через два. Где дом самого Горна а где родители его.*",132628,null],[132637,"2026-07-30T19:35:48",17,"\"Пойдем с родней поговорим, может он рассказывал им байки как воду добывал. А в каждой байке доля истины может быть.",132634,null],[132638,"2026-07-30T19:36:14",9,"Староста (Григорий) — Не знаю, любил мужик сходить на охоту альрыбалку. Коли на зайца ходил, травы собирать или в реку не всегда говорит.",132630,null],[132639,"2026-07-30T19:37:08",21,"—Старче же сказал уже, не хотят они об этом молвить, но попробовать стоит. А ещё я бы табака купил...но это позже. Подождем слов этого...—он осматривает Люца—жука.",132637,null],[132640,"2026-07-30T19:37:15",21,"@Jak_Zak",130271,null],[132641,"2026-07-30T19:38:23",17,"\"Хотят не хотят а нам узнать нужно. Давайте купим чего нибудь. Молока и хлеба и с гостиницами по доброму подойдем, между делом спросим. По людски. У них и так горе\"",132639,null],[132644,"2026-07-30T19:41:28",42,"// я тут, сорян. Кушал селëдочку",130271,null],[132647,"2026-07-30T19:42:09",42,"— Думаю сойдëт, если это колдунство то это уже по моей части",132625,null],[132648,"2026-07-30T19:42:57",21,"—Тогда пройдемся по деревне. Нужно купить этих..\"Гостинцев\" и пойти к родителям Горна.",130271,null],[132651,"2026-07-30T19:43:20",9,"//Ходите ищете что купить?",130271,null],[132654,"2026-07-30T19:44:41",21,"Да. И если могу ищу табака с кресалом",130271,null],[132655,"2026-07-30T19:44:54",42,"// у меня 12 золотых)",130271,null],[132656,"2026-07-30T19:45:21",17,"Фауст ходит и каждому встречному телепатически задаёт вопрос\n\n\"Здарова отец/мать, где купить н молочка, меда да хлеба?\"\n\nВнутри смеётся от их реакции на телепатию",130271,null],[132658,"2026-07-30T19:45:37",17,"/ в деревне ты алигарх",132655,null],[132659,"2026-07-30T19:46:22",42,"°ищет мясника местного чтобы купить сырым, свежим мясцом°",130271,null],[132660,"2026-07-30T19:46:25",9,"*У местных нет места где они продают что-то. Вот с рук в руки да ещё ща деньгу? Да они сами принесут! И свежий хлеб, и молока ковш, да ходь медку.*",130271,null],[132661,"2026-07-30T19:47:26",9,"*Ты не находишь ничего такого, но у одного из домов кажется растет табак а меж табаком кустики странные, конопли какие-то.*",132654,null],[132663,"2026-07-30T19:47:50",17,"Поняв как тут дела делают. Фауст даёт девушке горсть серебра \n\n\"Принеси гостинцев добрых. Спасибо\"",130271,null],[132664,"2026-07-30T19:48:15",9,"*Мясника не видать, у окраины хутора лишь изба возле которой шкуры сохнут.*",132659,null],[132665,"2026-07-30T19:48:54",41,"( мне нравится как Фауст подстроился под говор. Соль бы вот ваще ничего разобрать не смогла",130271,null],[132666,"2026-07-30T19:49:18",41,"( на корейском заговорила бы",130271,null],[132667,"2026-07-30T19:49:46",42,"°ну Люц потопал туда, в поисках мясца°",132664,null],[132668,"2026-07-30T19:50:07",17,"\"Ты куда, приятель?\"",132667,null],[132669,"2026-07-30T19:50:19",21,"—...тут легалайз?..\nВарг не обращает на это внимание, и просто следует за Фаустом, параллельно осматривая город",132661,null],[132670,"2026-07-30T19:51:13",42,"— Да я до избы со шкурами. Мне нужно мясо свежжжжее. Очень свежжжее",132668,null],[132671,"2026-07-30T19:51:32",9,"//Хутор один, изба на краю)",130271,null],[132672,"2026-07-30T19:51:50",42,"// тогда до избы)",132671,null],[132673,"2026-07-30T19:52:34",9,"*Девица захлопала глазами, икнула да кивая побежала искать гостинцев по домам.*",132663,null],[132674,"2026-07-30T19:52:59",17,"\"Кстате, спроси у хозяина что то об этом пропавшем. Если шкуры - значит охотник. Ходит по местам, знает их\"",132670,null],[132675,"2026-07-30T19:53:58",17,"Фауст ожидает девушку тут же. Чтобы она не потерялась",130271,null],[132676,"2026-07-30T19:54:09",9,"Староста (Григорий) — Вижу да без меня разберётесь. Я скажу мужикам пусть соломы постелят вон в том доме. — *Он показал на дом на окраине, пустующий.* — Таверны у нас нет, корчма и то громкое слово. Бунгаль пиво варит, все мужики у него дома сидят.",130271,null],[132677,"2026-07-30T19:55:55",9,"*До избы недалеко было, прямо там на крыльце сидел рукастый мужик и мял кожу.*",132670,null],[132678,"2026-07-30T19:56:02",42,"— Хорошо, узнаю. Ты же сам видел какой я охотник",132674,null],[132679,"2026-07-30T19:56:53",17,"\"Ты в лесу мастер, а тут горная местность. По уму нужно подойти.\"",132678,null],[132680,"2026-07-30T19:57:33",21,"—Бунгаль, говорите...а не подскажете где он?",132676,null],[132681,"2026-07-30T19:58:10",9,"*Ждать пришлось пол часа. Девушка вернулась с маленьким горшочкам мёда, свежими булками в платке что были ещё горячи и печеной картошкой. Ещё целый кувшин парного, тёплого молока. За ней увязялось несколько бабонек, стоят, поглядывают на красивого фея из-за угла. Да и сама левица красная как помидор.*\n\nДевушка — В-вот, держите. — *Крутит пальцем волосы.*",132675,null],[132684,"2026-07-30T19:59:35",9,"*Тебе староста показываеь дом с пристройкой широкой.*\n\nСтароста (Григорий) — Да вон, коли нужнг чего я тоже часто дома. — *Староста показал где кого найти и свинтил сославшись на дела, если у вес не осталось вопросов.*",132680,null],[132685,"2026-07-30T19:59:55",42,"°подхожу к мужику и сразу достал Кошель с монетами давай сразу знать с какими намерениями я пришëл°",132677,null],[132686,"2026-07-30T20:00:43",21,"—Хм...а ты популярен у девиц, Фауст.\nВарг смотрит на красную девушку, а потом на Фауста, будто оценивая их",132681,null],[132688,"2026-07-30T20:02:13",9,"*Охотник сужает глаза.*\n\nОхотник — Тьфу ты, орк. Не подходи ближе, страшный шо пиздец. — *Он наверное схватился за нож на поясе коли Люц что вытворил, но мужик не чует пока опасности.* — Хотел чего? Или свали, нервируешь ты меня.",132685,null],[132689,"2026-07-30T20:02:52",41,"Я так хочу сказать, что рядом с Фаустом женщины становятся лесбиянками, но эту шутку с натяжкой поймет только Коля",132686,null],[132691,"2026-07-30T20:03:14",42,"— Да хотел. Купить у тебя сырого свежего мяса и узззнать кое что, ты же охотник и опытный ззздесь?",130271,null],[132692,"2026-07-30T20:04:14",41,"( всё, шутки кончились",132690,null],[132693,"2026-07-30T20:04:23",21,"По моему дуэт Соль и Томы после Фауста стали явно кем то более близкими, чем знакомые или сослуживцы",132689,null],[132694,"2026-07-30T20:05:36",17,"\"Спасибо красавица. Вот тебе ещё немножко за срочность и красивые глаза\"\n\n/ в сумме 1 золотой отдал серебром",132681,null],[132695,"2026-07-30T20:06:42",17,"\"Это пока они не взглянут на мою перещитую рожу и деньга в кармане имеется.\"",132686,null],[132696,"2026-07-30T20:07:18",17,"/ Я был отвергнут, но потом обрёл любовь и умер за нее",132689,null],[132697,"2026-07-30T20:07:22",9,"Охотник — Свежего? Кабана вчера  поймали, ток поделили его уже. За свежаком выходить надо, коли лишнюю животину из леса таскать вымрет вся. — *Он посмотрел на Люца, кадется слбирался с мысдями и привыкал к внешности.* — Не подлизывайся, лучше сразу говори хотел чего?",132691,null],[132698,"2026-07-30T20:07:23",17,"/ Хорошая история",130271,null],[132700,"2026-07-30T20:07:42",21,"—Хээ..перешитую? Даже интересно кто сшивал. \nОн легко усмехается, указывая на огромный шрам на пол лица\n—И гадай что хуже!",132695,null],[132702,"2026-07-30T20:07:49",41,"( по секрету. У Фауста была конкуренция",132698,null],[132705,"2026-07-30T20:09:03",9,"*Она явно хотела что-то спросить или скащать, но краснела и не могла ничего произнести, в итоге просто ушла спрятав пунцевое лицо под вздохи старших подруг прятавшихся за углом дома. Сидеть теперь бабоньки там, обсуждают что-то.*",132694,null],[132706,"2026-07-30T20:09:11",17,"\"Это подарок на совершеннолетие от старейшин моего клана. Они называли это ритуалом свидетеля, но изгнали меня раньше чем рассказали что это за ритуал блять такой. Сволочи\"",132700,null],[132707,"2026-07-30T20:10:15",21,"—Как грустно. А мне этот шрам достался при битве с каким то наемником...говорили, сильнейший на континенте. Я, честно, все ещё жалею о том, что сколотил ту банду, отправив молодняк на верную гибель.",132706,null],[132708,"2026-07-30T20:10:19",42,"— тебе известно что-то о пропавшем? Я готов тебе выплатить за мясо и информацию 10 золотых. Я не буду подлизываться, просто хочу выполнить свою работу от вашего старейшины быстрее\n°вынул из Кошеля 2 золотых и оставил себе и предложил охотнику Кошель из 10 золотых°",132697,null],[132709,"2026-07-30T20:11:01",17,"\"Я тебя уж точно осуждать не стану, каждый крутится как может.\"",132707,null],[132710,"2026-07-30T20:11:43",21,"—Да и бессмысленно это, сам понимаю что творил, так что к обсуждениям привык давно.",132709,null],[132712,"2026-07-30T20:14:38",9,"Охотник — Пиздишь. Григорий искал его уже, я сам искал. Пропал Горн. — *Мужик явно сам учавствовал при поисках, сел на крыльце да продолжил мять кожу.* — Нет Горна в лесу, следов никаких, как сквозь землю провалился. Мы с мужиками тут каждую кочку знаем, не нашли.\n\n*На деньги он не повелся.*",132708,null],[132713,"2026-07-30T20:19:24",9,"//Ну, кто куда и что делает?",130271,null],[132714,"2026-07-30T20:20:28",42,"— ТАК! Я не понял блять?!? Я сюда притопал из не близких земель! Чтобы слышать такое обращение я не понял!! Я хотел помочь вам!\n°используется навык падшего аасимара савант смерти. Спас мудрости 14 или испуган°\n— Если ты не хочешь чтобы нашло его так и скажи! Скажи что тебе плевать на его жизнь!",132712,null],[132717,"2026-07-30T20:20:50",17,"\"Гостинцы у нас, пойдем навести матушку и жену Горна, может узнаем чего нибудь полезного. Мы с тобой правда такой вид имеем, ну прямо два пушистых котика милых. Они на нас глянут и сразу все захотят рассказать\"\n\nФауст передал часть гостинцев наемнику рядом",130271,null],[132718,"2026-07-30T20:21:19",9,"/roll 1d20+2 мудрость охотника",130271,null],[132720,"2026-07-30T20:21:47",21,"Варг берет гостинцы в руки, после чего ищет жука\n—Еще этого найти надо.",132717,null],[132721,"2026-07-30T20:22:11",42,"// тогда без преимущества",130271,null],[132722,"2026-07-30T20:22:17",21,"Тотаально похуй",132719,null],[132723,"2026-07-30T20:22:23",42,"/roll 1d20 +6 запугивание",130271,null],[132725,"2026-07-30T20:22:44",9,"Охотник — Пошёл в жопу сраный таракан! Залещь в норуиз которой вылез, мы сука искали Горна всем селом не нашли, а ну пиздуй отсюда.",132714,null],[132726,"2026-07-30T20:23:12",9,"*Бросил в Люца ссаную солёную тряпку.*",130271,null],[132727,"2026-07-30T20:23:23",21,"))",132724,null],[132728,"2026-07-30T20:23:23",17,"\"Он у охотника. А мы пока пойдем к семейству пропавшего. Согласен?\"",132720,null],[132729,"2026-07-30T20:23:38",21,"—Ну, пошли тогда.",132728,null],[132730,"2026-07-30T20:23:52",17,"И они двинулись к дому жены Горна",130271,null],[132731,"2026-07-30T20:23:56",9,"//Что бля мне могло еще выпасть 😂👍",132719,null],[132732,"2026-07-30T20:26:22",9,"*Изба относительно новая, строили наверное для молодожёнов совсем недавно. В поле у самой избы порается девушка которой немного за 20 на вид, красавица. На вас шипит огромный гусь.*",132730,null],[132735,"2026-07-30T20:26:38",9,"Гусь — Шшшшшшш... гага га!",130271,null],[132736,"2026-07-30T20:26:53",21,"—Злые же эти животные...",132732,null],[132737,"2026-07-30T20:27:08",9,"*Гусь бы наверное напал на вас, но ему мешает плетёный забор и подрезанные крылья.*",130271,null],[132738,"2026-07-30T20:27:20",17,"Фауст мгновенно реагируя на опасность ввиду гуся призывает ледяную копию перед ним в позе сидя и она делает руками \"Бу\" на гуся",130271,null],[132739,"2026-07-30T20:28:25",9,"/roll 1d20+2 атака гуся",132738,null],[132744,"2026-07-30T20:29:17",9,"*Гусь не пальцем деланный, бесстрашный, боевой!*\n\nГусь — Га га га!  — *Бьёт крыльями и пытается ущипнуть.*",130271,null],[132745,"2026-07-30T20:29:41",21,"Я хочу кинуть на запугивание гуся",130271,null],[132746,"2026-07-30T20:30:07",21,"/r 1d20+1",130271,null],[132748,"2026-07-30T20:30:11",9,"Жена Горна — Гости? Путники. — *Она вытирает лицо и подходит к забору, берет гуся на руки.* — Тише Красень, тише.",130271,null],[132750,"2026-07-30T20:30:48",9,"/roll +d20 мудрость гуся он соли не нюхал, злой вряд-ли испугается",132747,null],[132752,"2026-07-30T20:30:54",42,"— ладно.. Понял.. Извиняюсь что погорячился. Мне просто очень знакомо чувство потери и сам не смог смериться с нею до сих пор. Как понял вам нечего не известно, чтож тогда наша группа попытается найти его и надеюсь выйдет удачно",132725,null],[132753,"2026-07-30T20:31:03",17,"Гусь разбивает ледяного клона",130271,null],[132754,"2026-07-30T20:31:08",42,"/roll 1d20 +6 пиздабольство",130271,null],[132756,"2026-07-30T20:31:30",21,"С моей харей гуси должны чисто от пассивной агрессии пугаться",132751,null],[132758,"2026-07-30T20:31:42",9,"//Гусь круче чем воин эха\n🔥😎🔥\n   👉👉",132753,null],[132759,"2026-07-30T20:31:50",9,"🪿",130271,null],[132760,"2026-07-30T20:32:02",21,"Я знаю что он убил и сожрал горна",132758,null],[132761,"2026-07-30T20:32:09",17,"\"Это бешеный гусь, с такими лучше не связываться\"",130271,null],[132762,"2026-07-30T20:32:24",9,"//.",132748,null],[132764,"2026-07-30T20:33:00",21,"—Я всегда знал что птицы – злейшие существа. Так, женщина, для начала вот.\nОн протягивает ей гостинцы что они принесли, стараясь не трогать гуся",132761,null],[132766,"2026-07-30T20:34:23",17,"\"Доброго дня хозяйка. Простите что без спроса заявились. Мы слышали о вашем горе и хотим вашего мужа пропавшего поискать, может он жив ещё. Помогите уж нам пожалуйста понять куда он последний раз ушел?\"",132748,null],[132767,"2026-07-30T20:34:38",42,"// ледяной демон 0. Гусь 1",132758,null],[132768,"2026-07-30T20:35:11",17,"Фауст про себя думает\n\n\"Да, вселить ложную надежду, задобрить гостиницами и выведать все что знает.\"",130271,null],[132771,"2026-07-30T20:36:01",9,"Жена Горна — Ой спасибо. — *Она взяла подарки.* — Простите Красеня, он всегда шипит на незнакомцев.",132764,null],[132773,"2026-07-30T20:36:15",9,"//Ирл отвлекают, щас буду",130271,null],[132778,"2026-07-30T20:39:55",42,"// не забудь мой бросок балабола",132755,null],[132796,"2026-07-30T20:47:12",42,"// красень Би лайк",130271,null],[132801,"2026-07-30T20:51:11",9,"/roll 1d20+2 проницательность охотника",132755,null],[132804,"2026-07-30T20:51:33",42,"// да бля",130271,null],[132805,"2026-07-30T20:51:45",9,"Охотник — Свали отсюда уже, не отсвечивай.",130271,null],[132806,"2026-07-30T20:51:57",42,"// хард всë же продал душу за кубы",130271,null],[132807,"2026-07-30T20:52:07",42,"// и полностью походу, в отличие от меня",130271,null],[132808,"2026-07-30T20:52:12",9,"//Мне ещё 2 и 12 может выпадать",130271,null],[132809,"2026-07-30T20:53:16",42,"— да пошëл ты нахер! \n°утопал от сюда°",130271,null],[132810,"2026-07-30T20:53:21",9,"*Она закрыла лицо.*\n\nЖена Горна — Я... не хочу об этом говорить.",132766,null],[132811,"2026-07-30T20:53:42",9,"//Киньте проницательность сл 12 даже",132810,null],[132812,"2026-07-30T20:54:08",21,"/r 1d20+3",130271,null],[132816,"2026-07-30T20:55:08",9,"*Странно она себя ведет, на горюющую вдову не сильно похоже. Может скрывает что-то.*",132813,null],[132818,"2026-07-30T20:55:33",21,"—..?\nЯ знаю что гусь сожрал Горна.",130271,null],[132819,"2026-07-30T20:56:50",42,"°потопал в сторону где находится его команда°",130271,null],[132991,"2026-07-30T22:39:43",17,"/r +0 Проницательный",132811,null],[132995,"2026-07-30T22:41:38",9,"*Поведение вдовы кажется вполне нормальным.*",132992,null],[132999,"2026-07-30T22:42:27",9,"*Вдова 100% что-то скрывает. Может вина или обида, видел такое не раз.*",132818,null],[133002,"2026-07-30T22:47:17",17,"Фауст подходит и положит ей руку мягко на плечо\n\n\"Я понимаю. Это тяжело. Но мы здесь чтобы помочь. Как давно пропал ваш муж?\"",132810,null],[133003,"2026-07-30T22:47:37",17,"/r -1 Великое убеждение",130271,null],[133005,"2026-07-30T22:48:08",9,"/roll 1d20+2 злой гус )",130271,null],[133008,"2026-07-30T22:50:26",9,"*Она молчит, думает. Перед её глазами гусь захотел цапнуть Фауста, девушка лишь отошла.*\n\nЖена Горна — Простите красеня я его запру.",130271,null],[133009,"2026-07-30T22:53:18",9,"*Заперев гуся она вернулась с немного красными глазами. Поставив угощения на лавку у дома присела и сама, трёт нос, вздыхает.*\n\nЖена Горна — Я... он просто пропал, ушёл не сказав ни слова, к реке... Может в лес. Это было неделю назад. — *Закрыла лицо руками.* — Он не вернётся.",130271,null],[133424,"2026-07-31T16:29:00",21,"Так, я готова если что",130271,null],[133653,"2026-07-31T18:47:46",41,"( загадочный взгляд будущей королевы вампирши*",133424,null],[133655,"2026-07-31T18:51:30",9,"//Где вы там, котята ^^",130271,null],[133656,"2026-07-31T18:51:43",42,"// здесь только таракан",130271,null],[133657,"2026-07-31T18:52:24",17,"/ Ваще все давно тут",130271,null],[133658,"2026-07-31T18:52:49",9,"// Не правда, меня небыло",133657,null],[133659,"2026-07-31T18:53:08",17,"/ Жук уже вернулся?",130271,null],[133660,"2026-07-31T18:55:12",17,"\"Люц, а ты с животными разговаривать не умеешь? Этот гусь странный, он так защищает хозяйку, будто она ему дороже всего. Мне мать сказку рассказывала как людей в животных обращали. Целая деревня свиньями стали, может она ведьма или типо того?\"\n\nЭто слышат и Люц и Варг",130271,null],[133661,"2026-07-31T18:56:54",9,"//Персонаж спрашивает товарищей \"я хочу вырезать деревню\".\nPs: На самом деле он не спрашивал 😏👌",133660,null],[133663,"2026-07-31T18:58:38",42,"// есть животная речь колдуна",133660,null],[133664,"2026-07-31T18:58:57",42,"— да, могу болтать, а зачем именно этот гусь?",133660,null],[133665,"2026-07-31T19:00:11",17,"\"Ну знаешь, не каждый гусь может моего ледяного клона разбить. Хочу взять у него пару уроков\"",133664,null],[133668,"2026-07-31T19:02:42",42,"— ПХГ... \n°Люц ели как сдерживает смех и падает на живот бья землю в припадке смеха°\n— ААЗЗАЗАЗАЗАЗАЗА",133665,null],[133675,"2026-07-31T19:06:53",9,"Жена Горна — Я не думала что вы пришли посмеятся надо мной. — *Она всхлипнула и убежала в дом.*",130271,null],[133677,"2026-07-31T19:10:08",42,"— что за женщина? Ну ладно.. \n°встал и подошëл к гусю, кастую разговор с животными°\n— Здравствуй великий господин. Позвольте побеседовать с вами\n°медленно поклонился гусю, ибо пидоры гордые слишком°",130271,null],[133678,"2026-07-31T19:10:49",9,"*Гусь выглядывает из сарая, ограда не полностью его ограничивает, он просунул голову меж досками.*\n\nГусь — Га га га!",130271,null],[133679,"2026-07-31T19:11:29",42,"// мощный перевод. Понятно. Записываю",133678,null],[133680,"2026-07-31T19:12:13",9,"https://youtu.be/7H5ZBfMv4hU?si=efFmUZqzFNqf2yAJ",130271,null],[133682,"2026-07-31T19:12:25",9,"//Гусь в переводе, дословно",133680,null],[133683,"2026-07-31T19:12:57",42,"// походу если кастану на него корону безумия он только успокоится",130271,null],[133684,"2026-07-31T19:13:27",42,"// бля его ещë не запугать",130271,null],[133685,"2026-07-31T19:13:47",42,"// он же имун к этому?",130271,null],[133686,"2026-07-31T19:14:37",9,"//Если хочешь понять есть ли у него имун или нет кинь анализ или проницательность сл 12",133685,null],[133687,"2026-07-31T19:14:55",42,"/roll 1d20 +5 проницательность",130271,null],[133689,"2026-07-31T19:15:02",42,"// пох",130271,null],[133693,"2026-07-31T19:15:18",9,"*Гусь вообще бестрашный писец.*",133688,null],[133694,"2026-07-31T19:15:53",42,"— Слыш ты блядина пернатая. Я тебя выкуплю и сожру живьëм! УЯСНИЛ!?!",130271,null],[133695,"2026-07-31T19:16:02",42,"/roll 1d20 +6",130271,null],[133697,"2026-07-31T19:16:37",9,"/roll +d20+1 его мудрость я так понял",130271,null],[133700,"2026-07-31T19:19:20",9,"Гусь (погусиному) — \"Что ты пиздишь как дышишь? Решил ко мне лезть? Я сожрал вчера вместе с травой жуков и всю их личиночную жучиную семью, резня, умерли все. Иди нахуй, открой дверь коли такой храбрый, размажу тебя падлу мазохиста, холько лапки отлетят. Пиздеть на красавца из за забора каждый горазд!\"",133696,null],[133702,"2026-07-31T19:20:42",9,"//Ну, я видел конечно как крыса положила 3 игроков, но на этот раз это босфайт с гусём",133698,null],[133718,"2026-07-31T19:27:34",17,"/ Гусь 12 мудрости пздц",130271,null],[133719,"2026-07-31T19:34:20",42,"— а ну давай блять\n°прописываю кулаками двоечку гусю°",133700,null],[133720,"2026-07-31T19:34:33",42,"/roll 1d20 +1",130271,null],[133722,"2026-07-31T19:34:48",9,"/roll 1d20+2 контратака гуся",130271,null],[133724,"2026-07-31T19:34:55",42,"// блять. Этот гусь монстр аура",130271,null],[133725,"2026-07-31T19:35:58",9,"Гусь (погусиному) — \"Иди бл@дь сюда, решил ко мне лезть? Засранец вонючий, жри говно жук навозный...\"",130271,null],[133726,"2026-07-31T19:37:08",42,"— еб@ть ты. Слышу только га га га, з@лупа ты срущая. Не дай бог ты уже обосрался и корчишь из себя крутого",130271,null],[133727,"2026-07-31T19:37:24",42,"/roll 1d20 +1 кулаком по клюву",130271,null],[133729,"2026-07-31T19:37:40",42,"//2 урона",130271,null],[133730,"2026-07-31T19:37:46",9,"//Попал, что с уроном?",130271,null],[133731,"2026-07-31T19:37:52",42,"// 1+1",133730,null],[133732,"2026-07-31T19:38:09",42,"// я же не монах чтобы кулак наносил 1д4",130271,null],[133733,"2026-07-31T19:38:18",9,"//Хм, дай вспомнить",133731,null],[133734,"2026-07-31T19:38:53",42,"// могу ëбнуть нанесения ран",130271,null],[133735,"2026-07-31T19:39:11",42,"// думаю переживëт 3д10 +6",130271,null],[133736,"2026-07-31T19:39:49",9,"//Ну, технически ты наносишь 1+ мод силы это 0, гусю максимум обидно будет. Но у тебя есть природное оружие, когти на руках, они наносят 1д4+мод силы 😏",130271,null],[133738,"2026-07-31T19:40:19",42,"// забыл",130271,null],[133739,"2026-07-31T19:40:22",9,"//Решай, ты гусю обидно хочешь сделать или немного урона когтями?",133736,null],[133740,"2026-07-31T19:40:38",42,"// пускай обидно",130271,null],[133741,"2026-07-31T19:40:59",31,"Обидеть гуся может каждый. Переживет его ответ не каждый/",130271,null],[133742,"2026-07-31T19:41:17",9,"Гус (по гусиному) — \"Хахах, бьёшь как девчёнка\"",130271,null],[133744,"2026-07-31T19:41:35",9,"/roll 1d20+2 цап ответочка",130271,null],[133747,"2026-07-31T19:42:05",42,"// мимо",130271,null],[133749,"2026-07-31T19:42:21",9,"Гусь (по гусиному) — \"Давай, или сюда, я тебя тут порешу на месте.\"",130271,null],[133750,"2026-07-31T19:42:23",42,"// 16 кд. Я же в средних доспехах",130271,null],[133751,"2026-07-31T19:42:41",42,"/roll 1d20 +1",130271,null],[133753,"2026-07-31T19:43:18",42,"/roll 2d4 -1 что блять?!? Я тебя в потроха выпущу",130271,null],[133755,"2026-07-31T19:46:01",9,"*У гуся тяжёлая рана, останется шрам через все лицо, клюв и глаз. Он отступает в сарай.*\n\nГусь ( по гусиному) — \"Зря, очень зря. Я запомнил как ты выглядишь жук, возмездие настигнет когда не ждёшь и тебе не сдобровать...\" — *Угрозы изнутри, мгновение и тишина, гусь скрылся зализывать раны в сарае. Хоть бы не подох.*",133754,null],[133756,"2026-07-31T19:46:42",9,"*Всё это время Фауст наблюдал как Люц кричит на гуся и бьется с ним, кто кого перекрикнет около полуминуты.*",130271,null],[133757,"2026-07-31T19:47:16",42,"// чекайте он будет глав гадом этой компании. Уйдëт в качалку и изучит тëмную магию. Хард закрепи это, я уверен в этом",130271,null],[133758,"2026-07-31T19:47:51",42,"// пока во враги/фракции/союзники. Запишу. Злейший враг - Гусь красень",130271,null],[133759,"2026-07-31T19:48:05",9,"*Пару селян проходили мимо странно смотрели на это действо.*",130271,null],[133770,"2026-07-31T19:54:38",17,"/ я хз чё играть щас",130271,null],[133771,"2026-07-31T19:54:45",17,"/ зачем ты гуся отпиздил",130271,null],[133772,"2026-07-31T19:55:05",42,"// а хули он бычит на Люца",130271,null],[133773,"2026-07-31T19:55:12",42,"// Люц не терпила",130271,null],[133774,"2026-07-31T19:55:16",9,"//Спроси его как перс, идеально 👌",133771,null],[133776,"2026-07-31T19:55:51",17,"\"Фауст наблюдает краем глаза за Люцем и гусем, запоминает движения гуся\"",130271,null],[133778,"2026-07-31T19:56:24",9,"//Варга ждём наверное, надо чет думать",130271,null],[133809,"2026-07-31T21:14:06",17,"/ Жаль что этот Крит ничего не дал и девушка убежала... Я как то в тупике",133003,null],[133810,"2026-07-31T21:15:44",17,"Фауст плюнул бы, да не может\n\nПошел за девушкой которая убежала домой\n\nОн постучал аккуратно в дверь\n\nТелепатией нащупал ее сознание и тихо передал\n\n\"Простите за эту выходку моего коллеги. Он контуженный. Не принимайте на свой счёт. Мы действительно хотим помочь вам справится с горем. Пожалуйста поговорите со мной. \"",130271,null],[133811,"2026-07-31T21:19:00",9,"Жена Горна — Уходите, пожалуста. Я не хочу с вам говорить. — *Слышны всхлипы, она плачет?*",133810,null],[133812,"2026-07-31T21:27:17",17,"/r +1 Она плачет??",130271,null],[133814,"2026-07-31T21:27:42",17,"/ Ну нет так нет. Похуй",130271,null],[133815,"2026-07-31T21:27:51",17,"/ Я готов идти к матери Горна",130271,null],[133816,"2026-07-31T21:27:57",17,"/ Она же в другом доме живёт?",130271,null],[133817,"2026-07-31T21:32:07",42,"// может вырежим деревню? Не меньше опыта дадут и Лута побольше",130271,null],[133818,"2026-07-31T21:32:30",17,"/ Я не занимаюсь таким",130271,null],[133819,"2026-07-31T21:32:35",17,"/ Делай что хочешь",130271,null],[134161,"2026-08-01T11:58:09",17,"\"Варг, супруга Горна на контакт не идёт не помогли ни гостинцы ни уговоры. Может надавать на нее, ну так, легонечко.\n\nИли к матери Горна сходим? Люц пока занят, у него рамсы с гусем.\"",130271,null],[134163,"2026-08-01T12:00:00",42,"°люц отошëл от гуся и подошëл к товарищам°\n— не какой информации, только он что и говорил какое же ты ничтожество Фауст",130271,null],[134165,"2026-08-01T12:03:21",17,"\"Я догадывался, что он это и скажет\"",134163,null],[134167,"2026-08-01T12:04:10",42,"°самооценка Люца спасена что поверил Фауст его словам°",130271,null],[134171,"2026-08-01T12:08:32",21,"Зачем вы убивали гуся",130271,null],[134172,"2026-08-01T12:08:54",9,"//Лан, я тут + -",130271,null],[134173,"2026-08-01T12:08:59",42,"// он жив, просто получил мотивацию стать глав гадом",134171,null],[134174,"2026-08-01T12:08:59",9,"//Что делаете?",130271,null],[134175,"2026-08-01T12:09:11",21,"Аа, класс",134173,null],[134176,"2026-08-01T12:09:21",21,"Читаю что тут было вчера",134174,null],[134178,"2026-08-01T12:11:22",17,"/ Кто вы)) это жук",134171,null],[134182,"2026-08-01T13:46:21",17,"/ Варга жду и Люца. Предлагаю надавить на вдову. Она мутная. Или пойти в матери Горна.\n\nАльтернативно забить болт и пойти куда глаза глядят на гору. Искать источник молодости.",134174,null],[134184,"2026-08-01T13:49:43",42,"// надавим на женщину",130271,null],[135866,"2026-08-03T10:58:41",17,"\"Нет, давить не надо. Она в печали, не может успокоиться\"\n\nФауст махает рукой зовя за собой\n\n\"Пойдемте к матери Грома, спросим её и посмотрим что значит - Омолодилась после воды из горного источника.\"",130271,null],[135870,"2026-08-03T11:03:56",17,"/ @Meokala @Jak_Zak Пошлите",130271,null],[135871,"2026-08-03T11:08:49",42,"— ну ладно. Ты прав\n°потопал за Фаустом°",135866,null],[135872,"2026-08-03T11:12:25",9,"//Варг тут? Идём к мамке?",130271,null],[135873,"2026-08-03T11:12:51",21,"Да",130271,null],[135874,"2026-08-03T11:17:07",9,"*Изба мамки Горна была буквально через дом. Она зарёванная, с красными глазами старушка кое как правилась с бурьянами на своей посадке.*\n\n*Молода? На вид — нет. Сильна ли как при молодости? По ней не видно, правда работящая это точно.*\n\n*Встала и смотрит, не к ней ли вы идёте, заметила вас.*",130271,null],[135876,"2026-08-03T11:20:12",9,"//Музыка. Вайбы спокойного хутора, почти сказочная, сельская атмосфера.",135875,null],[135878,"2026-08-03T11:22:36",17,"\"Давайте вы обычным голосом окликните её, если я полезу ей телепатией в голову, старуха может напугаться и кони двинуть\"",130271,null],[135879,"2026-08-03T11:25:14",21,"—Гхм..вы хотите что бы говорил я?",135878,null],[135881,"2026-08-03T11:26:52",9,"*Старуха совсем не удивилась жуку или фею (эладрина), может всякого повидала, а может ей сейчас не до этого.*",130271,null],[135882,"2026-08-03T11:28:06",17,"\"Да, ты из нас самый привлекательный на вид и говорить умеешь. Дерзай\"",135879,null],[135883,"2026-08-03T11:29:34",21,"Варг подходит к старухе, не очень хорошо улыбаясь и начинает расспрашивать о Горне\n—Кхем...мы хотели выдвинуться на поиски вашего сына, Горна, может вы знаете что то о нем?",130271,null],[135884,"2026-08-03T11:30:20",42,"°Люц вообще молчит ибо понимает что будет если и мутант таракан тоже начнëт приставать°",130271,null],[135885,"2026-08-03T11:30:28",17,"\"Люц прикрой наш тыл от кровожадных гусей, мало ли у  того ублюдка целая гусиная банда\"",130271,null],[135886,"2026-08-03T11:31:37",42,"°люц лишь кивнул и подготавливает действие на нанесение ран первому гусю что подойдет в радиус атаки°",135885,null],[135887,"2026-08-03T11:40:53",9,"Мать Горна — Знаю всё, это мой сын. Я его родила и воспитала. — *Старуха была в скверном настроении, ещё заговорили о её сыне. Она тяжело вздохнула, оппираться небыло смысла.* — В последнее время он часто ходил на рыбалку, постоянно приносил рыбу, а после — исчез. Я слышала что у реки утопца страшного видели, не загрыз ли он его, не хочу об этом думать, \n\n*Она пустила скупую слезу.*",135883,null],[135888,"2026-08-03T11:43:44",17,"Фауст присматривается к старушке, смотрит на её микромимику, которая всегда выдаёт неумелого лжеца",130271,null],[135889,"2026-08-03T11:44:07",17,"/r +2 Проницательность",130271,null],[135891,"2026-08-03T11:44:13",17,"/База",130271,null],[135892,"2026-08-03T11:45:14",9,"*Старуха очень горюет о сыне.*",130271,null],[135893,"2026-08-03T11:46:23",9,"/roll 1d20+2 проницательность старухи, она вас оценивает для чего-то и не скрывает этого",130271,null],[135895,"2026-08-03T11:49:39",9,"Мать Горна — Подождите здесь.\n\n*Бабка отряхнула юбку и не хромая. Прошло немного времени и она выходит к вам с книгой, пером и банкой необычных чернил.*",130271,null],[135896,"2026-08-03T11:50:30",9,"Мать Горна — У меня нет ничего ценного. Но муж хотел состоять в Дикой охоте, ушёл на старости лет. Это всё что я могу дать, найдите моего сына, прошу.",130271,null],[135897,"2026-08-03T11:51:01",9,"*У старухи немного дрожат руки.*",130271,null],[135898,"2026-08-03T11:51:41",17,"Смотрю что там у неё в руках. Запоминаю \"Дикая охота\"\n\n\"Что еще за \"дикая охота\" хмммм\"",130271,null],[135899,"2026-08-03T11:53:03",9,"*Книга в красной обложке, какие-то особые чернила, свиток наверное.*\n\n//Она тебя слышит?",135898,null],[135900,"2026-08-03T11:53:17",17,"/Не, я думаю у себя в башке",130271,null],[135901,"2026-08-03T11:54:07",17,"Фауст приветливо подходит ближе к бабушке и Варгу\n\n\"Не пугайтесь, я так общаюсь. Что это за книга?\"",130271,null],[135902,"2026-08-03T11:54:52",9,"Мать Горна — Я не разбираюсь, но мой муж умел колдовать. Посмотрите если хотите. — *Дает книгу тебе.*",135901,null],[135903,"2026-08-03T11:55:04",17,"Открываю книгу",130271,null],[135904,"2026-08-03T11:56:13",9,"*Внутри формулы нескольких заклинаний и заметки о магии, а ещё кажется имя того кто написал её, \"Шеречун\".*",135903,null],[135905,"2026-08-03T11:56:22",9,"//Книга заклинаний",130271,null],[135906,"2026-08-03T11:58:08",17,"Фауст пробежавшись глазами ничего прочесть не смог. Отложил книгу в рюкзак.\n\n\"А чернила, он ими записывал?\"",130271,null],[135907,"2026-08-03T11:58:28",9,"//Тоесть ты принимаешь её?",135906,null],[135908,"2026-08-03T11:58:42",17,"/Ну я уже её открыл и забрал",130271,null],[135909,"2026-08-03T11:59:06",9,"Мать Горна — Да, это особые чернила. Заберайте всё, только найдите моего сына.",130271,null],[135910,"2026-08-03T12:00:18",17,"\"Хорошо, проверим берег, укажите куда он обычно рыбачить ходил?\"",130271,null],[135911,"2026-08-03T12:00:45",9,"/roll 3d20",130271,null],[135913,"2026-08-03T12:03:38",9,"//Раз так, то вот что она вам дала:\n\n— Книга заклинаний с тремя заклинаниями: первое ???, второе ???, третье ???. Подписанна автором \"Шеречун\".\n— Свиток заклинаний \"???\"\n— Чернила/материалы для переписывания заклинаний на 14 золотых.\n— Красивое гусиное перо с серебрянным наконечньком. Стоимость 3 золотых нетленными как произведение искуства.",130271,null],[135914,"2026-08-03T12:05:57",9,"Мать Горна — Я редко хожу с ним. — *Она покачала головой, сказать не могла, добавила грустно улыбнувшись:* — Он часто хвастался рыбными местами, спросите у Бунгаля, модет кто из знакомых знает.",135910,null],[135915,"2026-08-03T12:06:26",17,"/Дала нам, а спиздил всё я",135913,null],[135916,"2026-08-03T12:06:33",17,"/ Ну золото отдал по 7 вам",130271,null],[135917,"2026-08-03T12:06:43",42,"// оке",130271,null],[135918,"2026-08-03T12:06:54",17,"/ А не, это материалы на 14 золотых, тоже спиздил",130271,null],[135919,"2026-08-03T12:07:25",17,"\"Кто такой Бунгаль напомните пожалуйста, староста ваш?\"",130271,null],[135920,"2026-08-03T12:07:26",42,"// хорошая делëжка ребят",130271,null],[135921,"2026-08-03T12:08:04",42,"// даже советские солдаты были поскупее чем Фаус",130271,null],[135922,"2026-08-03T12:08:22",9,"//Ну, этот хочет мульту в волшебника, ему надо, вдруг 4й у меня возьмёт, хоть какие-то заклы будут у него",130271,null],[135923,"2026-08-03T12:08:44",17,"/ Люц уже получил моральную награду когда врезал гусю по клюву",130271,null],[135924,"2026-08-03T12:08:58",9,"//Первоуровневые из книги мож сразу выучить как класс возьмешь",130271,null],[135925,"2026-08-03T12:11:55",9,"Жена Горна — Пьяница местный, все у него заседают. — *Показывает на дом в центре с пристройкой. Кажется староста говорил что там у них что-то вроде корчмы хуторской.*",135919,null],[135926,"2026-08-03T12:14:24",17,"/Чето все молчуны, ладно жду, я готов идти дальше к этому Бунгалю",130271,null],[135927,"2026-08-03T12:16:05",42,"// сорянчик я тута",130271,null],[135928,"2026-08-03T12:16:15",9,"//Заявки у вас есть?",130271,null],[135929,"2026-08-03T12:17:06",42,"— Иии так что-то долго мы тянем. Давайте побыстрее туда зайдëм, узнаем и выполним задание",135925,null],[135930,"2026-08-03T12:23:37",21,"Нет",135928,null],[135931,"2026-08-03T12:25:18",17,"\"А может ну нахер этих бухих мужиков? Пойдемте по берегу речки просто, и сами поищем. Кажется мы теряем драгоценное время\"",130271,null],[135932,"2026-08-03T12:28:38",21,"—Согласен. Не хочется мне с пьяницами говорить лишний раз.",135931,null],[135933,"2026-08-03T12:44:25",9,"//Идёте куда",130271,null],[135934,"2026-08-03T12:46:02",21,"К берегу реки. Ищем хотя бы следы",130271,null],[135935,"2026-08-03T12:51:58",9,"*Вы идёте к реке. Камыши, обрывы, деревья, гнёзда птиц. Живая река, почти не тронутая природа и лишь редкие тропы ведущие в разные стороны.*",130271,null],[135936,"2026-08-03T12:53:37",9,"//Если ищите самостоятельно кидайте выживание/восприятие на ваш выбор, сложность высокая оч искать на угад 22+",130271,null],[135937,"2026-08-03T12:57:12",17,"/r +2 Выживание",130271,null],[135939,"2026-08-03T12:57:45",17,"Фауст проходя по берегу ничего особого не замечает\n\n\"Что там старушка говорила... Утопец? Это кто еще такой?\"",130271,null],[135940,"2026-08-03T12:59:21",21,"—Думаю, это живой утопленник. Возможно он что то скажет?",130271,null],[135941,"2026-08-03T13:03:01",9,"*Пару хороших мест где скорей всего ловят рыбу и небольшой самодельный пирс. Тут тихо, никого.*",135938,null],[135942,"2026-08-03T13:06:39",17,"\"Живые мертвецы... Да уж, воняет он наверное ужасно, издалека должно пахнуть мёртвечиной\"\n\nПродолжая путь Фауст призвал ледяного двойника вперед себя как приманку в случае чего",130271,null],[135943,"2026-08-03T13:06:55",42,"— извиняйте. С животными могу говорить, с мертвецами вряд-ли \n°пожал плечами люц°",130271,null],[135944,"2026-08-03T13:07:32",17,"\"Поймай какую нибудь жабу и спроси её, Люц\"",130271,null],[135945,"2026-08-03T13:08:37",42,"/roll 1d20 +4 выживание ищем жабу и ловим",130271,null],[135947,"2026-08-03T13:09:14",9,"*Ты видишь огромного скракля на берегу.*",135946,null],[135949,"2026-08-03T13:10:24",42,"°подхожу к нему и хочу посмотреть на его реакцию на мутанта таракана°",130271,null],[135950,"2026-08-03T13:11:41",9,"*Жаба огромная, настоящей скраколь.*",130271,null],[135951,"2026-08-03T13:12:10",9,"Жаб — Рибуп, Рибуп. — *Квакает глядя на реку о своём.*",130271,null],[135952,"2026-08-03T13:13:03",9,"*Его глаза реагируют на тебя когда подходишь близко.*\n\n//25 футов меж вами",135949,null],[135953,"2026-08-03T13:17:51",9,"//Щас ещё с жабой попиздиться 100%, вот вам и разговоры с животными 😂👍",130271,null],[135955,"2026-08-03T13:37:18",42,"— Рибупс рибуп",135951,null],[135957,"2026-08-03T13:43:56",9,"*Внимателтный взгляд огромной жабы в ответ. Варг и Фауст могли наблюдать как Люц квакает с жабой*\n\n//Ты пытаешься ей что-то сказать или? Обьясняй)",135955,null],[135958,"2026-08-03T13:45:00",9,"// Рибуп Рибуп это вариация Ква Ква кажется на английском, использую его ведь звучит внушительнее чем Ква для такой огромной лягухи)",130271,null],[135959,"2026-08-03T13:51:29",17,"/ @Jak_Zak",130271,null],[135960,"2026-08-03T13:53:10",9,"// Кажется работа фельдшера не щадит",130271,null],[135961,"2026-08-03T13:53:38",42,"// да",130271,null],[135962,"2026-08-03T13:53:59",42,"(Жабий) — Здравствуй здоровяк",135958,null],[135963,"2026-08-03T13:59:19",9,"Жаб (Терентий) — О, какие нынче цивилизованные молодые люди пошли. Никто не здоровался раньше со мной, обычно камень летить или сразу пытаются напугать. — *Он повернулся к тебе и положил руку на шею, или это живот?* — Я представлюсь, меня зовут Терентий, рад нашему знакомству.\n\n*Для остальных он квакал, повернулся глядя на Фауста и Ваога что стояли подальше если они не скрывались.*\n\nЖаб (Терентий) — Путники, впервые вижу вас в наших краях. Готов предположить что вы по делу, или решили осесть в деревушке людской?",135962,null],[135964,"2026-08-03T14:00:53",17,"\"Смотри Варг, жук с жабой базарит. Че только не бывает. Ты что думаешь нам делать надо? Искать этого Грома или просто по горам пойти полазить, авось наткномся на озеро волшебное?\"",130271,null],[135965,"2026-08-03T14:02:54",42,"— разрешите и мне представиться мистер Терентий. Я Люц, а это да мои спутники. Мы пришли по делу и ищем некого Горна который был утерян. Не известно тебе что-то об этом? Были бы очень благодарны за помощь\n°сел на землю жопой и явно видно что жуку беседа нравится°",135963,null],[135970,"2026-08-03T14:06:42",9,"Жаб (Терентий) — Горн? Вряд-ли кто-то носил с собой да потерял столь крупную вещь. — *Лягушка на ваших глазах потирает подбородок, а после ставил лапку на камень на котором грелся.* — Готов предположить что речь о человеке, с людьми обычно не удаётся общаться, имена их не знаю. Может есть у него примета какая или что-то что может мне помочь понять кого именно вы ищите? Частых рыбаков я помню в лицо.",130271,null],[135971,"2026-08-03T14:08:15",42,"— Фауст, есть какие-то примечательные черты у потеряшки?",130271,null],[135972,"2026-08-03T14:10:12",17,"\"Он вернулся ободранным когда воду из горного источника принёс. Больше примет нет\"",130271,null],[135973,"2026-08-03T14:10:48",9,"//Вы их не спрашивали)",135972,null],[135974,"2026-08-03T14:11:11",21,"—Да не знаю, чесслово. Сам пока понятия не имею что делать, да и не думаю что щас что то дельное сможем.",135964,null],[139599,"2026-08-04T20:45:53",9,"//Вас двоя осталось, чекните когда играете",130271,null],[139601,"2026-08-04T20:46:54",17,"/ Я щас на улице, поливаю свой прекрасный полисадник. Приду через минут 20 и лягу и уж тогдааа",130271,null],[139607,"2026-08-04T20:48:32",41,"( плюсик в карму. У меня тоже палисадник красивый",139601,null],[139608,"2026-08-04T20:49:00",9,"//Может тогда, вдвоём вы пролетите. Но щас для вас двоих там сложность заоблачная будет",130271,null],[139612,"2026-08-04T20:49:25",17,"/ Разберемся",130271,null],[139615,"2026-08-04T20:49:34",17,"/ Мы будем убегать если дело пахнет писюнами",130271,null],[139618,"2026-08-04T20:49:55",9,"//Ну, кинь на магию, скажу какие заклы у тебя, сложность 10 и 15",130271,null],[139626,"2026-08-04T20:51:05",17,"/ У меня ещё 3 лвл. А мультик на 4",130271,null],[139627,"2026-08-04T20:51:12",9,"//Условно книжку изучить пытаешься, хотя бы узнать что там",130271,null],[139628,"2026-08-04T20:51:14",17,"/r +1 Магия",130271,null],[139632,"2026-08-04T20:51:20",17,"/ Опааа",130271,null],[139634,"2026-08-04T20:51:26",17,"/ Умни Фауст",130271,null],[139637,"2026-08-04T20:51:34",41,"( прозрел",139634,null],[139649,"2026-08-04T20:53:22",9,"*Немного поизучав книгу Фауст смог разобраться формулы каких трех заклинаний там расписанны. Это были \"Ведьмин снаряд\", \"Псевдожизнь\" и \"Отражения\". Свиток кажется тоже содержит в себе заклинание \"Отражения\".*",139630,null],[139652,"2026-08-04T20:53:58",9,"//Сорян, у нпс тоже ток они были, он маг 5го уровня, вот так не везет ему)",130271,null],[139653,"2026-08-04T20:54:12",17,"/ Отражения это каеф",130271,null],[139661,"2026-08-04T20:55:28",9,"//И так как это твоя первая книга заклинаний то материалы на изучение этих трех мож не тратить, как класс возьмешь, остальные искать и изучать нормально прийдётся.",130271,null],[139669,"2026-08-04T20:56:41",17,"/ Спасибо мастэр",130271,null],[139693,"2026-08-04T21:02:19",9,"//На будущее, если что-то можно проверить, то это можно проверить)",130271,null],[139961,"2026-08-04T22:47:06",17,"/ @Jak_Zak спишь жук?",130271,null],[140071,"2026-08-05T09:18:20",42,"// да спал",130271,null],[140612,"2026-08-05T14:44:03",17,"Люц видит как Фауст от нечего делать идёт по берегу и меняется местами магически с ледяным двойником\n\nТуда сюда\n\nтуда сюда",130271,null],[140616,"2026-08-05T14:44:23",17,"\"Ничего интересного... Где же этот Гром? Или его трупешник\"",130271,null],[142047,"2026-08-05T23:10:09",42,"— Фаааауууууст. Ну Раскажи про нашу потеряшку что известно? Мистер Терентий хочет нам помочь информацией",130271,null],[142076,"2026-08-06T01:02:24",17,"\"Чего?\"\nФауст остановился и обернулся к Люцу\n\nТолько сейчас он увидел что жук говорит с жабой\n\n\"Ааа ты нашел с кем поболтать. Замечательно. Мужик...\"\n\nПересказываю ему отличительные черты Грома",130271,null],[142077,"2026-08-06T01:03:17",9,"//Вы не спрашивали о них, не знаете. Думате ещё",142076,null],[142078,"2026-08-06T01:04:17",9,"//Пропустили социалку, просто пропал мужик)",130271,null],[142079,"2026-08-06T01:04:34",17,"\"Только что он был ободран. Как то так вышло, что мы дурачки не спросили об особенностях внености\"\n\n\"Что он там тебе отвечает?\"",130271,null],[142080,"2026-08-06T01:07:35",17,"/ Ну что ж либо вернёмся в дом к пьняугам и распростм. Либо случайно наткнемся на улики на берегу",142077,null],[142081,"2026-08-06T01:08:02",17,"Между тем Фауст не терял времени даром найдя дерево он забрался на него чтобы осмотреть берег с высоты",130271,null],[142082,"2026-08-06T01:08:15",17,"/r +2 Пошел осмотр",130271,null],[142084,"2026-08-06T01:11:55",9,"*Ты видишь несколько \"скрытых\" мест для рыбалки, может это что-то ласт а может и нет. Никаких мертвяков не видно. Ещё за очеретами застряла перевернутая лодка, ощущение что её бросили.*",142083,null],[142085,"2026-08-06T01:17:17",17,"\"Бросай жабу Люц. Есть минимум пара мест где рыбачили, камыш примят, и ещё перевёрнутая лодка. Надо проверить\"\n\nФауст сидит на дереве а ледяной клон уже идёт в сторону первого скрытого рыбацкого места\n\nРассыпаясь снежинками Фауст меняется с ним местами и уже сам продирается через прибрежные заросли камыша и рогоза",130271,null],[142086,"2026-08-06T01:18:16",9,"//Ну, я подожду жаку",130271,null],[142087,"2026-08-06T01:19:02",17,"Дойдя до места он останавливается. \n\nДелает взмах невидимой удочкой будто бы ставя себя на место рыбака и приглядывается что тут необычного? Может остались следы или потерянные вещи...",130271,null],[142088,"2026-08-06T01:19:05",17,"/ Ждем",130271,null],[142160,"2026-08-06T10:46:11",17,"/@Jak_Zak очень хочу тут двигаться, давай в тандеме. Два делбича которые идут напрямик",130271,null],[142161,"2026-08-06T10:50:30",42,"— До свидания мистер Терентий! \n°потопал за Фаустом°",142085,null],[142162,"2026-08-06T10:53:52",17,"Не придумав ничего лучше Фауст решил начать рубить камыш в попытке расчистить заросли и найти след",130271,null],[142163,"2026-08-06T10:54:04",17,"/r +2 Выживание",130271,null],[142165,"2026-08-06T10:54:11",9,"//К лодке?",130271,null],[142166,"2026-08-06T10:54:23",17,"/ Ты сказал 2 места рыбаков и лодка, пока мы на 1 месте",130271,null],[142167,"2026-08-06T10:55:39",9,"*Первое — хорошее место, насиженное, под небольшим обрывом. Тут в воде есть камни, скорей всего в их тени под водой трется рыба.*",142166,null],[142168,"2026-08-06T10:56:19",17,"\"Кроме рыбы - ничего, Люц. Пойдем ко второму месту, а потом к лодке или ты что то попытаешься найти еще тут?\"",142167,null],[142169,"2026-08-06T10:57:51",9,"*Второе место что ты присморел прийдется прорубаться через камыши почти к самой реке, сложно сказать или определить глубину там пока не пройдёшь.*",142168,null],[142170,"2026-08-06T10:58:18",17,"/А сколько растояние прорубаться и лезть по воде?",130271,null],[142171,"2026-08-06T11:01:33",9,"*Футов 300-350 по мелководью пока камыши не кончатся. Второе примечательное место выглядит как насест у воды где наверное глубоко, поставленный у края камышей.*",142170,null],[143848,"2026-08-06T23:03:23",42,"— Да нет. Нечего искать не буду, потопаю ко второму месту\n°потопал за Фаустом думая что может случиться с потеряшкой°",142168,null],[143852,"2026-08-06T23:04:59",17,"\"Идём вброд к лодке за мной, тут вроде мелко\"\n\nФауст прорубает камыши перед собой движется целенаправленно у лодке",130271,null],[143858,"2026-08-06T23:06:59",9,"*Чем дальше тем глубже, где то на половине пути было по колено.*",143852,null],[143866,"2026-08-06T23:08:56",17,"\"Похоже ошибся, глубоковато становится. Я могу один трюк проворачивать, а тебе надо думать как пройти тут самому\"\n\nФауст после этого телепатического послания начал создавать впереди чуть выше воды своего клона и сразу меняться с ним местами и снова и снова и снова и снова\n\nОн почтиплюзался в воду и успевал меняться с клоном чтобы не заткнуть",130271,null],[143868,"2026-08-06T23:09:24",17,"/ Умение эха, призываю в 15 футах, меняюсь местами и снова призываю впереди в 15 и снова меняюсь так по кругу",130271,null],[143869,"2026-08-06T23:09:47",17,"/ Так прыгаю телепортации к лодке",130271,null],[143878,"2026-08-06T23:12:56",9,"//Ты к насесту вродь шёл, не?",130271,null],[143879,"2026-08-06T23:13:05",9,"//Или к лодке дальше",130271,null],[143888,"2026-08-06T23:16:44",42,"— о как.. Услышал родной\n°топаю дальше°",130271,null],[144005,"2026-08-06T23:55:19",17,"/ К лодке прямой наводкой",143879,null],[144007,"2026-08-07T00:31:56",17,"/ Доберусь так до лодки? Это бесконечно и бесплатно",130271,null],[144008,"2026-08-07T00:32:02",17,"/ Прыжки по 15 футов",130271,null],[144066,"2026-08-07T07:27:15",9,"*Возле перевёрнутой лодки что застряла в камышах уровень воды почти по плечи. Под ногами месится глина и муляка, идти тяжко.*\n\n//Трудно проходимая",130271,null],[144069,"2026-08-07T07:29:58",17,"Сперва Фауст присматривается что там конкретно застряло, может можно вытащить крюком с кошкой",130271,null],[144072,"2026-08-07T07:36:51",9,"*Может лодку прибило сюда и она просто не дрейфует в заросших камышах, а может та перевернулась уже здесь, по каким-то причинам...*",144069,null],[144074,"2026-08-07T07:50:42",17,"\"Люц, помоги ка перевернуть лодку\"\n\nПодошёл вплотную к лодке жду товарища.\n\nСтучу по днищу кулаком будто бы стучу в дверь\n\nПрислушиваюсь",130271,null],[144075,"2026-08-07T07:50:53",17,"/r +2 Восприятие",130271,null],[144079,"2026-08-07T07:56:03",42,"— хорошо\n°подошëл и начал помогать перевернуть лодку°",144074,null],[144080,"2026-08-07T08:01:52",17,"/ Мастер мы переворачиваем лодку",130271,null],[144108,"2026-08-07T09:20:56",17,"/ А там щас вылезет утопец ставлю всё на это и такой",130271,null],[144131,"2026-08-07T09:39:42",17,"Ледяной клон находился в 15 футах позади\n\nФауст готовился в случае опасности поменяться с ним местами в туже секунду",130271,null],[144133,"2026-08-07T09:40:19",9,"*Лодку удалось вернуть назад, она пуста, сбоку лишь закреплено весло которое не потерялось чудом. Под досками что были сделаны как сидения каким-то чудом не выпала сумка, в ней бутылка деревенского самогона и снасти.*\n\n//Получен набор рыбака и стеклянная бутылка деревенского самогона",130271,null],[144136,"2026-08-07T09:41:42",17,"\"Тут бутылка спиртного и рыбацкие снасти. И больше ничего... Ну может вернёмся в деревеню и распросим мужиков, где они там собираются и выпивают. Самогон у нас есть, развяжет им рты\"",130271,null],[144208,"2026-08-07T10:19:15",42,"— Звучит как план.. Как раз узнаем у людей как выглядит и что делал, после у Терентия информацию уточним",130271,null],[144211,"2026-08-07T10:20:12",17,"\"Тогда давай вылазить, тут кажется больше ничего\"\n\nНа всякий случай фауст пошерудит удочкой около лодки, может тело под водой",130271,null],[144213,"2026-08-07T10:20:17",17,"/r +2 Выживание",130271,null],[144219,"2026-08-07T10:20:43",9,"*В этом месте слегка тревожно, что-то не так, слегка тревожно.*",144136,null],[144231,"2026-08-07T10:22:37",42,"/roll 1d20 +2 внимательность",144219,null],[144234,"2026-08-07T10:22:41",9,"*Сделав небольшой осмотр вроде бы ничего, но ещё мгновение и глаза цепляются за фигуру в воде. Это труп рыбака и он внезапно всплыл прямо перед тобой.*",144214,null],[144244,"2026-08-07T10:24:14",17,"Фауст сразу меняется местами с ледяным клоном",130271,null],[144247,"2026-08-07T10:24:25",17,"\"Трупешник всплыл, проверишь? Я прикрою\"",130271,null],[144292,"2026-08-07T10:39:19",17,"/@Jak_Zak гоу экшен",130271,null],[144310,"2026-08-07T10:46:29",42,"// Гоу экшен",130271,null],[144312,"2026-08-07T10:46:57",42,"°МИСТИЧЕСКИЙ ЗАРЯД В ТРУП°",130271,null],[144315,"2026-08-07T10:47:33",42,"/roll 1d20 +6",130271,null],[144321,"2026-08-07T10:49:16",9,"*Труп не шевелится, не реагирует когда его прошило зарядом.*",130271,null],[144330,"2026-08-07T10:56:48",42,"— он мëртв. Мëртв точно",130271,null],[144332,"2026-08-07T10:58:00",17,"\"Может это Гром, давай вытащим его на берег\"",130271,null],[144338,"2026-08-07T11:03:49",42,"— давай\n°взял за руку труп и потащил на берег°",130271,null],[144345,"2026-08-07T11:05:07",9,"*На берегу выяснилось что это молодой рыбак, лет двадцати не больше. Его погрызли и убили совсем недавно, окоченел не полностью а на теле несколько посиневших следов от когтей.*",144338,null],[144357,"2026-08-07T11:23:24",42,"°осматриваю труп пытаясь от куда раны и кто мог бы их нанести°",130271,null],[144358,"2026-08-07T11:23:48",42,"// медицина или выживание если это дикое животное?",130271,null],[144359,"2026-08-07T11:24:16",9,"*Когти, зубы, но слабо похожи на тупые, словно один человек пытался сожрать другого и перестал когда жертва испустила дух.*",144357,null],[144360,"2026-08-07T11:24:56",42,"// могу же броском подетальнее попытаться узнать",144358,null],[144361,"2026-08-07T11:25:53",9,"//Я без броска ответил, но как хочешь, просто очевидные вещи проверки как по мне не требуют. Кинь и скажи что жочешь узнать",130271,null],[144363,"2026-08-07T11:26:46",42,"/roll 1d20 +4 выживание хочется узнать что за тварь по природе может так совершить ибо упыри доедают своих жертв",130271,null],[144367,"2026-08-07T11:29:39",9,"*Скорей всего нежить но почему-то да, она не ела его, а ещё на ранах четкие следы некротики. Что-бы это небыло, это необычная нежить.*",130271,null],[144369,"2026-08-07T11:31:49",42,"— Фаус.. Глянь\n°показываю рану что повреждена неротикой, гематомы с кулаков и когти°\n— твой нюх контр бандиста говорит что-то об этом? Если нет.. То я как житель Висперали знаю природу этих ран",130271,null],[144370,"2026-08-07T11:32:05",42,"// капец у меня все с Висперали кроме Майло",130271,null],[144371,"2026-08-07T11:33:08",17,"\"Зубы не острые. Зомби наверное. Живой мертвец\"",130271,null],[144372,"2026-08-07T11:34:18",42,"— да ты прав.. Но были бы так раны просто физические. А они ещë некротической энергией нанесли удар.. Нежить не простая..",130271,null],[144373,"2026-08-07T11:35:30",42,"// даже за колдуна играю как блад хантер... Заразная хрень",130271,null],[144493,"2026-08-07T13:13:20",17,"\"Давай его дотащим до деревни, может местные его опознают. Нам плюс в карму, всё же лучше отпеть и схоронить или сжечь, пусть сами разбираются\"",130271,null],[144509,"2026-08-07T13:22:00",42,"— полностью с тобою согласен. Хорошая репутация на чьëм-то труппе звучит не капли стрëмно",130271,null],[144529,"2026-08-07T13:26:21",17,"\"Всегда работает. Или сам ты прибил кого то или притащил труп уже убитый. Все довольны\"",130271,null],[144544,"2026-08-07T13:29:48",42,"— да мы с тобою споëмся друг мой\n°запрокинул тушку на плечо и потопал в сторону деревни подзывая за собою Фауста°",130271,null],[144549,"2026-08-07T13:31:09",17,"И они вернулись в деревню\n\n\"Давай с трупом сразу к мужикам, два дела разом делать, мне уже надоело бродить тут без понимая направления до цели. Думаю тебе тоже\"",130271,null],[144569,"2026-08-07T13:40:35",9,"//В корчму Бунгаля?",130271,null],[144599,"2026-08-07T13:50:12",9,"*Вы тащите труп, все кто его видят провожают вас взглядом и вдруг кто-то роняет ведро с водой и подбегает к парню.*\n\nПожилая женщина — Маркс марк, это не ты, я не верю. — *Ей плевать на вас, она припадает к сыну, обнимает холодный посиневший труп и плачет.*",130271,null],[144603,"2026-08-07T13:51:32",17,"\"Мы нашли его у берега в реке, его убила нечистая сила. Соболезную вашей утрате\"",144599,null],[144607,"2026-08-07T13:53:41",42,"— Я что мог заметить, это всë устроила нежить. Не трупоед, а кто-то пострашнее. Случаем нету же кладбищ поблизости от туда? Я с моим другом можем помочь отомстить за вашего сына",130271,null],[144608,"2026-08-07T13:54:02",9,"*Она плачет и причитает, ей плевать. Словно из под земли появляется староста, ему уже кто то сказал.*\n\nСтароста (Григорий) — Точно нечистая сила постаралась. — *Он вздыхает и качает головой.* — Жаль мы слигком далеко, дикая охота не скоро прибудет.",144603,null],[144609,"2026-08-07T13:54:33",9,"*Староста кивает вам, мол давайте немного отойдем не будем мешать.*",130271,null],[144612,"2026-08-07T13:54:54",17,"\"Мы можем найти нечисть и устранить. Пожалуйста помогите и нам с поисками Грома и воды, используйте свою власть и опросите всех. Уговор?\"",144608,null],[144613,"2026-08-07T13:55:34",9,"Староста (Григорий) — Из кладбища никто не вылезет, все правильно захоронены, по завету и правилам. Неупокоенный или забредший.",144607,null],[144617,"2026-08-07T13:58:01",9,"Староста (Григорий) — Горна? Да да, я вам и сам могу расказать о нёмс знаю всех в лицо. К воде правда сейчас никто не пойдёт, могу конечно мужиков поросить. Что вам точнее нужно? — *Видно что старик хочет решить проблему, готов сотрудничать.",144612,null],[144619,"2026-08-07T13:59:25",17,"\"Нужно понять. Вы занаете путь к воде? Гром вроде знал какой то безопасный? И честно говоря очень интересно узнать подробности, кто такая дикая охота. Благодарю вас.\"",144617,null],[144621,"2026-08-07T14:00:01",42,"— Господин.. Я сам с рода города нежити и знаю что правилтные захоронения это залог успеха.. Но мог придти кто-то и нарушить покой ныне не живых",144613,null],[144622,"2026-08-07T14:00:55",9,"Староста (Григорий) — Сторож за этим смотрит, цело всё. — *Качает головой, и садится на лавку немного отйдя, была неподалёку.*",144621,null],[144623,"2026-08-07T14:01:10",9,"Староста (Григорий) — Ну значит слушайтя...",130271,null],[144624,"2026-08-07T14:01:22",9,"//Щас ебану вам немного инфы",130271,null],[144625,"2026-08-07T14:01:58",17,"/ Мне реально интересен Лор, хотя хочется влететь в экшен тоже) Но его пока не нашли)",130271,null],[144635,"2026-08-07T14:05:40",42,"// экшена просить харда не надо.. Это обычно кончается драконом",144625,null],[144636,"2026-08-07T14:06:01",9,"*Дикая охота, ею правит сам король колдун в Вальдхейме, сильнейший воин и маг. Здесь нет королей, власти, налогов, только местячковая, чародеи, колдуны, маги, все дивут как хотят, по чести и совести.*\n\n*Дикая охота состоит не только из магов, а и из наемников, они гоняют нечисть, монстров, периодически приезжают решить проблеммы. Из почитают, некоторые хотят стать частью дикой охоты, но немногие.*\n\n*А так, без королей, стражи и наместников жизнь в Вальдхейме проста и нетороплива, чаще сельская. Земля ничейная потому что дикая охота легко прогонит любую армию захватчиков, дед в этом уверен. И главное, за плохим человеком, злым существом... рано или поздно... прийдёт... дикая охота.*",130271,null],[144637,"2026-08-07T14:09:28",17,"\"Спасибо. Я захотел присоедениться к дикой охоте сам. Может если мы вам поможем замолвите за меня словечко перед ними?\"",144636,null],[144638,"2026-08-07T14:09:38",9,"*Источник же местная легенда, говорят даёт здоровье и жизненные силы, только почти никто не возвращался с гор чтобы расказать где он, и дед не знает.*\n\nСтароста (Григорий) — Помню хотел жёнке своей воды принести, молодой был, думал станет краше и она рада. Пошел с мужиками источник искать, звери. — *Дед вздохнул, вспомнил старое и почесал бок.* — Побитые пришли, не помер никто и оо хорошо. Не нашли мы источника, а зверьё в горах крупнее, сильнее, опаснее. Ни один из охотников не сдюжит, Горн был локим и он полуживой вернулся оттуда, чудом нашёл источник, а где не знаю.",130271,null],[144639,"2026-08-07T14:10:39",9,"Староста (Григорий) — Без проблемм. А источник? У нас гостит часто подозрительный человек, имени его не знаю, но мужик хороший. Я так понял вы за водой к нам пришли?",144637,null],[144640,"2026-08-07T14:11:03",17,"\"Еще просьба, я владею неким трюком, не пугайтесь\"\n\nРядом появляется ледяной клон.\n\n\"Расскажите всем, чтобы не боялись ледяной копии, она для защиты, а не угроза для вас\"",130271,null],[144642,"2026-08-07T14:11:34",17,"\"Да, за водой. Можем мы с ним поговорить, где он?\"",144639,null],[144643,"2026-08-07T14:12:59",42,"— а я.. Лучше промолчу что могу\n°жук и так себя чувствует белой вороной из-за внешки, а если узнают про тëмную магию, сожгут точно°",130271,null],[144644,"2026-08-07T14:13:51",17,"/Если что я передаю тебе типо тоже самое что и старосте, так что ты вкурсе типо разговора",144643,null],[144646,"2026-08-07T14:15:02",9,"*Кивает*",144640,null],[144647,"2026-08-07T14:15:06",42,"// Люца не сильно уж удивило. Его покровитель это гитара. А сам он на половину жук что хавает сырое мясо",144644,null],[144648,"2026-08-07T14:15:38",9,"Староста (Григорий) — Если вы тут, то наверное он и заказал воду, значица прийдёт на днях.",144642,null],[144650,"2026-08-07T14:16:44",9,"Староста (Григорий) — Постоянно спрашивал мужиков наших, не сходим ли мы с ним. Но озотники дело знают и жить хотят, не пойдут и за залотую гору.",130271,null],[144653,"2026-08-07T14:20:50",42,"— ладно идëм? Время терять зря не хочется.. Да и ночь потревожит, если нежить вылезет",130271,null],[144654,"2026-08-07T14:33:49",17,"\"Да, пойдем поговорим с ним\"",130271,null],[144655,"2026-08-07T14:33:55",17,"/Мы идём к странному типу",130271,null],[144658,"2026-08-07T14:41:00",9,"//Типа нет сейчас",130271,null],[144659,"2026-08-07T14:41:23",9,"//Типа, но не всегда тут, вот в чем фокус",130271,null],[144664,"2026-08-07T14:46:47",17,"\"А, его нет сейчас? Тогда мы сперва зайдем к корчму Бунгаля. Пойдём, Люц.\"",130271,null],[144665,"2026-08-07T14:47:43",9,"//К бунгалю то зачем, староста всехместных в лицо знает, хотя... к Бкнгалю идёте?",130271,null],[144666,"2026-08-07T14:49:16",17,"/Да",130271,null],[144667,"2026-08-07T14:49:20",17,"/Хотим продвигаться",130271,null],[144668,"2026-08-07T14:49:25",17,"/ Во всех возможных направлениях",130271,null],[144678,"2026-08-07T15:00:11",42,"// я туты",130271,null],[144683,"2026-08-07T15:05:37",42,"// согласен",144667,null],[145044,"2026-08-07T18:40:18",9,"*В пристройке что местные назвали корчмой сидело два мужика, охотник что мял кожу и с ним болтал жук и незнакомец. А с ними на вид, ну точно пьяница, такой обычный мужичок щекастый с покрасневшим слегка заплывшим лицом, наверное тот самый Бунгаль, они играли в карты, усиленно, им на вас плевать, и судя по деньге на столе игра имеет ставки.*",130271,null],[146614,"2026-08-08T09:45:26",17,"\"Доброго дня хозяин и вы господин. Мы наемники, ищем воду с горного источника. Поделитесь с нами своими знаниями о нем, будьте добры. Мы с собой и магарыч принесли.\"\n\nГлазами взглянул на товарища\n\n\"Люц, доставай чекушку, время их задобрить\"",145044,null],[146615,"2026-08-08T09:46:56",17,"/ @Jak_Zak",130271,null],[146616,"2026-08-08T09:48:15",9,"Пьяница (Бунгаль) — Да да, не мяшай, у меня баченок на куш. — *Пьяница усиленно играет в карты, те несколько золотых на столе его волнуют сильнее чем сиюминутная выгода.*",146614,null],[146617,"2026-08-08T09:48:39",9,"*Тот охотник чьо обматерил жука, взглянул на Люца и хмыкнул.*",130271,null],[146618,"2026-08-08T09:49:12",17,"\"А что, я тоже не проч сыграть. И ставка золотом имеется! Примите в игру?\"",130271,null],[146619,"2026-08-08T09:49:13",42,"// тут",130271,null],[146620,"2026-08-08T09:50:10",42,"°посмотрел на охотника и хмыкнул в ответ на него°",130271,null],[146631,"2026-08-08T10:02:05",9,"Пьяница (Бунгаль) — Чох це, сячас, сячас. — *Он доигрывает и.*",146618,null],[146632,"2026-08-08T10:02:20",9,"/roll 1d3 везение пьяницы",130271,null],[146634,"2026-08-08T10:03:48",9,"Пьяница (Бунгаль) — Йасс, деньга моя! — *Забирает почти 3 золотых со стола обыграв других.*\n\nОхотник — Ладно батька, пива все равно налей.\n\n*Бунгаль приносит им пива, прямо со стола и сращу к вам.*\n\nПьяница (Бунгаль) — Чаго изволитя гости радныя.",130271,null],[146635,"2026-08-08T10:07:59",17,"\"Все что знаешь про Грома и про источник волшебной воды в горах. Все слухи что слышал. Нальём сейчас, выпьем. Денег тебе заплатим хозяин.\"",146634,null],[146637,"2026-08-08T10:37:44",9,"Пьяница (Бунгаль) — Оо, хараша, хараша. — *Потирает руки.* — Я накрою на стол.\n\n*Он вам показал на стол пристройкес простой но добротный и всё такое, а сам пошё за гриль в углу и достал мяска из ямы, жарить, вяленого рещет, бочёнок катит. Все сам!*",146635,null],[146638,"2026-08-08T10:38:36",17,"\"Какая красота, жаль я уже поел. Но мой друг может хочет.\"",130271,null],[146639,"2026-08-08T10:41:34",9,"*Бунгаль накрыл, ворчал но все равно.*\n\nПьяница (Бунгаль) — Не стясняйтесь, раза хатите деняг дать будят вам ущений. Деньга хорошо новая в этам местя, обороты надо вкладывать, а она ток тарговцам уходят в ярмарку что пряизжают, а у нас дянег больша не становится.\n\n*Расказывает о том что вложение денег в деревню которая их почти нет и те уходят во вне для него ценное экономическое вложение что окупается соразмерно...*",130271,null],[146640,"2026-08-08T10:42:31",9,"*Накрыв на стол самсел месте с вами, Бунгаль имел акцент странный, у местных нет почти его, но никто из вас пока не был в Темнограде чтобы с точностью сказать откуда пьяница.*",130271,null],[146641,"2026-08-08T10:45:29",17,"Фауст сразу кладет первую золотую монету на стол и медленно двигает Бунгалю пальцем по столешнице\n\n\"Деньги - есть. И я готов с ними расставаться, за каждый полезный слух об источнике. Я внимательно слушаю тебя хозяин\"",130271,null],[146642,"2026-08-08T10:47:36",9,"*Описал он Горна, парень лет 32 крепкий, на щеке шрам от когтей, чернявый и волосы длинный в косы заплетены, всегда алкоголь брал на реку и раколовки ставил, охотник вообще крутой былс щахомутал девицу красивую соседскую. Источник он не сказал нияего нового, лишь слухи. Из более менеее стоющего о том что по слухам источник у раздвоенной горы, но сам он не знает насколько это правда, пьяным услышал.*\n\nПьяница (Бунгаль) — Прасти, асточник вся хотят найти, адни говорят о водопаде из лятающего камня, другия о монстрах что жрут людей лягко. Трети что вада из асточника исцеляет и молодит. Насколько эта правда не знаю, мамка Горна здаровья поправила тагда, а вот молоде сильна не стала.",130271,null],[146652,"2026-08-08T13:43:07",17,"Ещё монета на столе. Фауст пальцем двигает ее информатору\n\n\"Почему вдова его не хочет нам помогать? Они рассорились? Или что говорят?\"",146642,null],[146654,"2026-08-08T13:44:23",9,"Пьяница (Бунгаль) — Ну эта лишное... — *Он подумал и все де сказал.* — Да, ругалися часта, то на рыбалке прападет, дома нет и вся такое. Гарюет девка думаю.",146652,null],[146657,"2026-08-08T13:47:59",17,"\"Тогда за эту монету, расскажи, что про дикую охоту рассказывают. Кто у них главный? Кто в вашу деревню захаживал? \"",130271,null],[146660,"2026-08-08T13:52:28",9,"Пьяница (Бунгаль) — Хм, к нам наёмники захаживают, ахотники и Алая ведьма атдыхать приезжает раз в месяц али два, коли позвать прияжают ток наёмники. — *Отпил пива немного, добавил.* — Самый сильней эта кароль калдун, но Семизар ужа стар, гатовит приямника. Сам яго никагда не видал. А алая ведьма сильна, порча и кровь, даже драк костями срать будят...\n\n*Расказывает насколько сильна и афигенна Алая ведьма. Семизар старый король колдун, тут не бывал, а так скоро будет новый говорят.*",146657,null],[146697,"2026-08-08T16:14:39",17,"\"Занятно. Алая ведьма значит. Имя точно внушает трепет. А кто же приемник, кого король колдун готовит себе на замену?\"",130271,null],[146717,"2026-08-08T16:59:00",9,"Пьяница (Бунгаль) — Чаго не знаю таго не знаю, тут у изгаловья редко ктл делится слухами. — *Расстроенно икнул и сушит кружку.*",146697,null],[147318,"2026-08-08T19:24:21",42,"— Колдун.. Значит убив его я могу хоть немного но возвысить своего покровителя по ступеням могущества.. \n°тихо шепчет себе под нос°",130271,null],[149248,"2026-08-09T19:50:16",17,"\"Укажешь направление к раздвоенной горе? Провожать не надо, но уж не обмани нас, хозяин\"\n\nЕщё монету по столу ему двигаю",130271,null],[149250,"2026-08-09T19:50:26",17,"/ Мы пойдем к раздвоенной горе на поиски источника",130271,null],[149277,"2026-08-09T19:54:14",9,"*Он вздыхает, мнется и приносиь карту, она сделанна от руки.*\n\nПьяница (Бунгаль) — Я сам не хадил но со слов нарисовал карту. Гара по словам где-та тута. — *Показывает за границу зарисовок, там пусто.* — Тока со слов энта, не тошно, вот и не рисавал на карте.",130271,null],[149280,"2026-08-09T19:55:12",17,"/ Со слов Энта? Типо слова живого древня?",130271,null],[149299,"2026-08-09T19:57:05",9,"// это акцент темноградцев, у этого ещё норм, в Темнограде там ток интуитивно бы понимал что местные базарят)",130271,null],[149312,"2026-08-09T19:58:16",17,"Фауст взял карту и оставил ещё золотой на столе\n\n\"Спасибо за все хозяин.\"\n\nОн встал и направился на выход\n\n\"Люц ты идёшь? Мы знаем откуда начать.\"",130271,null],[149313,"2026-08-09T19:58:28",17,"/ @Jak_Zak",130271,null],[149315,"2026-08-09T19:58:30",9,"Пьяница (Бунгаль) — А та та",149312,null],[149317,"2026-08-09T19:58:38",17,"/ 5 монет спишу",130271,null],[149318,"2026-08-09T19:58:44",9,"Пьяница (Бунгаль) — Карту не дам с сабой.",130271,null],[149322,"2026-08-09T19:59:09",17,"\"Не проблема, я перерисую себе.\"",130271,null],[149323,"2026-08-09T19:59:24",17,"Открыл блакнот и карандашом перенес карту",130271,null],[149324,"2026-08-09T19:59:40",9,"Пьяница (Бунгаль) — Тагда ладно, адна у мяня. Нада будят и самому сделать.",130271,null],[154708,"2026-08-12T13:42:11",17,"/ Кстате хочу тут продолжить, у Жаки ДР надеюсь завтра даст пост. ну или скажет будет играть дальше или не будет",130271,null],[154711,"2026-08-12T13:45:40",9,"//Я всегда вас жду, везде. Заявки ваши, и в вершкаи и в каверзе, везде",130271,null],[157830,"2026-08-13T09:50:06",42,"// у тута",130271,null],[157831,"2026-08-13T09:52:27",42,"— Конечно иду напарник. Сегодня у меня хорошее предчувствие \n\nПотопал за Фаустом, по дороге настраивая своего покровителя",149312,null],[157833,"2026-08-13T09:53:16",9,"//Ооооо, куда что идёте, обьясняйте)",130271,null],[157834,"2026-08-13T09:54:06",17,"\"Слышал раньше про эту раздвоенную гору?\"\n\nФауст смотрит на карту и ведёт по ней Люца",130271,null],[157835,"2026-08-13T09:54:29",9,"//Тоесть вы идёте в горы",130271,null],[157837,"2026-08-13T09:54:51",17,"/По карте бунгаля к радвоеной горе",130271,null],[157838,"2026-08-13T09:54:56",17,"/По слухам источник там",130271,null],[157839,"2026-08-13T09:54:58",17,"/Монстры там",130271,null],[157840,"2026-08-13T09:55:01",17,"/Веселье всё там",130271,null],[157841,"2026-08-13T09:55:31",42,"— ннн.. Нет? Я всю юность в культе прожил под наркотиками. От куда мне такое знать?",157834,null],[157842,"2026-08-13T09:55:59",17,"\"Да, что ж. Значит по ходу разберёмся\"",130271,null],[157844,"2026-08-13T09:57:06",42,"— пх.. Были бы хотя бы горы в висперали могли бы как-то разобраться.. А так ну попробую что-то да понять",130271,null],[157846,"2026-08-13T09:58:00",17,"\"Местность тут дикая, нужно быть наготове\"\n\nИз воздуха рядом формируется ледяной клон. Он ускоряется и идёт в 15 футах впереди группы",130271,null],[157847,"2026-08-13T09:58:10",42,"/roll d20 +4 выживание. Люц хочет попытаться понять природу гор и на понятии том же обузнать местность",130271,null],[157850,"2026-08-13T09:59:01",17,"Фауст помогает указывая на необычные кусты и следы",130271,null],[157851,"2026-08-13T09:59:08",17,"/Бросай еще",130271,null],[157853,"2026-08-13T10:01:34",42,":3",157831,null],[157854,"2026-08-13T10:02:04",9,"*Перед горами лежит лесистая местность, посл неведомое болото, а лишь за ним только начинаются горы. Это будет долгий поход, не зря каждому платят 400 золотых. Только к самому болоту день пути если прикинуть на глаз.*",130271,null],[157855,"2026-08-13T10:02:15",9,"//Я подготовился",130271,null],[157857,"2026-08-13T10:04:45",9,"//Вот вам инфа, если нет никаких особых заявок то двигаете?",157854,null],[157860,"2026-08-13T10:07:01",42,"// у меня нету особых заявок, пока не виду нечего особенного",157857,null],[157876,"2026-08-13T10:28:59",17,"Фауст смотрит на небо, какая ожидается погодка?",130271,null],[157879,"2026-08-13T10:30:14",9,"*Редкие перистые облака, солнца уже перешли полдень и начали закатываться на другую сторону неба. Скоро вечер.*",157876,null],[157881,"2026-08-13T10:31:00",17,"\"Поспешим\"",130271,null],[157882,"2026-08-13T10:31:38",9,"//Идёте?",130271,null],[157887,"2026-08-13T10:36:23",42,"— поспешим",157881,null],[157888,"2026-08-13T10:36:39",42,"// поспешиваем",157882,null],[157889,"2026-08-13T10:43:16",9,"*В лесу не встретилось особых опасностей, тропы охотников и собирателей, косули, редкий хищник забредёт в эти места. Так пока не добрались до болот.*\n\n*На топи пропахло сыростью, зелень, свагнум (мох) качался под ногами волнами, как неустойтивая земля. А еще глаза цепляли таблички с черепами или змеями на них, чтобы дети не ходили в эти места.*\n\n*Уже темнело, почти ничего не видно, дальше идти только в ночь.*\n\n*В поле зрения попадает вершина какого-то здания, дальше, в болотах. Разрушенная башня? Может быть, отсюда не видно.*",130271,null],[157893,"2026-08-13T10:50:11",42,"— Фаус. Уже темно, предлагаю заночевать. Болота в ночное время особенно опасны. Можно и в трясине потонуть",130271,null],[157895,"2026-08-13T11:00:44",17,"\"Хорошо, давай разобьём лагерь. Думаешь лучше тут в лесу или пойти дальше к той развалине на болотах?\"",130271,null],[157896,"2026-08-13T11:16:09",42,"— дай ка подумать.. Лучше уж лес чем болота, лес мы проходили и он безопасен. Болота же мы плохо знаем. Да и у нас в висперали были насекомые что водятся в болотах которые переносят разные болезни",157895,null],[157897,"2026-08-13T11:17:52",17,"\"Согласен\"\n\nФауст начинает раскладывать спальник, разводить костёр и питаться как умеет рубленным вяленым мясом\n\n\"Вот если вода из озера действительно от любой хвори лечит, так мы же разбогатеем! Продавать её можем, наладить поставки. Как тебе?\"\n\nЛедяной клон стоял рядом на готове защищая тылы",130271,null],[157898,"2026-08-13T11:29:12",38,"// ФАУСТ?!",157897,null],[157899,"2026-08-13T11:31:11",17,"/ Что?",130271,null],[157902,"2026-08-13T11:49:14",42,"— пхпхп! Да звучит это чудно. Но обязательно на рыбку поменьше придëт рыбка побольше. Если кто-то узнает что мы поставляем такую воду, сразу с выше начнут орать во всë горло что это их земля и вода тоже их. Так что выгодно, но опасно\n\n°ест из пайка°",157897,null],[157903,"2026-08-13T11:51:24",17,"\"Поэтому до того как развернуться, можем приторговывать на черном рынке, у меня есть связи, нанять охрану и так раскрутиться. Главное найти этот источник\"\n\n\"На сегодня всё, я подежурю, а ты ложись отдыхай, мне не нужно всю ночь отдыхать в медитации\"\n\nФауст встал, поднял фонарь и осмотрел кусты неподалёку. Нет ли незванных гостей",130271,null],[157904,"2026-08-13T11:51:30",17,"/r +2 Выживание",130271,null],[157906,"2026-08-13T11:52:41",9,"//Напомните где именно вы разложились, в лесу, на болоте, на окраине болота?",130271,null],[157907,"2026-08-13T11:55:11",17,"/В лесу",130271,null],[157908,"2026-08-13T11:56:56",9,"*Никого, но со стороны болота нарастает странный едва уловимый шум шелестения. Что-то там происходит ночью, но вы достаточно далеко чтобы не узнать.*",157905,null],[157909,"2026-08-13T12:01:28",17,"/ Я на стрёме 4 часа Люц спит, долгий отдых",130271,null],[157910,"2026-08-13T12:02:45",9,"*На рассвете странный шум из болота исчез. Ранние птицы чирикают, одну из них сожрала на лету змея, ничего необычного.*",130271,null],[157911,"2026-08-13T12:04:14",17,"\"Пойдем осмотрим руины на болотах, вдруг там тайник\"",130271,null],[157912,"2026-08-13T12:06:36",9,"*Летающая змея которую мельком увидел Фауст когда та поймала птицу в полёте.*",130271,null],[157913,"2026-08-13T12:13:03",17,"\"Ого, тут фауна опасная, змея летает, вооу\"",130271,null],[157914,"2026-08-13T12:13:34",17,"Чтобы избежать проблем с топями, фауст перемещается прыжками через своего двойника по 30 футов с кочки на кочку",130271,null],[157915,"2026-08-13T12:14:42",9,"*Много плотного свагнума по которому можно ходить, да и вода не такая густая чтобы, в ней можно и поплавать.*",157914,null],[157916,"2026-08-13T12:15:05",17,"\"Люц, догоняй, руины уже близко\"",130271,null],[157917,"2026-08-13T12:15:25",42,"// о блааа хирос оф меджик 3",157912,null],[157918,"2026-08-13T12:17:07",42,"— А?.. Чтоооо-оо...? \n\n\nговорит Люц с просони и видит летающую змею и резко бежит спотыкаясь от удивления за Фаустом",130271,null],[157919,"2026-08-13T12:18:39",9,"*На болоте живности на удивление нет, лишь слышно странное шуршание иногда где-то на краю восприятия.*",130271,null],[157920,"2026-08-13T12:19:22",17,"/r +3 Восприятие! КТо там шуршит",130271,null],[157922,"2026-08-13T12:20:11",9,"*Это кажется шуршание крылышек в кронах ив и болотных деревьев. Чтобы разглядеть прийдется подойти и посмотреть.*",157921,null],[157923,"2026-08-13T12:20:55",17,"\"Летает кто то, смотри тоже в оба или сколько там у тебя глаз?\"",130271,null],[157924,"2026-08-13T12:21:36",9,"//Идете дальше к разрушенному месту?",130271,null],[157925,"2026-08-13T12:22:05",17,"Дальше идёт к разрушенному строению на болоте",130271,null],[157926,"2026-08-13T12:22:26",42,"— да два глаза у меня!\n\nБежит за Фаустом жалобно крича обидку на мощный подъëб Фауста",130271,null],[157927,"2026-08-13T12:26:03",9,"*На шум с ближайшего дерева раздается мощное шуршание крылышек, из него небольшим роем, вылетают змии, но некогда ими любоваться вблизи.*\n\n//Кидаем иню",157926,null],[157928,"2026-08-13T12:26:55",9,"*Болотные змии.*\n\n//Только болота на фоне живые и в листве.",130271,null],[157929,"2026-08-13T12:26:59",17,"/r +4 Иня",130271,null],[157931,"2026-08-13T12:27:34",9,"/roll 1d20+5 летающие змии",130271,null],[157934,"2026-08-13T12:31:06",9,"/roll 1d2 кто из вас ближе, пусть два это жака",130271,null],[157936,"2026-08-13T12:34:14",17,"/ У меня призвано эхо оно чуть впереди нас было, если мимо него пролетит змея я хотел бы ее реакцией бамс",130271,null],[157937,"2026-08-13T12:35:42",9,"//Похоже это дерево сбоку или позади с которого слетели змеи, раз жака к ним ближе оказался. Он шел за тобой.",157936,null],[157938,"2026-08-13T12:36:02",17,"/ Хорошо",130271,null],[157939,"2026-08-13T12:36:14",17,"/ Впредь буду выставлять его в сторону шуршания)",130271,null],[157940,"2026-08-13T12:43:07",17,"/ @Jak_Zak ГОУ ДРАКА",130271,null],[157941,"2026-08-13T12:49:16",42,"/roll 1d20 +2 иня",157927,null],[157943,"2026-08-13T12:49:28",42,"// страшно",157940,null],[157944,"2026-08-13T12:50:12",9,"//Инициатива:\n\nРой летающих змей — 24\nРой летающих змиев — 10\nФауст — 7\nЛюц — 4",130271,null],[157946,"2026-08-13T12:51:32",9,"*Рой бросается в сторону ближайшего из вас, слетая с деревьев и жужа, их скорость... очень большая, они долетают и просто облепляют Люца со всех сторон.*",130271,null],[157947,"2026-08-13T12:51:48",9,"/roll 1d20+7 на Люца",130271,null],[157949,"2026-08-13T12:52:01",42,"// мимо",157948,null],[157950,"2026-08-13T12:52:11",9,"//Кд откуда такое?)",130271,null],[157951,"2026-08-13T12:52:16",42,"// хотя хз. Я не делал заявку что щит одел",130271,null],[157952,"2026-08-13T12:52:36",42,"// средние доспехи +2 от ловкость +2 щит который наверное я не одевал",157950,null],[157953,"2026-08-13T12:53:02",42,"// хекс блейд имеет доступ к средним доспехам и щитам",130271,null],[157954,"2026-08-13T12:53:06",9,"//Кд скок у тебя? Я не душню в первом бою, мож со щитом быть",130271,null],[157955,"2026-08-13T12:53:16",42,"// с щитом 18",157954,null],[157956,"2026-08-13T12:53:55",9,"*Броня достаточно крепка и парочку отогнав щитом никто не смог тебя укусить.*",157948,null],[157957,"2026-08-13T12:54:04",9,"//Ход Фауста, я думаю там не более 20-30 футов меж вами, вы вродь кучно шли",130271,null],[157958,"2026-08-13T13:26:20",17,"/Тут",130271,null],[157959,"2026-08-13T13:26:22",17,"/Сек читаю",130271,null],[157960,"2026-08-13T13:29:37",17,"Фауст отошел чуть дальше от врагов, руку вскинул в сторону ледяного клона, он лопнул снежинками и перенаправил руку в сторону ближайшей змеи. Ледяной демон воссоздался из воздуха рядом и тут же нанёс удар копией катаны Фауста",130271,null],[157961,"2026-08-13T13:29:52",17,"/ Бонуской призвал заново Эхо около врага, сам отошел. Между мной и врагами 35 футов",130271,null],[157962,"2026-08-13T13:29:59",17,"/r +6 Попал?",130271,null],[157964,"2026-08-13T13:30:13",17,"/r d8+6 Если попал рубящего",130271,null],[157966,"2026-08-13T13:30:36",17,"\"Они наверно ядовиты! Не попадайся друг\"",130271,null],[157972,"2026-08-13T13:37:08",42,"— спасибо за поддержку! Обнадëжил...",157966,null],[157973,"2026-08-13T13:37:22",17,"/ Твой ходик",130271,null],[157976,"2026-08-13T13:38:03",9,"//14 не попал)",130271,null],[157978,"2026-08-13T13:38:21",42,"// можешь везунчика если есть?",130271,null],[157980,"2026-08-13T13:38:43",17,"/ Да могу!",130271,null],[157982,"2026-08-13T13:38:52",17,"/ Везунчики 2/3!))",130271,null],[157984,"2026-08-13T13:40:09",9,"//Кстати, если вдруг насобираете опыта для лвл апа то сможете поднять его ток после длинного отдыха даж если хватает, я так делаю",130271,null],[157985,"2026-08-13T13:41:08",17,"/ Люц еби змеюк",130271,null],[157986,"2026-08-13T13:41:13",17,"/ Я экономлю ресурсы",130271,null],[157987,"2026-08-13T13:41:46",17,"\"Если можешь, отступи и давай расстреливать их издалека, мой клон будет отвлекать\"",130271,null],[157988,"2026-08-13T13:42:08",42,"Люц шëпотом читая предложение от договора взялся за гитару, его рука стала чернеть и тьма уходит в гитару\n\n— Мой покровитель. Я дарю тебе часть своей силы взамен на разрешение использовать тебя как оружие! \n\nГитара начала мутировать и обрастать плотью и лезвием пока не приняла форму боевой косы. Как это случилось действием бью змей",130271,null],[157990,"2026-08-13T13:42:45",42,"/roll d20 +6 +1 от улучшеного договора оружия",130271,null],[157992,"2026-08-13T13:43:39",42,"// попало? Или кд как у Тараска?)",157991,null],[157993,"2026-08-13T13:44:22",42,"/roll 1d8 +4 +1 режущего",130271,null],[157995,"2026-08-13T13:45:41",42,"— нет! Мне нужна свежая плоть! И бойня! \n\nОтвечает Люц уже не своим голосом, как буд-то он стал одержим когда гитара приняла форму оружия",157987,null],[157996,"2026-08-13T13:45:52",42,"// ход",130271,null],[157997,"2026-08-13T13:46:06",17,"\"О как, ну ладно, тогда разделаемся с ними быстро!\"",130271,null],[157998,"2026-08-13T13:46:15",9,"/roll 1d20+7 люц похоже не отошёл",130271,null],[158001,"2026-08-13T13:46:57",42,"// говорите что хотите но когда мои персонажи полностью уходят в отыгрыш. Они получают силу всех за одного",130271,null],[158002,"2026-08-13T13:47:52",9,"*Змии тыкаются в Люца, им не везёт, каждый укус в броню. Кровожадные твари без разума.*\n\n//По ним удары с преимуществом до их след хода",157999,null],[158003,"2026-08-13T13:48:34",9,"/roll 1d2 на удачу твою бедную",157995,null],[158005,"2026-08-13T13:48:47",9,"/roll 1d20+5 иня",130271,null],[158008,"2026-08-13T13:49:39",42,"// мы всë равно на дне инициативы",130271,null],[158009,"2026-08-13T13:50:02",9,"*На шум летит ещё рой гадюк, уже со спины фауста но они немного далеко, не успевают.*\n\n//Ход второго роя",158006,null],[158010,"2026-08-13T13:50:17",17,"/За моей спиной да?",130271,null],[158011,"2026-08-13T13:50:20",9,"//Вот)",157944,null],[158012,"2026-08-13T13:50:48",17,"\"Люц, похоже нужно срочно прорубить отдну сторону иначе нас окружат\"",130271,null],[158013,"2026-08-13T13:50:54",17,"/Сколько тварей там где люц и клон?",130271,null],[158014,"2026-08-13T13:51:00",17,"/ Или это рой",130271,null],[158015,"2026-08-13T13:51:18",9,"//Это уже 2 роя",130271,null],[158016,"2026-08-13T13:51:27",17,"Фауст присматривается сколько Люц свомг убить своим ударом",130271,null],[158017,"2026-08-13T13:51:45",9,"*Добрую треть покромсал.*",158016,null],[158018,"2026-08-13T13:51:45",17,"/ Мне нужно понять какова его плотность 12 урона это много или почти ничего или средне",130271,null],[158019,"2026-08-13T13:51:49",17,"/Пон",130271,null],[158020,"2026-08-13T13:52:13",17,"Рубящим ударом фауст рубит воздух, а клон дублирует атаки по летучим змеям",130271,null],[158021,"2026-08-13T13:52:16",17,"/r +6 q",130271,null],[158023,"2026-08-13T13:52:23",17,"/Везунчик!",130271,null],[158025,"2026-08-13T13:52:29",17,"/ Всё",130271,null],[158026,"2026-08-13T13:52:31",17,"/ Синема",130271,null],[158029,"2026-08-13T13:53:13",9,"*Фауст стал куда то не туда и вгруз в болото по пояс.*\n\n//Считай ничком лежишь",130271,null],[158030,"2026-08-13T13:53:24",17,"/ Это повезло",130271,null],[158031,"2026-08-13T13:53:40",17,"/Меняюсь местами с клоном за 15 футов скорости",130271,null],[158032,"2026-08-13T13:53:51",17,"/И встаю за 15",130271,null],[158033,"2026-08-13T13:54:43",17,"Ледяное сердце разогнало кровь быстрее Фауст провалился в топь и упал, но сразу же поменялся с клоном местами вскочил на ноги и еще раз рубанул по змеям уже сам",130271,null],[158034,"2026-08-13T13:54:49",17,"/r +6 Крита НЕ будет!",130271,null],[158036,"2026-08-13T13:54:58",17,"/r d8+6 Рубящий",130271,null],[158038,"2026-08-13T13:55:09",17,"/Всплеск действий потратил",130271,null],[158039,"2026-08-13T13:55:32",42,"// ход?",130271,null],[158040,"2026-08-13T13:56:08",17,"Клон поднимается готовый отражать атаку с тыла",130271,null],[158043,"2026-08-13T13:59:39",42,"Коса люца загорелась зелёный и мëртвой энергией, после сразу же наносит удар по змеям что спереди его",130271,null],[158044,"2026-08-13T14:00:01",42,"/roll 1d20 +6 нанесение ран от черты",130271,null],[158046,"2026-08-13T14:00:37",42,"/roll 3d10 +4 некротикой",130271,null],[158048,"2026-08-13T14:00:53",9,"//Не щабудьте списать по рациону за прошедший день",130271,null],[158049,"2026-08-13T14:01:11",17,"/ Ок щас менеджментом займусь",130271,null],[158050,"2026-08-13T14:01:22",9,"//Описывай что произошло с роем что тебя окружал что он истлел нах",158047,null],[158051,"2026-08-13T14:03:39",42,"— ФАУС ПРИГНИСЬ! \n\nКак Люц наполнил косу энергией своей тëмной души она больше не резала, она иссушала всего чего касась. Как магия дала о себе знать Люц решил сделать круговой удар своею косой и все твари просто превратились в исохший пепел",158050,null],[158052,"2026-08-13T14:03:55",17,"Пригнулся сразу",130271,null],[158053,"2026-08-13T14:05:02",17,"/Щас сливаем все самое мощное на рой змей!))",130271,null],[158054,"2026-08-13T14:05:06",9,"/roll 1d20+7 рой змиев рядом с Фаустом атакует его, полез прямо к ним",130271,null],[158056,"2026-08-13T14:05:19",42,"// это бесплатно. Черта тронутый тенью. Короткий отдых и кайф",158053,null],[158057,"2026-08-13T14:05:40",9,"// @dunchev попал?",158055,null],[158058,"2026-08-13T14:07:39",17,"/Неа у меня КД19 Бригантина 13 +4 ловкость +2 щит",130271,null],[158059,"2026-08-13T14:07:50",17,"/ Они пролетели мимо клона же? Могу провокацию?",130271,null],[158060,"2026-08-13T14:08:01",42,"// щиты нас оберегают",130271,null],[158061,"2026-08-13T14:08:15",9,"//Ты рядом с ними стоял не? Атаковал в прошлом ходу как)",158059,null],[158062,"2026-08-13T14:08:17",17,"Фауст отбился железной перчаткой от змеиных нападок",130271,null],[158063,"2026-08-13T14:08:29",17,"/ У меня заявка была простая, я бонуской могу меняться с эхо",158061,null],[158064,"2026-08-13T14:08:41",17,"/ Местами. Пуф и я около Люца а клон там где был я",130271,null],[158067,"2026-08-13T14:09:25",9,"//Хм, думаю вряд ли они провоцированную хватонули, твой ход всё равно",130271,null],[158068,"2026-08-13T14:09:36",17,"/ Почему? Клон же был на их пути к нам",130271,null],[158069,"2026-08-13T14:09:45",17,"/ Я через клона могу провоцированные давать",130271,null],[158070,"2026-08-13T14:09:50",9,"//А ты с ним поменялся",130271,null],[158071,"2026-08-13T14:09:55",17,"/ С ним с ним",130271,null],[158072,"2026-08-13T14:09:58",42,"// телепортация не вызывает провакационные если ты не с чертой страж или убийца магов",158067,null],[158073,"2026-08-13T14:10:10",17,"/ Да это не про то",130271,null],[158074,"2026-08-13T14:10:25",9,"//Ты 2 раза поменялся местами успел?",130271,null],[158075,"2026-08-13T14:10:25",17,"/ нарисовать чтоле",130271,null],[158076,"2026-08-13T14:10:31",17,"/ сек",130271,null],[158077,"2026-08-13T14:11:15",42,"// клон был возле меня. А он был в трясине. И решил поменяться местами с клоном. Теперь он со мной, а клон в трясине",158074,null],[158078,"2026-08-13T14:11:25",9,"//Ну, я пытаюсь понять. Фауст подбежел, провалился, рядим ьыл клон... а, типа они на клетку все равно передвинулись",130271,null],[158079,"2026-08-13T14:11:34",17,"/ да но клон не существо он ен может лежать и тд он просто атм стоит и встречает",130271,null],[158080,"2026-08-13T14:11:56",42,"// ну я говорю образно что просто местами поменялись",158079,null],[158081,"2026-08-13T14:11:58",9,"//Короче бей провоцирку)",130271,null],[158082,"2026-08-13T14:12:46",17,"/ Давай разберем щас один раз чтобы все понимали, рыцарь эхо это сложная хуйня, я понимаю",130271,null],[158083,"2026-08-13T14:12:50",17,"/ 1 ход было так",130271,null],[158084,"2026-08-13T14:13:18",42,"// сложная хуйня начинается когда получишь 7 лвл..",158082,null],[158085,"2026-08-13T14:13:19",17,"/ 2 ход я поменялся когда провалился и появился 2 рой стало так",130271,null],[158086,"2026-08-13T14:13:31",17,"/ Я только в 3 его, дальше песня клинка",158084,null],[158087,"2026-08-13T14:13:49",9,"//А, ты бил не второй рой а первый!",130271,null],[158088,"2026-08-13T14:13:57",17,"/ Сейчас вот так 3 ход",130271,null],[158089,"2026-08-13T14:13:57",9,"//Тогда на места стало",130271,null],[158090,"2026-08-13T14:14:08",17,"/ 1 рой убит. Второй пролетал через клона ко мне",130271,null],[158091,"2026-08-13T14:14:17",9,"//Так потому что я думал что вместо клона ты)",130271,null],[158092,"2026-08-13T14:14:31",9,"//Так бы клона ударили, но пох",130271,null],[158093,"2026-08-13T14:14:40",9,"//Провоцирку и пляшем",130271,null],[158094,"2026-08-13T14:14:41",17,"/ ну вот могу меняться с ним местами я так и передвигаюсь в опасных местах его вперед и пуф поменялся",130271,null],[158095,"2026-08-13T14:14:54",17,"/r +6 Провоцирка",130271,null],[158097,"2026-08-13T14:15:00",17,"/r d8+6 Ныа",130271,null],[158099,"2026-08-13T14:15:19",9,"//Твой ход теперь",130271,null],[158100,"2026-08-13T14:15:39",42,"// урааа. Так..? Теперь змейки рядом со мной тоже?",130271,null],[158101,"2026-08-13T14:15:59",17,"С разворота рассекающим ударом рублю змей",130271,null],[158102,"2026-08-13T14:16:02",9,"//Да чё",158088,null],[158105,"2026-08-13T14:16:13",17,"/ ОПА",130271,null],[158107,"2026-08-13T14:16:39",42,"// раскладка языков вечный враг))",158105,null],[158108,"2026-08-13T14:16:43",9,"*Осталось всего несколько змей.*",158104,null],[158109,"2026-08-13T14:19:31",42,"— Оставь мне тоже!! \n\nЛюц делает разбег. В процессе разбега коса опять начала опять обрастать плотью и железом, теперь у косы на двух концах лезвие и в прыжке начал раскручивать косу (атака) на змей",130271,null],[158110,"2026-08-13T14:19:41",42,"/roll d20 +6 +1",130271,null],[158112,"2026-08-13T14:20:09",42,"// всë. Ход. Ноу пафос",130271,null],[158113,"2026-08-13T14:20:49",9,"*Когда люц прямо ныряет к ним змии пытаются его царнуть, уж больно размашисто он мохал руками.*",130271,null],[158114,"2026-08-13T14:20:55",9,"/roll 1d20+7",130271,null],[158116,"2026-08-13T14:21:27",9,"*Но в отместку и они не могли за него уцепиться.*",130271,null],[158118,"2026-08-13T14:21:44",9,"//Описывайте как додавали пару последних гадюк",130271,null],[158119,"2026-08-13T14:21:46",42,"// как в героях меча и магии 3 змеи слабый Т3 юнит. Как и тут слабый моб",130271,null],[158120,"2026-08-13T14:22:34",42,"// что джекпот устроим из ДМК? У меня есть арбалет. А у тебя?",158118,null],[158122,"2026-08-13T14:23:46",9,"//Давайте уде че нить, я могу по приколу заспавнить вам 3д100 крабов с ножами, но к сожелению их тут нет, змии всё выжрали",158120,null],[158123,"2026-08-13T14:24:19",42,"// если Коля согласится. То так их и гасим. По стреле на тварь скрестив арбателы",130271,null],[158125,"2026-08-13T14:26:51",17,"/ Опиши Жака максимальный пафос",130271,null],[158126,"2026-08-13T14:27:02",17,"/ Я чур Вергилий",130271,null],[158129,"2026-08-13T14:27:49",42,"// конечно. Данте мой любимчик",158126,null],[158132,"2026-08-13T14:30:54",42,"Подойдя прижашись плечом к плечу товарища Люц достал из пазухи арбалет и цыкнул ему намекнув на совместный выстрел. Фауст выставив арбалет боком, а Люц прямо скрестив оружие, а после совместной фразы \"Сдох\" делают одновременный выстрел по каждой тваре по стреле",130271,null],[158139,"2026-08-13T14:36:25",42,"// ну такой мог только пафос высрать",158132,null],[158140,"2026-08-13T14:37:16",9,"*Болты прошили змиев и те упали на пол, в каждом было по стреле. Пока тихо, где-то на краю сознания слышно шуршание, в этом месте лучше не шуметь.*\n\n*Пройти ещё немного и перед вами виднелся замок? Скорее его наклонённая верхушка с изломленной башней что видна была в далеке. Заросший плющом, рядом ивы, в это месте никого нет, а ещё, на деревьях возле этой крепости сидят змии, много, но они пока не потревоженны. Отдыхают или спят.*",130271,null],[158143,"2026-08-13T14:39:13",9,"//Опыт:\n\nЛюц: \"350\"\n(200 змии +100 за арку с деревней и +50 за отыгрыш)\nФауст: \"400\"\n(200 змии +100 за арку с деревней и 100 за отыгрыш)\n\nPs: Пока так, выдам сейчас пока не забыл, а там дальше посмотрим ,)",130271,null],[158144,"2026-08-13T14:41:08",42,"// 1350 опыта это лвл ап? Я тупой убейте. Играю в днд только ради отыгрыша",130271,null],[158145,"2026-08-13T14:41:56",9,"// На 4й \"2700\" надо",130271,null],[158146,"2026-08-13T14:42:41",42,"// ладно, я не забуду как драл второй лвл почти месяц на него",130271,null],[158147,"2026-08-13T14:42:53",42,"// жаловаться не на что",130271,null],[158156,"2026-08-13T14:47:46",42,"Закончив бой. Из косы выходит тëмная энергия обратно по венам люца и так до груди, опустошив косу она начала съëживаться как хозяйство зимойдо своих размеров, плоть начала столбенеть в древесину, а лезвие впитавшись с кровью змей внутрь словно пропали так как будто это всегда была гитарой (якобы подношение покровителю за помощь \"кровь врагов\")",158140,null],[158172,"2026-08-13T16:08:46",17,"\"Похоже твой жучиный бог крут в бою!\"",158156,null],[158173,"2026-08-13T16:09:17",17,"\"Ладно, давай осмотрим уже эти руины, ради чего вся эта возня\"\n\nФауст пошел осматривать старые развалины на болоте",130271,null],[158174,"2026-08-13T16:09:23",17,"/r +3 Внимание",130271,null],[158177,"2026-08-13T16:10:12",42,"Люц помогает Фаусту осматривать руины",158175,null],[158178,"2026-08-13T16:10:29",42,"// перекинь",158175,null],[158310,"2026-08-13T17:33:53",9,"//Это у вас что там крит на крите псли не 1 то 20)))",130271,null],[158319,"2026-08-13T17:37:16",9,"*Возле этих руин поросших ивами и деревьями кишмя кишат летающие змеи, их не две и не три, а сотни. Внутри не видно что, но остались залы верхних этажей что ещё не ушли в болото. На самом здании можно заметить странные полосы, будто плющ и травы которые на нём растут иногда сминают в таком виде, полосы широкие, шириной в человека или немного толще.*",158180,null],[158326,"2026-08-13T17:38:39",17,"\"Этот плющ будто сдавил здание и разломал его, смотри какой мощный. Попробуем пройти аккуратно мимо змей? Бригантина гремит как бубен, мать её\"",130271,null],[158351,"2026-08-13T17:42:30",9,"//То чувство когда получил помеху на скрыт ради +1 кд)))",130271,null],[158365,"2026-08-13T17:47:51",17,"/Пока не пробили, оправдывается",130271,null],[158560,"2026-08-13T18:25:32",42,"// я тут",130271,null],[158562,"2026-08-13T18:26:06",17,"\"В обломках может что то быть, но плющ наверное опасный. Я за то чтобы рискнуть\"",130271,null],[158564,"2026-08-13T18:26:11",17,"\"Пошарим там\"",130271,null],[158570,"2026-08-13T18:26:57",42,"— полностью с тобою согласен. У меня есть факела и трудница. Можем сожëм плющ? Или идея так себе?",130271,null],[158575,"2026-08-13T18:27:41",17,"\"Тут сотни змей, они слетятся на нас и задавят мясом, так что, давай попробуем сперва проверить издалека, кинуть в него камень или выстрелить может?\"",130271,null],[158591,"2026-08-13T18:29:42",42,"— можем выстрелить\n\nЛюц достал из пазухи арбалет и ждëт подтверждение товарища чтобы сделать выстрел",130271,null],[158599,"2026-08-13T18:31:11",17,"А Фауст кивает ставя клона ближе к этому стеблю плюща",130271,null],[158609,"2026-08-13T18:32:24",42,"Люц увидев знак шмаляет из арбалета",130271,null],[158642,"2026-08-13T18:37:33",9,"//В здание просто?",158609,null],[158652,"2026-08-13T18:38:15",42,"// в стебель плюща",158642,null],[158659,"2026-08-13T18:39:03",9,"*Стрела просто застряёт в зарослях, это обычный плющ, наверное даже не ядовитый.*",158609,null],[158663,"2026-08-13T18:39:58",42,"/roll 1d20 +4 выживание. Пытается понять природу плюща и всю его родословную",130271,null],[158672,"2026-08-13T18:41:23",9,"*Дядюшка плющ, обычный лесной и не ядовитыйс такой везде растёт и в лесу где вы шли до этого болота постоянно встречался.*",158664,null],[158675,"2026-08-13T18:42:49",42,"— Фауст. Плющ то нормальный и не ядовит. \n\nПрошëлся пальцем по его соку и лизнул этот же палец",130271,null],[158683,"2026-08-13T18:44:21",9,"//Вы к самому зданию подошли впритык? Я не заметил когда",158675,null],[158687,"2026-08-13T18:44:58",17,"Подойдя ближе помогает осмотреть место попадания и сок растения",158663,null],[158688,"2026-08-13T18:45:00",17,"/Помощь",130271,null],[158694,"2026-08-13T18:45:56",42,"// ща узнается что у него нейротоксины как у каменного паука)",158690,null],[158713,"2026-08-13T18:48:16",9,"*Плющ как плющ, обросло здание всё им, а ещё над головой в деревьях уже четкое трепыхание крылышек, уже знакомых вам змиев. Тут их намного больше чем две стайки.*",158690,null],[158716,"2026-08-13T18:49:05",42,"/roll 1d20 +4 спас",130271,null],[158719,"2026-08-13T18:49:17",9,"//От чего?",158717,null],[158725,"2026-08-13T18:49:42",42,"// блааа. Я в другую игру это должен был написать, но туда пришло",130271,null],[158729,"2026-08-13T18:50:27",9,"*Ты видишь огромный длинный след на плюще, словно кто-то его смял ползя по зданию.*",158687,null],[158901,"2026-08-13T19:27:06",17,"\"Это ползучая гадина огромна. Змея… как пить дать.\"",130271,null],[158905,"2026-08-13T19:27:32",17,"/r +3 Фауст ищет что то полезное в развалинах",130271,null],[158936,"2026-08-13T19:34:43",9,"//Лезишь внутрь? Опиши как ты это делаешь)",158905,null],[158940,"2026-08-13T19:36:01",17,"/ Я потерял описание. Там есть щель или спуск вниз разрушенного здания?",130271,null],[158946,"2026-08-13T19:36:33",17,"Фауст создаёт внутри разрушенного здания клона и меняется с ним местами оказывается в низу",130271,null],[158965,"2026-08-13T19:41:06",9,"*Лидыжки в воде и ряске, здание который век уходит под воду, видны остаки мебели, каких то совсем уж выцвевших габеленов и что-то блестит в воде, но это не монетка, напоминает...*",158946,null],[158979,"2026-08-13T19:44:46",17,"Фауст быстрым движением хватает блестяшку",130271,null],[159003,"2026-08-13T19:50:42",9,"*Это багровая капля? Скорее чешуйка и она очень крупная. Ты в каком-то просторном зале и сейчас здесь очень тихо и мрачно.*",158979,null],[159083,"2026-08-13T20:18:17",17,"Положу чешуйку в суму и осмотрюсь здесь ещё. Какой то знатный род жил в этом месте видимо",130271,null],[159084,"2026-08-13T20:18:23",17,"/r +3 Повнимательнее",130271,null],[159101,"2026-08-13T20:21:57",9,"//Жаку бы",130271,null],[159103,"2026-08-13T20:22:08",17,"/ Ждем",130271,null],[159104,"2026-08-13T20:22:20",17,"/ @Jak_Zak",130271,null],[159211,"2026-08-13T22:03:58",42,"// извиняюсь. Я уснул",130271,null],[159679,"2026-08-14T16:27:37",42,"— да да.. Пошëл я нахер.. Ну ладно других вариантов нету\n\nЛюц кастует на себя невидимость чертой и взбирается за Фаустом, ибо его трагали тени, а не феи чтобы уметь телепортироваться",158946,null],[159688,"2026-08-14T17:15:35",9,"*Раздаётся напряжённое шипение, в этом месте эхом отдающееся от стен, не разобрать окуда оно.*",130271,null],[159689,"2026-08-14T17:23:08",42,"// хард я знаю что у тебя ненависть к приручениям. Но если я смогу чисто в теории.. Не будешь против если у меня будет ручная змея летучая?",130271,null],[159690,"2026-08-14T17:26:38",9,"//Не против, но чтобы она в бою работала прийдётся дрессировку выучить через мудрость, учти",159689,null],[159691,"2026-08-14T17:29:26",17,"Ледяной клон встаёт на защиту\n\n\"Откуда звук?\"",130271,null],[159692,"2026-08-14T17:29:50",17,"/r +4 Восприятие",130271,null],[159695,"2026-08-14T17:33:42",9,"*Звук везде, чёрт знает откуда, может из комнат, может из тьмы на границе твоего восприятия, а может за спиной куда не смотрят глаза.*",159693,null],[159696,"2026-08-14T17:34:26",17,"Фауст присматривается к портретам",130271,null],[159697,"2026-08-14T17:35:42",9,"*Пустые выгоревшие рамки, на тканях их красок едва угадываются очертания картин. Шипение исчезло, нечто знает о вас.*",159696,null],[159698,"2026-08-14T17:41:18",42,"Люц пытается уловить слухом от куда именно и ближе всего исходит жужание, паралельно добираясь до своего товарища по оружию",130271,null],[159700,"2026-08-14T17:41:32",42,"/roll 1d20 +4 восприятие",130271,null],[159704,"2026-08-14T17:44:50",9,"*Жужания нет, пчёл здесь не водится.*\n\n//Шучу\n\n*Шипение идёт кажется откуда-то сверху.*",159701,null],[159716,"2026-08-14T17:50:44",17,"/ Бля у меня щас везде одни крит провалы это пздц",130271,null],[159734,"2026-08-14T18:03:18",42,"— понятно.. \n\nЛюц дальше добирается до своего товарища. \n\n//Как далеко ещë?",159704,null],[159739,"2026-08-14T18:04:48",9,"*Вы примерно в одном зале, \"тзззззз\" раздается звук трения о камни.*\n\n//Фауст может перекинуть восприятие",159734,null],[159740,"2026-08-14T18:05:26",17,"/r +4 Перекид",130271,null],[159748,"2026-08-14T18:08:25",9,"*Гремит, не понятно откуда. Момент, второй, напряжение... и в моменте на тебя сверху падают крошки кирпичей.*\n\n//Ты поднимаешь глаза?)",159741,null],[159750,"2026-08-14T18:09:10",17,"Фауст напрягся и выставил тут же клона перед собой смотрит через егоп розрачное ледяное тело вперед",130271,null],[159752,"2026-08-14T18:09:43",42,"// помогаю\n\nЛюц вместе слушает с фаустом",159741,null],[159756,"2026-08-14T18:10:11",42,"// уже лучше дружище",159753,null],[159758,"2026-08-14T18:11:39",9,"*Впереди ничего нет, а вот на голову падает огромнеший змей, он открыл рот готовый ухватить жертву в рывке.*",159753,null],[159759,"2026-08-14T18:12:00",9,"/roll 1d2 по фаусту или клону, на еденице фауст",130271,null],[159762,"2026-08-14T18:12:48",9,"/roll +d20+5 из засады, на потолок так никто и не поднял глаза даже когда на голову упала каменная крошка",130271,null],[159764,"2026-08-14T18:13:34",9,"// @dunchev , ты там можешь реакцией местами с клоном поменяться, мне страшно кидать урон. Или нет у тебя такой функции?",130271,null],[159766,"2026-08-14T18:14:05",17,"/ Нету",130271,null],[159768,"2026-08-14T18:14:20",17,"/ Только бонусным действием",130271,null],[159770,"2026-08-14T18:14:36",17,"/ Погоди, посчитаю везунчики",130271,null],[159771,"2026-08-14T18:14:42",17,"/ Щас собью его крит",130271,null],[159772,"2026-08-14T18:15:12",17,"/ 1/3 есть",130271,null],[159774,"2026-08-14T18:15:23",17,"/ Выбираю 12 +5 = 17 это промах",130271,null],[159780,"2026-08-14T18:18:12",17,"Огромный змей с потолка падает открыв пасть, в последний момент в отражении ледяного клона фауст замечает угрозу и уклоняется в сторону\n\nСразу занеся меч для атаки",130271,null],[159781,"2026-08-14T18:18:17",17,"/r +4 Ини",130271,null],[159785,"2026-08-14T18:19:32",42,"/roll 1d20 +2 иня",130271,null],[159788,"2026-08-14T18:20:28",9,"*Багровый змей шумно падает на пол, всплеск воды, несколлько кирпичей падает вниз. Огромный, он вывалился в дыру в потолке, одну из нескольких в этом зале. Выровнявшись, тот гордо поднялся над вами, промах? Это пока, вертикальные зрачки уже сосредоточились на жертве которую багровый змей не смог достать...*",130271,null],[159789,"2026-08-14T18:20:32",9,"/roll 1d20+3 иня",130271,null],[159791,"2026-08-14T18:20:59",17,"\"Змеиное болото... Думаю местные его так и называют\"",130271,null],[159792,"2026-08-14T18:21:03",9,"/roll 1d4 в этом ходу мелких змиев налетело",130271,null],[159803,"2026-08-14T18:23:21",42,"— смешная игра слов. Но змеи тоже кровь имеют. Так что мой покровитель будет счастлив такой жертве!",159791,null],[159805,"2026-08-14T18:23:46",9,"//Инициатива:\n\nЛюц — 21\nБольшой змей с рубиновой чешуёй — 14\nФауст — 12\nЛетающие змии 9 шт — последние",130271,null],[159816,"2026-08-14T18:24:48",9,"*Змей изворачивается занимая добрую часть пространства, он угрожающе шипит.*\n\n//Люц, ходи, он занимает условно куб из 4 клеток",130271,null],[159829,"2026-08-14T18:26:56",42,"Люц достав гитару и чутка подумав глянув на катану товарища решил ему подыграть. Тьма из его души вышла в гитару, гитара снова начала мутировать, но в этот раз это уже красная катана. И действием он начал излучать ужасающую ауру (саван смерти) ужасая врагов",130271,null],[159831,"2026-08-14T18:27:06",42,"// спас мудрости от испуга, сложность 14",130271,null],[159837,"2026-08-14T18:27:40",9,"/roll +d20+5 мудрость змея",130271,null],[159841,"2026-08-14T18:27:55",42,"// все враги от меня на 30 футов ужасаются если провалили",130271,null],[159844,"2026-08-14T18:28:12",42,"// ход",130271,null],[159846,"2026-08-14T18:28:16",9,"/roll 1d20 мудрость летающего",130271,null],[159849,"2026-08-14T18:28:43",9,"*Летающий змий сыбался так и не подлетев к вам.*",130271,null],[159851,"2026-08-14T18:29:09",9,"//Это как ты понял был багровый)",159838,null],[159853,"2026-08-14T18:29:27",42,"// видно. Мудрая падла",159851,null],[159854,"2026-08-14T18:29:37",9,"/roll 1d3 три это клон, два фаут, один жак",130271,null],[159856,"2026-08-14T18:30:13",42,"// хуярь. Щас цыганские фокусы покажу",159854,null],[159857,"2026-08-14T18:30:36",9,"//Кстати, напомни, невидимость же вродь снялась от твоего савана?",130271,null],[159859,"2026-08-14T18:31:03",42,"// нет. Они не мешают друг другу. Это не атака, а просто аура ужаса",159857,null],[159861,"2026-08-14T18:31:17",9,"//Тогда переброс",130271,null],[159862,"2026-08-14T18:31:27",9,"/roll 1d2 одиничка эт фаут",130271,null],[159864,"2026-08-14T18:31:31",17,"/ Давай",130271,null],[159866,"2026-08-14T18:31:42",9,"/roll 1d20+5 атака по клону",130271,null],[159868,"2026-08-14T18:31:44",17,"/ У Клона сейчас 16КД",130271,null],[159871,"2026-08-14T18:31:48",17,"/ Убит 1 хит",130271,null],[159872,"2026-08-14T18:31:57",17,"/ НО КЛОНЫ АХАХАХ БЕСКОНЕЧНЫЕ",130271,null],[159875,"2026-08-14T18:32:23",42,"// апхахахха. Устроим ему метал край",159872,null],[159876,"2026-08-14T18:32:32",9,"*Тшшшш, клон распадается на осколки, змей понял что что то не так и недобро взглянул уже на фауста.*\n\n//Ход",130271,null],[159878,"2026-08-14T18:33:04",42,"// змия летающего кстати убери. Если он съебался",130271,null],[159882,"2026-08-14T18:33:49",17,"Фауст молча смотрит как глупи змей  разбивает ледяного клона и тут же создаёт нового перед собой, сам огибает змея чтобы окружить с люцифером и бьёт клинком ему в брюхо. Высвобождая потенциал ледяного демона, клон тоже атакует ледяными когтями",130271,null],[159883,"2026-08-14T18:33:54",17,"/r +6 q +6 q",130271,null],[159885,"2026-08-14T18:34:03",17,"/ Невезёт",130271,null],[159887,"2026-08-14T18:34:15",17,"/ Конец хода\n\nВезучик 0/3\n\nВысвобождение потенциала 2/3",130271,null],[159888,"2026-08-14T18:34:23",9,"//А ток ты бьёшь?",130271,null],[159889,"2026-08-14T18:34:39",42,"// Эх.. Дайте мне палочку дережëра. Я такую песню нашëл для боëвки",130271,null],[159890,"2026-08-14T18:34:50",9,"//Типа, это вродь броски без преимущества)",159884,null],[159892,"2026-08-14T18:35:04",9,"//Ты окружал змея?",130271,null],[159895,"2026-08-14T18:35:28",42,"// а как? Клона нет. Я невидем",130271,null],[159906,"2026-08-14T18:36:03",17,"/ Бью я и клон",159888,null],[159907,"2026-08-14T18:36:09",17,"/ Я нового бонуской создал",130271,null],[159909,"2026-08-14T18:36:17",17,"/ Че можно окружить если жак рядом невидимка?",130271,null],[159910,"2026-08-14T18:36:23",42,"// это какой-то детский утренник",159902,null],[159912,"2026-08-14T18:36:31",9,"//С клоном нельзя окружать?",159909,null],[159919,"2026-08-14T18:36:57",17,"/ Нет это не существо, неживое, он как предмет, как коробка, кусок стены, за ним есть укрытие на 1/2",159912,null],[159923,"2026-08-14T18:37:07",9,"//Тогда Жак!",130271,null],[159925,"2026-08-14T18:37:18",42,"// Жак, Жак. Да да",159909,null],[159927,"2026-08-14T18:37:33",17,"/ Вот тогда с окружения",130271,null],[159929,"2026-08-14T18:37:36",9,"*Мечи отскакивают от крепкой чешуи выбивая искры.*",159884,null],[159932,"2026-08-14T18:37:45",17,"/r d8+6 Если можно ну или нет смотри сам мастер",130271,null],[159935,"2026-08-14T18:37:59",42,"// Джек пот",159933,null],[159937,"2026-08-14T18:38:03",9,"//Мне бы понять можно или нет",159932,null],[159939,"2026-08-14T18:38:15",42,"// 25 не пробил?!?",159937,null],[159940,"2026-08-14T18:38:24",9,"//Пусть будет так уже",130271,null],[159944,"2026-08-14T18:38:37",42,"// да. Я невидим. Но окружение работает",130271,null],[159953,"2026-08-14T18:39:10",9,"*На твердом панципе выбилось несколько чешуек.*",159933,null],[159956,"2026-08-14T18:39:29",27,"// Там ещё один новичок, босс",159953,null],[159961,"2026-08-14T18:40:26",42,"// мой ход?",130271,null],[159969,"2026-08-14T18:41:21",9,"//Если фауст походил)",130271,null],[159973,"2026-08-14T18:41:41",42,"// оке",130271,null],[159975,"2026-08-14T18:41:42",17,"/ Да я все ребят",130271,null],[159976,"2026-08-14T18:41:44",17,"/ Ходи",130271,null],[159978,"2026-08-14T18:41:48",9,"/roll 1d4 летающих змиев прилетевших на шум в начале раунда",130271,null],[159983,"2026-08-14T18:42:12",17,"/ Буду в дороге. Мы следующий ход это ударить гада дважды с окружением. Потрачу ещё одно использование высвободить потенциал.",130271,null],[159990,"2026-08-14T18:42:57",17,"/r +d20+6 q1 +d20+6 q2\n\nd8+6 q1\n\nd8+6 q2",130271,null],[159993,"2026-08-14T18:43:07",17,"/ Опа крит",130271,null],[159994,"2026-08-14T18:43:09",42,"Рука люца начала издавать невидимую тëмную ауру и выпрямив руку в сторону больший змееи он пытается нащупать еë душу, найдя еë он сжимает кулак ставя особую метку своего покровителя в душе твари",130271,null],[159995,"2026-08-14T18:43:16",9,"//Эт на след ход?)",159991,null],[159996,"2026-08-14T18:43:17",17,"/r d8+6 Ещё к кому урона",130271,null],[160000,"2026-08-14T18:43:21",17,"/ Да да",159995,null],[160002,"2026-08-14T18:43:32",17,"/ ой минус 6 вычтем",130271,null],[160003,"2026-08-14T18:43:35",17,"/ Лишнего",130271,null],[160008,"2026-08-14T18:44:50",42,"После Люц наносит удар твари. Катана начала гореть зелёный пламенем покрытая некрозом и наносит удар багровой змее",130271,null],[160009,"2026-08-14T18:44:55",9,"//Давай жак)",130271,null],[160011,"2026-08-14T18:45:02",42,"/roll +d20 +6 +1",130271,null],[160019,"2026-08-14T18:45:34",42,"/roll 4d10 +5 нанесение ран",130271,null],[160023,"2026-08-14T18:46:02",42,"// теперь я видимый и ход",130271,null],[160026,"2026-08-14T18:46:43",17,"/ Пошла ебка",130271,null],[160028,"2026-08-14T18:46:51",9,"*Некротическая энергия частично впитывается чешуёй и теперь сам змей дымится этой злой энергией, она не твоя...*",160020,null],[160030,"2026-08-14T18:47:04",9,"/roll 1d20+5 по Люцу",130271,null],[160033,"2026-08-14T18:47:26",42,"// 32 урона. Из-за метки добавляется урон от БМ",130271,null],[160034,"2026-08-14T18:47:36",9,"*Дым развеивается когда челюсти так и не смогли ухватить Люца.*",130271,null],[160036,"2026-08-14T18:48:08",9,"//Потом был урон от Фауста",130271,null],[160039,"2026-08-14T18:48:18",9,"/roll 1d3 на кого нападет змий",130271,null],[160041,"2026-08-14T18:48:39",9,"/roll 1d20+5 в фауста летающая змея кидается",130271,null],[160044,"2026-08-14T18:49:08",9,"*Только мельтешит перед глазами.*\n\n//Ход",160042,null],[160046,"2026-08-14T18:49:26",9,"/roll 1d4 ещё летающие змии в начале хода",130271,null],[160048,"2026-08-14T18:50:15",9,"*На шум боя слетается всебольше крылатых гадюк.*",160047,null],[160049,"2026-08-14T18:50:20",9,"//Жак!",130271,null],[160051,"2026-08-14T18:50:42",42,"Люц взмахивает катаной на рубиновую змею. Атака покровителем!",130271,null],[160053,"2026-08-14T18:51:04",42,"/roll +d20 +6 +1",130271,null],[160056,"2026-08-14T18:51:36",42,"/roll d8 +4 +1 магический режущий",130271,null],[160062,"2026-08-14T18:52:33",42,"// ход",130271,null],[160066,"2026-08-14T18:53:22",9,"*Рубиновый змей уже потерявший часть своей чешуи понимает что силой вас не взять и поэтому мгновенно разворачивается в разные стороны, если он был клубком то теперь занимает еще больше места.*",130271,null],[160067,"2026-08-14T18:53:23",42,"// 10 урона. Забываю прибавлять 2",160057,null],[160071,"2026-08-14T18:53:55",9,"//Спас ловкости сл 15 от вас, ливбо вас откинет на 10 футов и вы упадёте ничком",130271,null],[160075,"2026-08-14T18:54:15",9,"/roll 3d4 дробящего но ток кто провалил",130271,null],[160078,"2026-08-14T18:54:24",17,"/ Мой урон посчитали же. Я до Жака сходил получается. После его нанесения ран от меня прилетело 23 рубящего",130271,null],[160079,"2026-08-14T18:54:46",42,"/roll d20 +2 спас",160071,null],[160088,"2026-08-14T18:55:18",17,"/r +4",130271,null],[160090,"2026-08-14T18:55:20",9,"//Клон проходит спасы кстати, или ему просто урон прилетает? Я не шарю",160078,null],[160091,"2026-08-14T18:55:36",17,"/ Урон по области гарантированный его сносит",160090,null],[160093,"2026-08-14T18:55:45",17,"/ Если страх и тд ему похуй он как коробка",130271,null],[160094,"2026-08-14T18:55:49",17,"/ не существо",130271,null],[160097,"2026-08-14T18:56:15",9,"*Клон разбился на осколки и змей снова скрутившись бьёт одного из вас.*",130271,null],[160099,"2026-08-14T18:56:27",9,"/roll +d20+5",130271,null],[160102,"2026-08-14T18:56:38",9,"/roll 1d2 одиничка жака",130271,null],[160107,"2026-08-14T18:57:38",42,"// ого",130271,null],[160109,"2026-08-14T18:57:49",9,"/roll 2d8+3 колющий",130271,null],[160111,"2026-08-14T18:58:04",9,"/roll 2d10 ядом и спас тело сл 12",130271,null],[160116,"2026-08-14T18:58:58",42,"/roll d20 +3",130271,null],[160121,"2026-08-14T18:59:48",42,"// может поиздеваться над змеем? У меня есть закл прикольный. Отражение",130271,null],[160122,"2026-08-14T18:59:57",9,"*Большая змеиная пасть цапнула Люца за плечо, яд, сладкий словно марево морочит голову, хочется уснуть, изображение перед глазами плывет как под шафе или сказочного дыма, но ты, устоял.*",130271,null],[160124,"2026-08-14T19:00:11",9,"//Ход",130271,null],[160125,"2026-08-14T19:00:12",17,"Фауст видит как змей вгрызается в его товарища и понимает что нужно заканчивать как можно быстрее.\n\n он напрягает все свои силы износа течёт маленькая струйка крови ещё один клон из воздуха появляется тонкий слоёный лёд \n\n Фауст поднимает свой клинок и синхронно вместе с клоном наносит атаку спереди сзади поэтому змею пытаясь расковырять его уязвимые места",130271,null],[160126,"2026-08-14T19:00:15",17,"/r +d20+6 q1 +d20+6 q2\n\nd8+6 q1\n\nd8+6 q2",130271,null],[160130,"2026-08-14T19:00:32",17,"/r d8",130271,null],[160140,"2026-08-14T19:02:51",9,"*Клинки прошивают плоть в местах где сбита чешуя. Пасть отпускает Люца и змей поворачивается к обидчику, Фаусту... Глаза его словно горят синевой а зрачки напоминают щели тоньше иглы.*",130271,null],[160141,"2026-08-14T19:02:59",9,"//Спас мудрости 17",130271,null],[160142,"2026-08-14T19:02:59",42,"// мы же играем в днд так по приколу или с биологической точки зрения?",130271,null],[160144,"2026-08-14T19:03:05",17,"/r +2",130271,null],[160147,"2026-08-14T19:04:04",9,"*Хотелось застыть на месте и не двигаться, тело и разум едва едва справилось с ошеломлением и воздействия на разум. Ты уловил нотки страха телепатией, перед вами разумный, и он боится вас.*",160145,null],[160148,"2026-08-14T19:04:07",42,"// если имеет смысл биологии тут, можно из одним заговором распугать. Мелкотню точно",160142,null],[160151,"2026-08-14T19:05:15",9,"/roll 4d3 на одиничке жак, три эт клон кого атакуют змии",130271,null],[160155,"2026-08-14T19:05:45",42,"// может я не буду больше еденичкой?)",130271,null],[160157,"2026-08-14T19:05:49",9,"/roll 1d20+5 жаку\n/roll 1d20+5 жаку\n/roll 1d20+5 фаусту\n/roll 1d20+5 клон",130271,null],[160160,"2026-08-14T19:06:19",9,"/roll 2d4+1 ядом одиничка эт колющий и спас тела десять",130271,null],[160162,"2026-08-14T19:06:46",9,"//Если пройдёшь спас то всего 2 урона ядом и 1 колющий",160161,null],[160165,"2026-08-14T19:07:04",9,"/roll 1d4 новые змии прилетают на шум боя",130271,null],[160167,"2026-08-14T19:07:35",42,"/roll 1d20 +3",130271,null],[160171,"2026-08-14T19:08:06",42,"// сколько люца не травите. Он проходит)",130271,null],[160173,"2026-08-14T19:08:17",9,"//Ходи",130271,null],[160174,"2026-08-14T19:08:20",42,"// мужик же в висперали прожил и на наркоте торчал",130271,null],[160178,"2026-08-14T19:08:53",9,"//Хотя, щас",130271,null],[160183,"2026-08-14T19:09:16",9,"// Как то реагируешь на это или делаешь что-то?",160147,null],[160186,"2026-08-14T19:09:42",42,"Люц взмахивает катаной и вспышка. Теперь почему то видно 4 Люца вместо одного\n\n// закл отражение",130271,null],[160189,"2026-08-14T19:10:18",42,"// бонусной ебашу заговором зелëнный клинок по мелкоте",130271,null],[160191,"2026-08-14T19:10:30",42,"/roll 1d20 +6",130271,null],[160193,"2026-08-14T19:10:36",9,"//А как ты бонусным атакуешь? Метамагия?",130271,null],[160236,"2026-08-14T19:19:46",42,"// этот заговор просит бонуски",160193,null],[160242,"2026-08-14T19:20:31",42,"// не использовал потому что уже узнал что большая змея впитывает магию. А огненный смерч мне не нужен",130271,null],[160254,"2026-08-14T19:22:44",9,"//Покажи мне где клинок зеленого пламени на бонусном)",130271,null],[160259,"2026-08-14T19:23:02",9,"//Там ток волшебные камни и ещё чет бонуской из заговоров",130271,null],[160260,"2026-08-14T19:23:04",42,"// отбой, действие. Это я с ммт взял вариант заговора",130271,null],[160262,"2026-08-14T19:23:20",42,"// в днд Су да. Действик",130271,null],[160843,"2026-08-15T00:58:03",9,"//Ну раз фауст не реагирует, наверное мой ход)",130271,null],[160846,"2026-08-15T00:58:46",9,"/roll 1d20+5 в фауста укус багрового змея",130271,null],[160848,"2026-08-15T00:59:28",9,"// @dunchev нет ничего чтобы исправить положение? Там приема какого нить, реакции, хз",160847,null],[160849,"2026-08-15T00:59:50",9,"//Криты падлы",130271,null],[160864,"2026-08-15T01:13:35",9,"//Или удалить пока он их не видел...",130271,null],[160885,"2026-08-15T06:43:45",17,"/ Нету. Давай урон",130271,null],[160886,"2026-08-15T07:50:01",9,"//Вопрос, кубы яда тоже удваиваются в таком случае?",160885,null],[160888,"2026-08-15T08:31:52",9,"/roll 4d8+3 колющий",160885,null],[160890,"2026-08-15T08:33:49",9,"/roll 2d10 ядом, и спас тела сл двенадцать",130271,null],[160892,"2026-08-15T08:47:52",17,"/ Да",160886,null],[160893,"2026-08-15T08:48:37",42,"// через час или меньше я тут",130271,null],[160894,"2026-08-15T08:48:46",42,"// мед осмотр у меня",130271,null],[160895,"2026-08-15T08:49:19",17,"/ Ок. Я всё Жака. У меня был 31 хит",130271,null],[160896,"2026-08-15T08:49:23",9,"/roll 2d10 еще яд",130271,null],[160898,"2026-08-15T08:49:36",9,"//Спас тела ебани, порежь урон от яда пж",160895,null],[160899,"2026-08-15T08:49:48",17,"/r +5 Да вот Спасик тела",130271,null],[160902,"2026-08-15T08:50:07",17,"/ Все ещё больше 31",130271,null],[160903,"2026-08-15T08:50:17",9,"//Хотя бе не смерть, ысего 12 ядом и 28 колющего",130271,null],[160904,"2026-08-15T08:50:27",9,"//В сумме не 62 и збс",160902,null],[160905,"2026-08-15T08:50:36",42,"// апхахахха",130271,null],[160907,"2026-08-15T08:51:10",42,"// у меня ещë ячейка 2 уровня. Под отражением 3 клона ещë",130271,null],[160912,"2026-08-15T08:53:54",42,"// Hard увы. Но без карты тяжко. Я хз как использовать волну грома или другие ауе скиллы",130271,null],[160913,"2026-08-15T08:53:59",9,"//Да, я расчитывал что вас будет мин 4, вы ещё неплохо вдвоём справляетесь. А так, как и говорил заготовки и сложность не ищменится не зависимо от того сколько вас.",130271,null],[160915,"2026-08-15T08:54:45",9,"//Просто скажи что встал так чтобы не задело фауста, чтобы ты понимал сам багровый змей занимает 10×10 футов",160912,null],[160916,"2026-08-15T08:55:19",9,"//Но ты точно хочешь волну грома?)))",130271,null],[160918,"2026-08-15T08:56:01",17,"Укус ядовитой алой змеи внезапный и резкий. Защита Фауста пропущена, яд бежит по крови и ждёт изнутри. \n\nЛедяной клон разбирается и его осколки падают на пол где исчезают \n\nВ глазах Фауста темнеет и сознание покидает его \n\n\"Недооценил противника, чеееерт\"",130271,null],[160920,"2026-08-15T09:09:29",9,"//У фауста пропущен один бросок от смерти",130271,null],[160921,"2026-08-15T09:10:31",9,"/roll 1d20+5\n/roll 1d20+5\n/roll 1d20+5\n/roll 1d20+5\n/roll 1d20+5\n/roll 1d20+5\n/roll 1d20+5\n/roll 1d20+5",130271,null],[160924,"2026-08-15T09:11:45",17,"/r Спас от смерти",130271,null],[160926,"2026-08-15T09:12:20",9,"*Летающие змии пытаются атаковать стоящего на ногах Люца летая вокруг него, шипя и норовя цапнуть. Один из них ударился головой о броню и упал в возу оглушенный.*",160922,null],[160928,"2026-08-15T09:12:46",9,"//Не защитанно, бросишь когда Люц тебя полечит или проверит, это метагейм твоего состояния, не люблю такое.",160925,null],[160930,"2026-08-15T09:13:21",9,"/roll 1d4 налетают новые змии на шум битвы",130271,null],[160932,"2026-08-15T09:13:47",9,"// @Jak_Zak хоть кто то попал? Если нет — твой ход",160922,null],[160934,"2026-08-15T09:16:37",42,"// я тут",130271,null],[160935,"2026-08-15T09:17:17",42,"// 18 попал. Но он кусает мой клон. Поэтому по мне урона нету",160922,null],[160937,"2026-08-15T09:17:46",9,"//Там вроде бы надо бросить кого он укусил если щакл отражения",160935,null],[160938,"2026-08-15T09:18:01",42,"// да да да. Кидай",130271,null],[160942,"2026-08-15T09:19:04",9,"//Кд копии равен 10+твой мод ловкости)",130271,null],[160943,"2026-08-15T09:19:14",42,"// увидел. 12 кд",130271,null],[160945,"2026-08-15T09:20:35",42,"// 13 17 18 по копиям. Щас буду кидать кубик. Остальные не попали",130271,null],[160948,"2026-08-15T09:21:03",9,"/roll 4d20 на кого нападали змеи на первом кубе змей который выбил восемнадцать",130271,null],[160952,"2026-08-15T09:21:28",9,"//У тебя ток одна копия, твой ход",160945,null],[160953,"2026-08-15T09:21:38",42,"// бла бла бла. Удали",130271,null],[160955,"2026-08-15T09:21:49",42,"// у меня сообщения не прогрузились",130271,null],[160956,"2026-08-15T09:23:22",42,"// я могу как-то всех этих мелких падл ëбнуть Громовой волной?",130271,null],[160957,"2026-08-15T09:23:31",42,"// карты нету. Поэтому отвечай",130271,null],[160959,"2026-08-15T09:24:30",9,"//Можешь слегка обойти багрового змея чтобы Фауста не задело и ебануть, они хаотично летают но более менее рядом, я просто кину 3д4 сколько ты заденешь из них",130271,null],[160960,"2026-08-15T09:25:11",42,"// и впустишь мою последнюю ячейку в молоко?",160959,null],[160961,"2026-08-15T09:25:28",42,"// щас буду колю косплеить",130271,null],[160962,"2026-08-15T09:25:44",42,"// Джимми где карта. Нам нужна карта",130271,null],[160964,"2026-08-15T09:26:33",42,"// может я брошу? Твои броски очень хреновы. Плюс это последствия моих действий.",130271,null],[160965,"2026-08-15T09:28:37",17,"/ Забей на карту долбани волну и кидь 3д4 нормально будет",130271,null],[160966,"2026-08-15T09:28:41",9,"//Красный это змей, синий — фауст, черный — жук \"Люц\". Змии постоянно хаотично летают вокруг, рояться, так что количество которых ты заденешь за раз = 3д4 шт из 9",130271,null],[160967,"2026-08-15T09:31:28",42,"// ок",130271,null],[160968,"2026-08-15T09:32:07",9,"//Тебе даже отходить не надо, фауста не заденет выходит, там куб с ребром 15 фт с тобой в центре",130271,null],[160969,"2026-08-15T09:32:27",42,"/roll 3d4 это сколько задену\n/roll 3d8 урон звуком",130271,null],[160971,"2026-08-15T09:33:31",42,"// прикол в другом. Хард хотел кинуть. Я ему такие Кубы не доверяю)",160965,null],[160972,"2026-08-15T09:35:14",9,"*Всех змиев откидывает от тебя оглушённых и мертвых, как дождь в разные стороны.*",160970,null],[160973,"2026-08-15T09:35:41",42,"// в следующий ход я использую наложение рук на Фауста",130271,null],[160974,"2026-08-15T09:35:43",9,"/roll 1d20+2 телосложение багровой змеи",130271,null],[160976,"2026-08-15T09:36:26",9,"//Ну, точно прошла, так что ток половина урона ей",130271,null],[160977,"2026-08-15T09:36:45",9,"//Щас, минутку, и тут",130271,null],[160978,"2026-08-15T09:37:27",42,"// 9+2 еë душа страдает)",160976,null],[160979,"2026-08-15T09:39:17",9,"*Змей всё ещё живой, чешуя местами облупилась, тяжело дышит, но все еще готов сражаться. Зверь загнанный в угол будет делать это до последнего.*",130271,null],[160980,"2026-08-15T09:39:30",9,"/roll 1d20+5 цепнет, надеюсь нет",130271,null],[160982,"2026-08-15T09:39:47",42,"// надеюсь нет... Ебать как",160981,null],[160983,"2026-08-15T09:40:04",9,"//У тебя тоженичо нет?",130271,null],[160984,"2026-08-15T09:40:16",42,"// одно отражение",130271,null],[160985,"2026-08-15T09:40:33",42,"/roll d20 надеюсь больше одиннадцати",130271,null],[160987,"2026-08-15T09:40:44",9,"//Кидай, если 10 и больше на д20 то отражение",130271,null],[160988,"2026-08-15T09:40:47",42,"// по клону Крит!",160986,null],[160989,"2026-08-15T09:41:32",9,"*Змей в рывке схватил иллюзию и та развеялась у него в зубах.*",130271,null],[160990,"2026-08-15T09:42:01",9,"/roll 3d4 на звук сражения и громовой волны прилетают новые змии",130271,null],[160992,"2026-08-15T09:42:23",9,"//Твой ход жак",130271,null],[160993,"2026-08-15T09:42:55",42,"// на уроках биологии нам говорили что змеи боятся громких звуков, ну ладно)",160990,null],[160994,"2026-08-15T09:43:04",42,"// Фауст без сознания?",160992,null],[160995,"2026-08-15T09:43:10",9,"//У фауста 2 пропущенных спаса пока, его состояние не известно",130271,null],[160996,"2026-08-15T09:43:27",9,"//Тоесть он их не кидал, ты не знаешь что с ним",160995,null],[160997,"2026-08-15T09:44:12",9,"//Это голодные, на болоте все выжрано и тишина, звук это потенциальная добыча)",160993,null],[160998,"2026-08-15T09:44:55",42,"//уууууххх. Не доебаться, не доебаться)",160997,null],[160999,"2026-08-15T09:47:29",42,"// ок. Ждëм Колю. Если жив дальше ебашим, не. Хилим как паладин",160995,null],[161000,"2026-08-15T09:48:38",9,"//Он их кидать не будет, пока ты не вылечишь его или не проверишь хотя бы подойдя и бонусное потратив на осмотр. Я спецом не даю кидать чтобы сохранять интригу)",160999,null],[161001,"2026-08-15T09:49:13",42,"// ок. Кидаю медицину бонусным",130271,null],[161002,"2026-08-15T09:49:24",42,"/roll d20 +4",130271,null],[161004,"2026-08-15T09:50:28",9,"// @dunchev а теперь можешь кинуть лва броска пропущенных,",161003,null],[161005,"2026-08-15T09:51:21",9,"//Теперь карта вот так выходит, ты подошел я так понял",130271,null],[161014,"2026-08-15T10:15:43",17,"/r 2d20",161004,null],[161016,"2026-08-15T10:15:54",17,"/ Присмерти",130271,null],[161017,"2026-08-15T10:16:28",17,"/ Крит у этой змеи это стандарт())",130271,null],[161018,"2026-08-15T10:16:56",42,"Рука люца наполняется целебной энергией и хилю Фауста на 3 хп",130271,null],[161019,"2026-08-15T10:18:00",42,"// а теперь ход",130271,null],[161020,"2026-08-15T10:18:00",17,"Резко втягивая воздух через ноздри сознание возвращается к эладрину.. он встаёт опираясь на клинок и мрачнг кивает Люцу\n\n\"Думал мне конец. Спасибо\"",130271,null],[161021,"2026-08-15T10:18:48",42,"— конец только этой твари! А мы словно тараканы будем биться даже без головы",161020,null],[161022,"2026-08-15T10:21:49",9,"*Змей видит что ты пытаешься вылечить союзника, он атакует лежачего Фауста.*",130271,null],[161023,"2026-08-15T10:22:04",9,"/roll +d20+5 по фаусту",130271,null],[161025,"2026-08-15T10:22:50",9,"*Тыкается носом мимо в пол намочив багровую морду в воде.*\n\n//Ход",161024,null],[161026,"2026-08-15T10:23:08",42,"// таракан слишком страшен чтобы ранить того кого он лечит",130271,null],[161027,"2026-08-15T10:25:58",9,"//Мудрость у змея велика, он пытается в тактику)",161026,null],[161030,"2026-08-15T10:29:23",42,"// в тактику не выходит. Только подсосышами срëт",161027,null],[161032,"2026-08-15T10:30:28",17,"Фауст собирает силы и бьёт катаной по твари, а клона создаёт позади себя",130271,null],[161033,"2026-08-15T10:30:48",17,"/r +d20+6 Ну-ка вжух",130271,null],[161035,"2026-08-15T10:31:04",17,"/r d8+6 Рубящий",130271,null],[161038,"2026-08-15T10:31:38",9,"//Описывай как добил тварь)",161036,null],[161040,"2026-08-15T10:32:38",9,"*Змей поднимает голову, готовый в любой момент бросится на одного из вас, согнулся в пружину.*",130271,null],[161042,"2026-08-15T10:34:14",17,"Когда змей понёсся открытой пастью на Фауста тот выставил резко клинок поперек змеиной пасти и остановил его, не давая пасти закрыться.\n\n\nДёрнув в сторону змей качнулся в Люцу\n\n\"Добей его!\"",130271,null],[161043,"2026-08-15T10:34:20",17,"/ Люц пиши добивание",130271,null],[161044,"2026-08-15T10:37:00",42,"— ДА! \n\nУслышав команду товарища, Люц стоял на месте и как змей качнулся в его сторону Люц всем весом тела взмахия лезвием сверху вниз прорубил голову твари",130271,null],[161045,"2026-08-15T10:38:29",9,"*Победа, туша огромного змея все ещё корчится в коныульсиях на полу, но он мёртв, однозначно конец.*",130271,null],[161046,"2026-08-15T10:39:10",9,"/roll 9d3 кого атакуют мелкие змии еденица Люц, два фауст и тд",130271,null],[161048,"2026-08-15T10:39:36",42,"// ну да ну да...",130271,null],[161049,"2026-08-15T10:39:45",9,"/roll 1d20+5\n/roll 1d20+5\n/roll 1d20+5\n/roll 1d20+5\n/roll 1d20+5 по Люцу",130271,null],[161051,"2026-08-15T10:40:35",42,"// 2 Крита по мне. Ну ладно, теперь у меня есть временные хп за убийство большой змеи",130271,null],[161052,"2026-08-15T10:40:47",9,"/roll 2d4\n/roll 4d4\n/roll 4d4\n/roll 2d4 ядом, четыре спаса тела от тебя",130271,null],[161054,"2026-08-15T10:41:03",9,"//И 4 колющего до кучи",130271,null],[161055,"2026-08-15T10:41:21",9,"/roll 1d20+5\n/roll 1d20+5 по клону",130271,null],[161057,"2026-08-15T10:41:34",9,"/roll 1d20+5\n/roll 1d20+5 по фаусту",130271,null],[161059,"2026-08-15T10:41:42",42,"/roll d20 +3 \n/roll d20 +3\n/roll d20 +3\n/roll d20 +3",130271,null],[161061,"2026-08-15T10:42:10",42,"// Люца не отравить)",161060,null],[161062,"2026-08-15T10:42:22",9,"/roll 2d4 по фаусту и одиничка колющий",130271,null],[161064,"2026-08-15T10:42:30",9,"//Снова в о",130271,null],[161065,"2026-08-15T10:43:03",9,"// 8 урона ядом и 4 колющего",161060,null],[161067,"2026-08-15T10:44:07",42,"// а не. Не",130271,null],[161068,"2026-08-15T10:44:12",42,"// я того упаль",130271,null],[161069,"2026-08-15T10:44:33",42,"// ровно сука",130271,null],[161071,"2026-08-15T10:45:03",17,"/ Ну.. жаль конечно",130271,null],[161072,"2026-08-15T10:45:15",42,"// а стоп ебать. Тогда я живее всех живых.",161065,null],[161073,"2026-08-15T10:45:26",17,"/ Я еблан едси что забыл похилится",130271,null],[161074,"2026-08-15T10:45:33",17,"/ Воинской абилкой",130271,null],[161075,"2026-08-15T10:45:59",17,"/ Провоцированнуб кстате по 1 змею могу. Когда они пролетают мимо клона",130271,null],[161077,"2026-08-15T10:46:07",17,"/r +6",130271,null],[161080,"2026-08-15T10:46:36",9,"//Кто кого, обьясняйте",130271,null],[161082,"2026-08-15T10:47:23",9,"//Так, обьясняйте",130271,null],[161083,"2026-08-15T10:47:29",9,"//Вы стоите и почему",130271,null],[161084,"2026-08-15T10:47:40",9,"//Опишите это круто",130271,null],[161085,"2026-08-15T10:49:53",9,"//Я понимаю что вы проебали абилку и тд, но будем считать что нет. Мне нужно описание или хоть что-то",130271,null],[161086,"2026-08-15T10:50:21",9,"//Почему я долден помнить ваше хп и навыки",130271,null],[161087,"2026-08-15T10:51:50",42,"// ну вот моя причина почему жив. Покровитель кое что сказал",130271,null],[161091,"2026-08-15T10:59:57",9,"*Тело багрового змея бьется в конвульсиях. Фаст (хуй знает что с ним, пусть опишет, но в след раз пусть помнит свои способки).*\n\n*Небольшая стая змиев летает вокруг вас, прилетевшая на шум, готовая откусить от вас кусочек.*",130271,null],[161092,"2026-08-15T11:00:04",9,"//Ходи жака",130271,null],[161100,"2026-08-15T11:04:29",42,"Катана люца наполняется огнëм и бьëт по одной змеюке, после огонëк из попавшей змеи рекошетит в другую близжайшую змею",130271,null],[161101,"2026-08-15T11:04:43",42,"/roll 1d20 +6 +1",130271,null],[161103,"2026-08-15T11:04:58",17,"Фауст видя как змеи летят на него закрывает глаза смирившись\n\nТогда ледяной клон действует сам. Ледяными когтями он разрывает пару змеев и движется к Фаусту сливаясь с ним\n\nХолодный рассудок возвращается и Фауст открывает глаза\n\nПоднимает меч как может отбивается",130271,null],[161104,"2026-08-15T11:05:06",17,"/r d10+3 Хилюсь",130271,null],[161106,"2026-08-15T11:06:02",9,"*Огромный змей, точнее его тело бьющейся в конвульсиях на полу сбивает тебя с ног и ты падаешь ничком. Не надо было стоять рядом с этой штукой пока не починет полностью.*",161102,null],[161111,"2026-08-15T11:07:21",9,"//Ходи, ты после жаки, хотя у него скорость осталась, модет встать просто",161104,null],[161117,"2026-08-15T11:10:57",17,"\"Надо валить!\"",130271,null],[161118,"2026-08-15T11:11:46",17,"Фауст взрывается снегом рядом совершая фейский шаг. Устрашающий змей вокруг",130271,null],[161119,"2026-08-15T11:11:58",17,"/ Спас мудрости СЛ 12",130271,null],[161120,"2026-08-15T11:12:03",17,"/ или страх",130271,null],[161121,"2026-08-15T11:12:25",17,"/ Это за бонуску",130271,null],[161122,"2026-08-15T11:13:38",9,"*Есть несколько проходов по бокам в другие комнаты или можно скрыться через дыру наверх откуда упал змей.*",161118,null],[161123,"2026-08-15T11:14:13",17,"Фауст отталкивается от туши змея и хватается за дыру чтоб вылезти",130271,null],[161124,"2026-08-15T11:14:24",17,"/ отход действие",130271,null],[161125,"2026-08-15T11:14:31",9,"/roll 1d20\n/roll 1d20\n/roll 1d20\n/roll 1d20\n/roll 1d20\n/roll 1d20\n/roll 1d20\n/roll 1d20 мцдрость тварей",130271,null],[161127,"2026-08-15T11:14:39",17,"/ Испуганных много",130271,null],[161128,"2026-08-15T11:15:14",9,"*Почти все разлетаются и убегают в разные стороны, безбашенных осталось всего несколько, а именно три.*",130271,null],[161129,"2026-08-15T11:17:00",9,"*Ты на верху и тут гнездо из веток и костей этажом выше. Змей настолько умный чтобы свить себе гнездо тут. Снизу все еще люц и твой клон.*",161123,null],[161130,"2026-08-15T11:19:43",42,"// Люц готов добить тройку",130271,null],[161131,"2026-08-15T11:25:00",9,"/roll 1d20+5\n/roll 1d20+5\n/roll 1d20+5 по люцу выходит",130271,null],[161133,"2026-08-15T11:25:24",42,"// одно попадание",130271,null],[161135,"2026-08-15T11:27:03",9,"/roll 2d4 и спас тела тебе",130271,null],[161137,"2026-08-15T11:27:38",42,"/roll 1d20 +3",130271,null],[161139,"2026-08-15T11:27:58",42,"// люца не отравить)",130271,null],[161143,"2026-08-15T11:35:17",9,"//1 урона ядом и 1 колющий, твой ход",161138,null],[161164,"2026-08-15T12:00:38",42,"Люцу уже это не нравится, его эти змеи начали взбешивать.. Он встал между ними и ебашит вспышку мечей",130271,null],[161170,"2026-08-15T12:05:51",9,"*Все три изрезываются на куски. Снаружи дуткий гул шуршащих крылышек, вся округа снаружи скорее всего в этих мелких шуршащих змиях.*\n\n//Конец инициативы, ваши действия",161164,null],[161179,"2026-08-15T12:09:46",17,"Глазами Фауст ищет что нибудь полезное чтобы сбежать или залечить раны в гнезде змея",161129,null],[161180,"2026-08-15T12:09:58",17,"/r +4 Хладнокровно осматриваю",130271,null],[161182,"2026-08-15T12:10:10",17,"\"Люц ты где там! Бежим!\"",130271,null],[161189,"2026-08-15T12:14:01",9,"*Ты видишь кожу змея в гнезде. Багровые чешуйки переливаются под лучами солнца пробивающейся сквозь трещины в потолке. Похоже он сбросил её когда динял, а ещё вся эта комната исписанна рунами, хаотичными, бессмысленными. Как немного разбирающийся в магии ты примечаешь несколько что повторяются не раз в сочитании \"Дракон разума\".*",161181,null],[161190,"2026-08-15T12:14:44",17,"Фауст подхватит пару чешуек с собой",130271,null],[161191,"2026-08-15T12:14:50",9,"*Это место кажется относительно безопасным чтобы пересидеть, лишь несколько дыр ведут на низ и пару щелей в крыше.*",130271,null],[161193,"2026-08-15T12:16:06",17,"\"Люц забирайся сюда наверх. Тут мы сможем забаррикадировать я от змеев и переждать.\"",130271,null],[161194,"2026-08-15T12:16:15",9,"*Ты видишь как в окнах через которые ты попал в зал мелькают змии, они вскоре будут тут.*",161164,null],[161195,"2026-08-15T12:16:52",17,"Фауст в поисках чего то чтобы закрыть щели и окна.",130271,null],[161196,"2026-08-15T12:16:56",17,"/r +4",130271,null],[161198,"2026-08-15T12:17:04",17,"/ Блять кубы хотят нашей смерти",130271,null],[161199,"2026-08-15T12:17:12",17,"/ Ну ладно терпим",130271,null],[161200,"2026-08-15T12:17:51",17,"Не найдя ничего Фауст создаёт клона его ледяным силуэтом закрывая окно. \n\nКровь из обеих ноздрей хлынула от этого усилия а сам клон создался из кровавого льда",130271,null],[161201,"2026-08-15T12:18:03",17,"\"Люц, ответь! Ты жив?\"",130271,null],[161202,"2026-08-15T12:18:25",17,"Поиском мыслей пытаюсь нащупать мысли Люца чтоб понять он жив или нет",130271,null],[161203,"2026-08-15T12:20:49",42,"— Жив! Вот только я без понятия что делать. Их наверное тут тысячи",161201,null],[161211,"2026-08-15T12:24:39",42,"// так, Фауст сверху?",161170,null],[161217,"2026-08-15T12:25:33",42,"— Дружище ты где?",130271,null],[161222,"2026-08-15T12:26:41",42,"// разрешишь использовать абилку по не назначению? Хочу превратить оружие договора в шест, длиинююючий",130271,null],[161228,"2026-08-15T12:28:06",17,"\"Наверх посмотри там щель, тут гнездо змея алого\"",130271,null],[161238,"2026-08-15T12:29:53",42,"// если хард даст добро с помощью прыжка на шесте добраться до тебя тогда и начну действовать в зависимости от решения Харда",130271,null],[161240,"2026-08-15T12:30:55",9,"//Го, акробатика если шестом, сл 12",161238,null],[161267,"2026-08-15T12:41:27",17,"Фауст свешивает руки вниз чтобы ухватить Люца",130271,null],[161268,"2026-08-15T12:41:30",17,"/ помощь",130271,null],[161273,"2026-08-15T12:43:10",42,"— Фауст! Готовься схватить меня если долечу! \n\nкатана люца сузилась и превратилась в длинючий посох, Люц набирал разбег 20 футов и после оперев шест он делает прыжок (если выйдет) и в воздухе превращает его в обычную мелкую штуку (кинжал) чтобы с собою утащить",130271,null],[161276,"2026-08-15T12:43:31",42,"/roll +d20 +4 акробатика",130271,null],[161285,"2026-08-15T12:47:35",9,"*Вы оба оказались на верху. Снаружи шум, и внизу тоже нарастает уже знакомое трепыхание крылышек. Люц громовой волной раздраконил всю округу, только пересидеть пока всё успокоится.*",130271,null],[161286,"2026-08-15T12:49:53",9,"// +1000 каждому опыт за багрового змея разума и мелочь.",130271,null],[161288,"2026-08-15T12:49:57",9,"//Я думал вы сдохнете еще когда только вошли внутрь и ни разу не посмотрели вверх чтобы разоблачить засаду даже когда крошки камней упали Фаусту на плечо",130271,null],[161291,"2026-08-15T12:52:02",17,"/ Ну у меня Крит провалы или низкие значения. Я отыгрыал)",130271,null],[161299,"2026-08-15T12:54:32",9,"// ещё +100 за то что зачистили это место, чуть не забыл",161286,null],[161307,"2026-08-15T12:58:15",42,"// ещё 250 опыта за крутые мувы?",161299,null],[161308,"2026-08-15T12:58:29",42,"// дай дай дай лвл ап",130271,null],[161309,"2026-08-15T12:59:07",42,"// я не знаю что в колдуна на 4, но я хочу",130271,null],[161312,"2026-08-15T13:00:13",9,"*Наверху ты видишь гнездо из веток и костей, тут Фауст и сбоку лежит целый пласт багровой кожи, тот змей недавно линял и не успел её сожрать перед вашим приходом, возможно он должен был быть ещё крепче. Солнечные лучи пускают красные зайчики от чешуи, та переливается как драгоценность.*\n\n*Все стены этой комнаты исписанны драконьими и магическими рунами, в безумии или разуме?*",161276,null],[161313,"2026-08-15T13:00:34",9,"// я дал что мол по максимуму, так что нет)",161308,null],[161315,"2026-08-15T13:05:59",42,"// типо по приколу мой перс шарит за язык безумия и злых нот. Сойдëт?",161312,null],[161316,"2026-08-15T13:06:13",42,"// окееей",161313,null],[161321,"2026-08-15T13:07:10",42,"Люц видя чешуйки собирает их себе в рюкзак\n\n— Фауст, собирай тоже. За них точно можно хорошо выручить или сделать хороший доспех на заказ",130271,null],[161340,"2026-08-15T13:15:31",9,"*Сброшенная кожа большая, и в отличие от змея внизу — целая, жёсткая, крепкая.*\n\n// ps: вот вам материал для \"доспеха из змеиной чешуи\" хватит на один, делите как хотите",161321,null],[161347,"2026-08-15T13:21:52",42,"— Су е фа? Или продадим а деньги попалам? \n\nСмотрит Люц на чешую",161340,null],[161374,"2026-08-15T14:03:30",17,"\"Да. Змея тут сбросила шкуру.\"",161321,null],[161375,"2026-08-15T14:03:58",17,"\"Потом поделим. Щас главное не сдохнуть.\"\n\nФауст перевязывал себе раны бинтом",130271,null],[161376,"2026-08-15T14:04:24",17,"/ Это Люцу сделаем. Я не могу носить средний доспех",161340,null],[161377,"2026-08-15T14:04:31",17,"/ Песня клинка не позволяет",130271,null],[161390,"2026-08-15T14:09:11",42,"— Не сдохнем. Глаааавнооооее найти выход. Змеи обычно одним тунелем их гнëзд не отделываются\n\nЛюц высматривает всë гнездо в поисках другого выхода",161375,null],[161393,"2026-08-15T14:09:32",42,"/roll 1d20 +4 выживание",130271,null],[161657,"2026-08-15T15:54:03",9,"*Под потолком есть место где мог вылезть змей, но, это место более 50 футов по стене. Похоже владелец логова ввиду своего веса и размера пользовался только теми тремя дырами что вели в зал под вами.*",161394,null],[161658,"2026-08-15T15:55:18",17,"\"Чтож. Предлагаю укрепить тут входы и отдохнуть. Мне серьезно досталось, еле на нога стою\"",130271,null],[161711,"2026-08-15T16:21:03",42,"— Конечно дружище. Нам обоим нужно отдохнуть\n\nЛюц укрепляет входы и после ложится отдохнуть",130271,null],[161716,"2026-08-15T16:22:06",17,"\"Сила твоего покровителя пугающе огромна. И эта гитара, что стала косой. Впечатляет. Это он избрал тебя или ты сам выбрал его для себя?\"",130271,null],[162087,"2026-08-15T20:07:36",42,"— походу мы сами нашли друг друга. Когда я умирал он нашëл мою угасающую душу, он показал всë что прожил. Он был великим воином, но одинок. Роняя последние капли своей крови я нашëл его в обломках заброшенной усадьбы. Он отдал все силы чтобы оживить меня соеденим с жуком что пожирал меня. После он пропал пока не стал сильнее и не подписал с ним договор. Вот такая история о моëм покровителе и обо мне. А какова твоя история друг?",161716,null],[162094,"2026-08-15T20:08:41",17,"\"Ого. Так твой покровитель не этот самый жук? Как он выглядит ты знаешь?\"",130271,null],[162103,"2026-08-15T20:10:23",42,"— видел только образ его в доспехах. Он был воином, вряд ли какой-то маг. А жуком я стал потому что у меня вырвали кишки, сердце и другие внутренности и они у меня жучинные",130271,null],[162114,"2026-08-15T20:15:41",17,"\"Повезло тебе. Вероятно сильно повезло.\"",130271,null],[162135,"2026-08-15T20:39:43",42,"— так ладно. Я люблю себя. Но как насчëт тебя? Мне правда интересно от куда ты и от куда у тебя такие мощные техники?",162114,null],[162185,"2026-08-15T20:51:02",17,"\"Я из особого клана зимних эладринов. В клане всем мужчинам по наступлению совершеннолетия в 50 лет проводят обряд молчания. Зашивают рот серебряными нитями и ты вынужден молчать. Они прокляты древней архифеей и священны для клана. Если ты порежешь нити получить проклятье. Они все равно снова почти сразу прошьют губы но уже в других местах через невыносимую боль. И вот после этого я смог овладеть техникой ледяного клонирования. \n\nПонимаешь я как раз из тех кто пытался нарушить правила. Я резал эти нити снова и снова. Без надежды на результат. Это привело к изгнанию из клана. Сожжению моей матери. И моей клятве мести. Я вернусь и вырежу всех старейшин. \n\nСтарейшины как то сняли эти нити. Говорили про какой то ритуал свидетеля. Но меня изгнали почти сразу и, конечно, не рассказали ничего. Вот такая история\"",130271,null],[162535,"2026-08-16T02:02:01",17,"Фауст достал книгу заклинаний он встал и подошёл к стене сверяя написанное в книге с глифами на по стенам он пытался что то понять",130271,null],[162536,"2026-08-16T02:02:08",17,"/r +1 Магия",130271,null],[162538,"2026-08-16T02:02:36",17,"Заодно пробуя наложить свои заклинания",130271,null],[162539,"2026-08-16T02:02:41",17,"/ Псевдожизнь",130271,null],[162541,"2026-08-16T02:03:04",17,"/r d4+4",130271,null],[162543,"2026-08-16T02:03:31",9,"*Руны на стенах все ещё плохо угадывались. Что точно и часто встречалось — словосочитание \"дракон разума\".*",162537,null],[162544,"2026-08-16T02:04:25",17,"\"Дракон разума... Дракон разума... Что это значит? Сапфировый дракон?\"",130271,null],[162545,"2026-08-16T02:05:41",17,"Фауст попытался вспомнить что то о словосочетании \"Дракон разума\"",130271,null],[162546,"2026-08-16T02:05:54",17,"/r +1 История",130271,null],[162548,"2026-08-16T02:06:03",17,"Но ничего в голову не шло.",130271,null],[162549,"2026-08-16T02:06:36",17,"Тогда он попробовал переписать руны и глифы прямо в волшебную книгу как есть\n Буквально срисовать их себе.",130271,null],[162550,"2026-08-16T02:06:49",17,"/r +4 Ловкость рук",130271,null],[162552,"2026-08-16T02:06:56",17,"/ Пупупуппупупуру",130271,null],[162553,"2026-08-16T02:07:10",17,"Руки дрожали от усталости и вышло криво.",130271,null],[162554,"2026-08-16T02:08:21",17,"Тогда Фауст попробовал подойти по научному. Он попытался проанализировать взаимосвязь символов на стене между собой. Это слова?",130271,null],[162555,"2026-08-16T02:08:30",17,"/r +1 Анализ",130271,null],[162557,"2026-08-16T02:08:36",17,"/ Роооофл",130271,null],[162558,"2026-08-16T02:10:02",17,"Ничего толком не выходило и эладрин будто уже начал злиться под коркой льда. На последок он попытался осветить руны и глифы факелом проверяя нагрев, а потом заморозил воду из бурдюка и провел сосулькой",130271,null],[162559,"2026-08-16T02:10:10",17,"/r +1 Природа",130271,null],[162561,"2026-08-16T02:11:12",9,"// Карма за побеждённого змея мстит",130271,null],[162562,"2026-08-16T02:11:22",17,"Но и это не дало результата. Тогда Фауст скл р раскрыл рюкзак\n\nОттуда показался молодой грифон\n\n\"Привет дружок. Ты меня не понимаешь, конечно, но я за тобой присматрю\" \n\nОн достал вяленое мясо и скормил грмфончику",130271,null],[162563,"2026-08-16T02:11:31",17,"\"Как же мне тебя назвать...…?\"",130271,null],[162564,"2026-08-16T02:12:05",17,"\"Может Фрост? Нравится?\"",130271,null],[162565,"2026-08-16T02:12:13",17,"/r +2 Уход за животными",130271,null],[162567,"2026-08-16T02:12:58",17,"\"Хм.. может иначе...  Пока подумаю\"",130271,null],[162577,"2026-08-16T09:16:52",42,"// я тут",130271,null],[162578,"2026-08-16T09:17:51",42,"— Ого! А кто это у тебя такой красавец в рюкзаке?",130271,null],[162580,"2026-08-16T09:25:47",17,"\"Яйцо нашли в гнезде на задании. Его мамочку мы убили, чтоб не жрала путников на перевале. Ну а яйцо забрали. Я должен был его уже давно продать но что то все как то не получилось. Он возьми и вылупись. Жалко теперь. Вот кормлю. Имя не придумал, есть идеи?\"",130271,null],[162623,"2026-08-16T14:13:33",42,"— Тааак... Хмммм... Айз?",130271,null],[162624,"2026-08-16T14:44:47",17,"\"Хм... может или Айс, или Эйс Винтура, или Фрост. Ну да что то такое. Прожорливый смотри как мясо жрет. Его мамаша тоже хотела нас сожрать\"",130271,null],[162625,"2026-08-16T14:45:37",17,"\"У тебя есть какая нибудь глобальная цель? Такая, что после ее достижения можно и на покой? Вот как у меня с местью всем старейшинам клана например.\"",130271,null],[162632,"2026-08-16T15:08:43",42,"— Я бы хотел покончить с окультистами полностью. Чтобы не существовало культов которые извращают юнцов и их жизнь, я из-за них всю юность на наркоте торчал. Не хочу чтобы кто-то кроме меня попал бы под такую судьбу",130271,null],[162633,"2026-08-16T15:09:30",17,"\"Хорошая цель. Помогу тебе с радостью. Тоже культистов на дух не переношу\"",130271,null],[162634,"2026-08-16T15:09:53",17,"\"На стенах написано что то. Можешь помочь понять это?\"",130271,null],[162635,"2026-08-16T15:10:07",17,"/ Нужна помощь с распознанием у меня вчера рак кубов был",130271,null],[162636,"2026-08-16T15:12:29",9,"//Если он поможет можешь кинуть заново еще раз и с преимуществом, поновой",130271,null],[162642,"2026-08-16T15:24:10",42,"— Да конечно. Давай\n\nЛюц помогает Фаусту распознать записи",162634,null],[162645,"2026-08-16T15:31:46",17,"/r +d20+1 Попытка расшифровать глифы",130271,null],[162647,"2026-08-16T15:32:48",17,"/ Бля это злой рок",130271,null],[162648,"2026-08-16T15:32:58",17,"/ Судьба говорит не надо ничего тут понимать",130271,null],[162654,"2026-08-16T15:38:44",17,"\"Нет... Ничего не понимаю... Ладно может позже. Я зарисовал эти символы. Покажу в городе кому нибудь начитанному\"",130271,null],[162655,"2026-08-16T15:39:00",17,"\"Ложись отдыхать первый я посторожу\"",130271,null],[162656,"2026-08-16T15:39:04",17,"/ Долгий отдых",130271,null],[162658,"2026-08-16T15:48:34",9,"// Звпиши себе и не забудь:\n\n\"Записи о драконе разума из логова багрового змея\"",162654,null],[162660,"2026-08-16T15:49:51",9,"//Если долгий то спишите по рациону и я сейчас опишу что куда",130271,null],[162809,"2026-08-16T22:04:08",42,"— Ну в следующий раз разберëм что и как. А пока давай я отдохну. Разбудишь как моя очередь будет быть на стрëме\n\nЛюц сразу же лëг спать после такого тяжëлого дня, рубит и клонит в сон",162654,null],[162812,"2026-08-16T22:08:18",17,"Фауст и его ледяной клон на страже",130271,null],[162814,"2026-08-16T22:18:39",42,"// если клон профукал гусю.. Я уже начинаю сомневаться в моей безопасности)",162812,null],[162819,"2026-08-16T22:32:32",17,"/ Это был демонический гусь как пить дать",130271,null],[162826,"2026-08-16T22:36:03",42,"// запомни. Он уже обидку на нас словил. Он стопудово финальный босс квеста",130271,null],[162835,"2026-08-16T22:50:40",42,"// Hard ты же говорил что сложность для 4 персонажей подбирал. Так пускай и опыт мы будем получать за 4 перса. Думаю баланс + приятно к Кнуту получать и пряник",130271,null],[162839,"2026-08-16T22:55:14",9,"//Вы бы и получили по 250 на четверых, или даж по 200",130271,null],[162843,"2026-08-16T22:58:24",17,"/ Завтра играем? У мен будет время с 8 до 17",162835,null],[162844,"2026-08-16T22:58:58",9,"//Постараюсь вести активно, щас настроения в ноч вести нет, развн играть",130271,null],[162845,"2026-08-16T22:59:30",9,"//И по 100 сверху каждый за зачистку как миниквест, да",162839,null],[162847,"2026-08-16T23:00:07",9,"//Сюда лезть не обязательно было, могли мимо пройти, к основной цели)",130271,null],[163313,"2026-08-17T08:58:43",17,"\"Пора двигаться дальше. До раздвоеной горы сколько еще... Сутки или двое? По карте не понятен масштаб. Ну ладно. Предлагаю со змеями не связываться больше и бежать не оглядываясь с этих топей\"",130271,null],[163314,"2026-08-17T08:59:14",17,"Фауст поднялся после медитации и посмотрел в щель\n\n\"Вылезем, так же как и залезли сюда\"",130271,null],[163317,"2026-08-17T09:02:53",9,"*Ночью снаружи был шум,шумело невероятно от трепыханий крылышек, даже пару залетных змиев залетало к вам сюда, всё же отдохнуть удалось.*\n\n//Да, длинный защитан господа",130271,null],[163392,"2026-08-17T10:25:08",42,"— Фауст. Знаешь что? Я всегда мечтал о питомце змее. Может поможешь? Я тебе даже 50 золотых отсыплю за помощь",130271,null],[163404,"2026-08-17T10:28:56",17,"\"А что делать?\"",130271,null],[163536,"2026-08-17T11:43:21",42,"— ну ты же контрабандист. Думал ты что-то предложишь\n\nЛюц смотрит на Фауста с улыбкой с скрытым подъебоном, как будто сомневается в его навыках контрабанды",130271,null],[163539,"2026-08-17T11:45:01",17,"\"Да я больше руками работаю, а не головой в этих делах. Но вот как найдём источник волшебный может и стану кумекать больше, как деньгу сколотить. Ну вот у меня мешок есть, хватай змеюку туда и комарами корми, авось станет покладистая\"\n\nПротянул мешок Люцу",130271,null],[163557,"2026-08-17T11:59:16",42,"— да ты гений! Споймаем в мешок и со временем приручим! \n\nЛюц хватает мешок и ожидает момента когда он понадобится",163539,null],[163567,"2026-08-17T12:11:57",17,"Они вылезли так же как и залезли Фауст озирается по старонам в поисках змеи для Люца или опасности",130271,null],[163568,"2026-08-17T12:12:04",17,"/r +3 Озирается",130271,null],[163573,"2026-08-17T12:14:08",9,"*Они все так же днём спят на деревьях и скорей всего среагируют на громкий звук.*",163569,null],[163578,"2026-08-17T12:16:49",42,"(Шëпотом) — Фаус, я могу раз в день стать невидимым. Это очень полезная магия, думаю она стоит того чтобы поймать змеюку в мешочек\n\nподкрадывается к дереву готовясь споймать одну змеюку",130271,null],[163585,"2026-08-17T12:19:54",17,"\"А мне что? Пошуметь чутка? Давай по дереву стукну легонько\"",130271,null],[163586,"2026-08-17T12:20:07",9,"//С преимуществом захват, они спят, если не будите",130271,null],[163597,"2026-08-17T12:22:30",42,"// тогда что кидать? Ловкость рук?",163586,null],[163629,"2026-08-17T12:31:50",9,"//Опиши как ты это делаешь и я скажу кто ты что кинуть",163597,null],[163637,"2026-08-17T12:35:12",42,"Подбираясь Люц включает режим анального ассасина и входит в дырочку невидимость, и пытается резким и ловким движением руки схватить змеюку и запихнуть еë в анал мешок",130271,null],[163650,"2026-08-17T12:42:20",9,"//Тогда ловкость твоих обдроченных лапок рук с преимуществом, сл 14 змии неудобно сидят скрученные вокруг веток",163637,null],[163681,"2026-08-17T12:53:23",42,"/roll +d20 +4 фистинг ловкость рук",130271,null],[163685,"2026-08-17T12:53:59",42,"// стопэ. Я же могу использовать свой подарок на др",130271,null],[163686,"2026-08-17T12:54:04",42,"/roll d4",130271,null],[163689,"2026-08-17T12:54:12",42,"// имба",130271,null],[163690,"2026-08-17T12:54:35",9,"//Чётко хватило, описывай и у тебя летающий змий в мешке)",130271,null],[163700,"2026-08-17T12:57:57",42,"Люц схватил змеюку и затащил еë в мешок и после свалил",130271,null],[163721,"2026-08-17T13:02:21",17,"\"Ну... Теперь думаю ты доволен. Только не подноси змейку близко к моему рюкзаку, грифоны наверное и змейками питаются. Хе. Пошли дальше к раздвоеной горе, пок арте это туда\"\n\nУказывая вперед фауст движется к цели",130271,null],[163724,"2026-08-17T13:02:48",9,"*Бьётся в мешке, ты слышишь хруст, кажется хрупкие крылья змия такого не выдержали. Но он жив и в мешке.*",163700,null],[163725,"2026-08-17T13:03:07",42,"// ТЫ ЛОМАЕШЬ МНЕ СЕРДЦЕ!!",163724,null],[163726,"2026-08-17T13:03:23",17,"/Змея скрутилась в узел и задушила сама себя в мешке!",130271,null],[163729,"2026-08-17T13:04:02",9,"//И что, отрастут со временем, не парься",163725,null],[163733,"2026-08-17T13:04:24",9,"//Но крылья реально хрупкие очень)",130271,null],[163796,"2026-08-17T13:20:19",42,"// ладно. Поплакал послушал песни для суицида. Теперь в норме",130271,null],[163799,"2026-08-17T13:20:56",42,"— Более.. \n\nЛюц услышал хруст в мешке\n\n— БЛЯЯЯЯЯЯЯЯ!!!",163721,null],[163800,"2026-08-17T13:21:33",17,"\"Хрупкие какие то создания\"",130271,null],[163801,"2026-08-17T13:21:46",17,"И они двинулись из болот к радвоеной горе",130271,null],[163812,"2026-08-17T13:32:40",9,"// Ну бери:\n\n\"Крылатый Змий\". Статблок змеи но имеет хрупчайшие крылья как у стрекозы, пока они целы имеет скорость полета 50. Прыткая, летая бонус попадания атакой +5 и имеет кд 15, не провоцирует атак. (Крылья сломаны, отрастут достаточно 1 октября этого года)",163799,null],[163813,"2026-08-17T13:34:22",42,"// еБА.. Я прочëл следующего года)",163812,null],[163822,"2026-08-17T13:36:28",9,"//Ну, буду щас горы описывать",130271,null],[164412,"2026-08-17T21:22:58",9,"*Стелится туман, пар, облака. Через долину поднимаясь выше, выбравшись из болота вас ожидают горы. Холодную пустошь греет дыхание, ваше дыхание все еще греет грядущую пустошь.*\n\n*Маштабы не те что на карте, на глаз идти неделю только к месту где долна находиться та самая гора. Переживете ли вы этот поход в драконьи горы...*\n\n*Холод? Может зимнему эладрину частично и плевать на него, но заготовил ли тёплую одежку Люц.*",130271,null],[164413,"2026-08-17T21:23:16",9,"// есще минус рацион с каждого, путь к предгорьям занял хорошо времени",130271,null],[164489,"2026-08-18T10:06:24",42,"Люц не был готов к холоду, но какое счастье что он знает заговор \"управление огнëм\" Поэтому он гуляет с источником тепла в руке",164412,null],[164496,"2026-08-18T10:21:30",9,"*По всё ещё угадывающейся тропе, к камню с надписями. Наставление для охотников или предупреждение вычерченное рунами на черном граните, как на скрижали.*\n\n\"Коли ты жаден, охотник. Берёшь больше чем надо, злой человек. Убивай без причины, тебя убьёт он. Демон ночной, охотник на охотников, большой чёрный волк. За твоею душонкой, прийдёт Амарок.\"",130271,null],[164525,"2026-08-18T11:28:40",17,"\"Конечно не обойдётся без страшной сказочки. Ладно потопали, мы такие , какие мы есть, а кому не нравится, пусть приходят и попробуют нас поменять.\"",130271,null],[164530,"2026-08-18T11:30:29",17,"Фауст синхронно с клоном шагает по каменистой горной тропе. Холод в его крови и он не мёрзнет здесь",130271,null],[164563,"2026-08-18T12:43:23",17,"Он озирается по сторонам высматривая что нибудь интересное или опасное",130271,null],[164564,"2026-08-18T12:43:32",17,"/r +3 Внимание",130271,null],[164566,"2026-08-18T12:47:12",9,"*Ты вступил в говно, если бы не это то не заметил бы следы. Однажды ты встречал подобные, лютоволки, по следам их численность около дюжины, может больше.*",164565,null],[164567,"2026-08-18T12:55:51",17,"\"Куча волчьего говна, Люц. Смотри в оба, они ходят стаями, не дай им окружить себя\"",130271,null],[164568,"2026-08-18T12:56:31",17,"Чистит сапог от говна\n\nФауст находит немного снега и делает жестами формирование воды этой водой отмывает сапог",130271,null],[164581,"2026-08-18T15:12:42",42,"Люц решил в этот раз сам глянуть поточнее",164565,null],[164582,"2026-08-18T15:12:54",42,"/roll 1d20 +4",130271,null],[164584,"2026-08-18T15:13:11",42,"// Hard твой любимый 22",164583,null],[164674,"2026-08-18T17:59:47",9,"*Ты замечаешь кучу говна в которую вступил фауст и крупные волчьи следы, не те что у ободранных шавок в Веспирали, эти опаснее. Их около дюжины на вид здесь пробежало, и примерно в ту сторону куда идёте вы.*",164583,null],[164679,"2026-08-18T18:01:28",9,"*Чуть дальше, уже по снегу следы этих псин сливаются в один ряд, они идут волчьей тропой за вожаком.*",130271,null],[164707,"2026-08-18T18:36:52",42,"— Дружище. Откроем сезон охоты? Судя по тому следу что ты наступил они в той стороне\n\nПоказал пальцем туда в каком направлении находятся волки",164674,null],[164710,"2026-08-18T18:39:46",17,"\"Предлагаю сделать по уму, ты займёшь позицию на дереве. Там же я оставлю ледяного клона, сам я привлеку стаю к твоей засаде, после, поменяюсь местами с клоном. Ледяной демон снизу будет рвать волков, а ты расстреливать сверху. Что скажешь? Это конечно... Не очень чесно по отношению к волкам, но... Нам нужно выжить и пользоваться\"\n\n\nОн стучит по виску пальцем\n\n\"Преимуществом в интеллекте\"",164707,null],[164713,"2026-08-18T18:40:36",9,"//А когда стучали по голове там точно был пустой гулкий звук)",164710,null],[164714,"2026-08-18T18:40:47",9,"// Шучу",130271,null],[164715,"2026-08-18T18:40:48",17,"/ Я поменял)",130271,null],[164777,"2026-08-18T19:09:25",42,"// ыхыхы. Лады. Я тут с вами точно",130271,null],[164783,"2026-08-18T19:10:16",42,"// дайте фаер бол и будет засада ебейшая",164710,null],[164786,"2026-08-18T19:11:19",42,"— Ну вот тот Фауст которого я знаю. Хороший стратег и контр бандист\n\nЛюц пошëл делать так как сказал ему его товарищ",164710,null],[164790,"2026-08-18T19:12:17",17,"\"Знаешь... Со змеем могло все кончится плохо. Ты меня спас чего греха таить. Больше не хочу проигрывать ни монстрам ни людям. Мне ещё многое нужно сделать\"",164786,null],[164797,"2026-08-18T19:14:10",42,"— у всех у нас не законченные дела. А дать тебе погибнуть, это было бы приступление против моих ценностей. Да и уверен, ты бы тоже самое сделал бы на моëм месте",164790,null],[164800,"2026-08-18T19:14:43",17,"\"Да.\"",130271,null],[164801,"2026-08-18T19:14:44",17,"Фауст ищет крепкую сосну повыше",130271,null],[164802,"2026-08-18T19:14:59",17,"\"Вот тут отличное место для засады. Я привлеку их кровью\"",130271,null],[164806,"2026-08-18T19:15:22",17,"На крепкой ветке Фауст создаёт ледяного клона он замер в ожидании",130271,null],[164825,"2026-08-18T19:20:06",42,"Люц же занял ту же позицию где и его клон",130271,null],[164830,"2026-08-18T19:24:19",17,"Фауст пошел недалеко от засады по следам волков \n\nРезанул ладонь и расплескал кровь по снегу",130271,null],[164853,"2026-08-18T19:36:55",9,"//Выживание сл 12",164830,null],[164893,"2026-08-18T20:06:02",17,"/r +2 Выживание",130271,null],[164899,"2026-08-18T20:07:55",9,"*Хрен знает, но окрестности не выглядят так словно волки рядом, а ты уже слишком далеко от места засады.*",164894,null],[164903,"2026-08-18T20:11:37",17,"\"Волки далеко ушли видимо, не нападают.\"",130271,null],[164904,"2026-08-18T20:12:08",17,"Фауст решает стучать по стволу сосны стальной перчаткой \n\nМожет на звук придут",130271,null],[164906,"2026-08-18T20:14:18",9,"*Ничего, не слышно чтобы они пёрлись сюда. Чтобы устроить охоту на них, наверное прийдется догонять.*",130271,null],[164921,"2026-08-18T20:30:22",17,"\"Стая ушла далеко, плакала наша засада. Ладно. Слезай, Люц. Если нападут на нас по пути то используем смекалочку и преимущество высоты.\"",130271,null],[164993,"2026-08-18T22:22:14",42,"— пхпхпхп.. Извини Фауст, но после того как мы убили короля змей, мне кажется волки не будут более для нас чем закуска\n\nЛюц слез с дерева",164921,null],[164995,"2026-08-18T22:24:47",17,"\"Обычные волки столько не срут, Люц. Эти лютые гады\"",130271,null],[164997,"2026-08-18T22:27:16",42,"— хочешь сказать лютоволки? Если так, то стая будет сложнее чем даже тройка таких королей змей",130271,null],[165504,"2026-08-19T20:11:38",9,"//Ладно, что вы делаете, будете пытаться обойти стаю или сами с ней столкнётесь 😏👌",130271,null],[165519,"2026-08-19T20:19:04",17,"\"Если следы стаи идут к расколотой скале, значит мы с ними столкнемся. Но будем готовы. \"",130271,null],[165520,"2026-08-19T20:19:26",17,"Фауст приобрел в сторону разбитой скалы",130271,null],[165521,"2026-08-19T20:19:47",17,"И рядом призван ледяной клон",130271,null],[165606,"2026-08-19T22:11:00",9,"//Бля, я щас нажимаю сюда и думаю какого фига с Люпеном делает ледяной клон 😂👍",165521,null],[165607,"2026-08-19T22:13:52",17,"/ ))",130271,null],[165608,"2026-08-19T22:14:05",17,"/ Мы тут подзастряли",130271,null],[165609,"2026-08-19T22:14:13",17,"/ Жалко конечно",130271,null],[165610,"2026-08-19T22:14:18",17,"/ Но такова судьба",130271,null],[167820,"2026-08-22T18:04:44",9,"// @dunchev @Jak_Zak я вас отпускаю с квеста, совсем прошло настроение его вести, простите. Получите дополнительно ещё 100 опыта и 50 золотых каждый. А так, не знаю, можете просто сразу идти искать новые или еще что. Назревает гоблинская ярмарка, период когда будет прилавок в котором маг предметы будут меняться каждый день, это вдвое дороже (торговаться еще можно) но не ждать 30 лет нужный предмет из магазина)",130271,null]]);
